window.LICEY_DATA = {"art": [{"id": "a0", "title": "Как смотреть на искусство", "period": "Азбука", "intro": [], "traits": ["Жанры: портрет, пейзаж, натюрморт, историческая, бытовая и религиозная живопись", "Виды: живопись, графика, скульптура, архитектура", "Техники: фреска, темпера, масло, акварель, мозаика", "Перспектива — приём, создающий иллюзию глубины на плоскости", "Светотень (кьяроскуро) — лепка объёма светом и тенью"], "works": [], "quiz": [{"q": "Как называется жанр живописи, где изображена природа?", "o": ["Натюрморт", "Пейзаж", "Портрет", "Марина"], "a": 1, "e": "Пейзаж — изображение природы. Марина — его разновидность: морской пейзаж."}, {"q": "Что такое натюрморт?", "o": ["Изображение неживых предметов: цветов, посуды, фруктов", "Портрет умершего человека", "Картина на мифологический сюжет", "Роспись по сырой штукатурке"], "a": 0, "e": "Nature morte по-французски — «мёртвая природа»: композиция из предметов."}, {"q": "Роспись по сырой штукатурке называется…", "o": ["Темпера", "Мозаика", "Фреска", "Гравюра"], "a": 2, "e": "Fresco — «свежий»: краски впитываются в сырую штукатурку и живут веками."}, {"q": "Приём, который создаёт иллюзию глубины на плоской картине:", "o": ["Перспектива", "Контраст", "Орнамент", "Колорит"], "a": 0, "e": "Линейная перспектива: параллельные линии сходятся в точке на горизонте."}], "why": ["Экскурсоводы, путеводители и подписи в музеях говорят на своём языке: жанр, фреска, темпера, перспектива. Здесь собраны главные термины, каждый с примером. Разберитесь с ними один раз, и любая картина дальше будет читаться легче."], "groups": [{"h": "Какое бывает искусство", "p": "Сначала главное деление: картина, рисунок, статуя или здание. Это виды изобразительного искусства.", "items": [{"t": "Живопись", "d": "Изображение красками на холсте, доске или стене.", "c": "Леонардо да Винчи. «Мона Лиза»", "more": ["Леонардо да Винчи писал «Мону Лизу» больше десяти лет, начиная примерно с 1503 года, и так и не отдал её заказчику. Скорее всего, на портрете Лиза Герардини, жена флорентийского торговца шёлком.", "Сила живописи в цвете и свете. Посмотрите на лицо: контуры будто растворены в дымке, поэтому выражение кажется то печальным, то улыбающимся. Леонардо добивался этого десятками тончайших полупрозрачных слоёв краски. Этот приём называют сфумато, о нём будет в главе про Возрождение.", "В 1911 году картину украли из Лувра, и два года её искала полиция всего мира. Именно после этой истории «Мона Лиза» стала самой известной картиной на свете."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mona_Lisa,_by_Leonardo_da_Vinci,_from_C2RMF_retouched.jpg", "lic": "Public domain", "by": "Leonardo da Vinci", "src": "media/img/b6403bc945-1000.webp", "w": 1000, "h": 1490, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Графика", "d": "Рисунок и печатная гравюра: карандаш, тушь, уголь.", "c": "Дюрер. «Носорог», гравюра. Он рисовал по описанию, ни разу не видев зверя", "more": ["В 1515 году в Лиссабон привезли из Индии живого носорога, первого в Европе за тысячу лет. Немецкий художник Альбрехт Дюрер его ни разу не видел. Он сделал изображение по чужому письму и наброску, поэтому у зверя панцирь, похожий на рыцарские латы, и лишний рожок на спине.", "Это гравюра. Рисунок вырезают на деревянной доске, покрывают краской и печатают на бумаге, как штампом. С одной доски можно сделать сотни оттисков. Поэтому «Носорог» разошёлся по всей Европе, и почти двести лет даже в учебниках зоологии носорогов рисовали именно так."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer,_The_Rhinoceros,_1515,_NGA_47903.jpg", "lic": "CC0", "by": "Albrecht Dürer", "src": "media/img/b96612112b-1000.webp", "w": 1000, "h": 785, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Albrecht_D%C3%BCrer%2C_The_Rhinoceros%2C_1515%2C_NGA_47903.jpg/1280px-Albrecht_D%C3%BCrer%2C_The_Rhinoceros%2C_1515%2C_NGA_47903.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Скульптура", "d": "Объёмная фигура из камня, бронзы, дерева или глины.", "c": "Венера Милосская, Древняя Греция", "more": ["Статую нашёл крестьянин в 1820 году на греческом острове Милос, отсюда название. Её создали около 130 года до нашей эры. Это богиня любви Афродита, римляне называли её Венерой.", "Руки были утрачены ещё до находки. Как она их держала, спорят до сих пор: возможно, в руке было яблоко. В отличие от картины, скульптуру обходят по кругу, и с каждой стороны она выглядит по-новому. Скульптор продумывает все точки зрения сразу. Сейчас Венера стоит в Лувре."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg", "lic": "Public domain", "by": "Unknown artistUnknown artist", "src": "media/img/c5268119fe-1000.webp", "w": 1000, "h": 1678, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Venus_de_Milo_Louvre_Ma399_n4.jpg/1280px-Venus_de_Milo_Louvre_Ma399_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Архитектура", "d": "Искусство проектировать и строить здания.", "c": "Парфенон в Афинах", "more": ["Парфенон построили в Афинах с 447 по 432 год до нашей эры как храм богини Афины, покровительницы города. Внутри стояла её статуя высотой около 12 метров, покрытая золотом и слоновой костью.", "В нём почти нет прямых линий. Колонны слегка наклонены внутрь и чуть утолщены посередине, а основание немного выгнуто вверх. Дело в том, что издалека идеально прямые линии кажутся провисшими. Греческие архитекторы рассчитали этот обман зрения и исправили его заранее.", "В 1687 году во время войны с венецианцами турки хранили в храме порох. Снаряд попал внутрь, порох взорвался, и Парфенон остался без крыши."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Parthenon_in_Athens.jpg", "lic": "CC BY 2.0", "by": "Steve Swayne", "src": "media/img/72aa7cef8d-1000.webp", "w": 1000, "h": 703, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/da/The_Parthenon_in_Athens.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}, {"h": "Что изображают: жанры", "p": "Жанр отвечает на вопрос «что изображено?».", "items": [{"t": "Портрет", "d": "Изображение конкретного человека.", "c": "Вермеер. «Девушка с жемчужной серёжкой»", "more": ["Ян Вермеер жил в голландском городе Делфт в XVII веке и написал всего около 35 картин. Девушка на этой картине, скорее всего, не заказчица. Голландцы называли такие работы «тронье»: этюд головы в необычном костюме, чтобы показать характер и мастерство.", "Посмотрите на свет: блики на губах и в глазах, а жемчужина нарисована всего двумя мазками. Сверху яркий блик, снизу отражение белого воротника. Синюю краску для тюрбана делали из толчёного лазурита, камня, который возили из Афганистана. Она стоила дороже золота."], "img": {"page": "https://commons.wikimedia.org/wiki/File:1665_Girl_with_a_Pearl_Earring.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/1f01b6178c-1000.webp", "w": 1000, "h": 1184, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/1280px-1665_Girl_with_a_Pearl_Earring.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Пейзаж", "d": "Изображение природы.", "c": "Констебл. «Телега для сена»", "more": ["Джон Констебл всю жизнь писал одни и те же места: деревни на реке Стур в Англии, где он вырос. На картине 1821 года телега переезжает реку вброд. Так делали специально, чтобы деревянные колёса намокли и не рассыхались, а лошади заодно напились.", "В то время пейзаж считали второсортным жанром, гораздо выше ценились исторические и библейские сюжеты. Констебл доказывал, что обычная природа достойна большого холста. В Англии картину не купили, а на выставке в Париже в 1824 году она получила золотую медаль и вдохновила французских художников, будущих импрессионистов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:John_Constable_-_The_Hay_Wain_(1821).jpg", "lic": "Public domain", "by": "John Constable", "src": "media/img/8ec3e1f802-1000.webp", "w": 1000, "h": 690, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/John_Constable_-_The_Hay_Wain_%281821%29.jpg/1280px-John_Constable_-_The_Hay_Wain_%281821%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Марина", "d": "Морской пейзаж.", "c": "Айвазовский. «Девятый вал»", "more": ["Слово «марина» происходит от латинского mare, «море». Морские пейзажи особенно любили в странах, которые жили мореплаванием и торговлей: в Голландии, Англии, позже в России.", "Иван Айвазовский написал около шести тысяч картин, почти все о море. При этом с натуры он море не писал: наблюдал, запоминал и работал по памяти в мастерской. Он говорил, что движение стихий нельзя поймать кистью с натуры, его можно только запомнить. История «Девятого вала» ниже, в разделе «Произведения»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Hovhannes Aivazovsky (1817 - 1900) – painter (Russian) Born in Rossiiskaya imper", "src": "media/img/14baff2254-1000.webp", "w": 1000, "h": 672, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg/1280px-Hovhannes_Aivazovsky_-_The_Ninth_Wave_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Натюрморт", "d": "Композиция из предметов: посуда, еда, цветы.", "c": "Хеда. «Завтрак»", "more": ["Виллем Хеда из голландского Харлема писал «завтраки»: недоеденный пирог, опрокинутый бокал, лимон с наполовину снятой кожурой. Почти всё выдержано в серебристо-коричневых тонах.", "Для голландцев XVII века такие картины были с подтекстом. Недопитое вино, погасшая свеча, часы напоминали, что жизнь проходит быстро, а богатство не вечно. Заодно художник показывал мастерство: попробуйте нарисовать отражение окна в изогнутом стекле бокала."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Willem_Claesz._Heda_-_Breakfast_Still-Life_-_WGA11232.jpg", "lic": "Public domain", "by": "Willem Claesz. Heda", "src": "media/img/a187280085-1000.webp", "w": 1000, "h": 744, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/d7/Willem_Claesz._Heda_-_Breakfast_Still-Life_-_WGA11232.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Бытовой жанр", "d": "Сцены повседневной жизни.", "c": "Брейгель. «Крестьянская свадьба»", "more": ["Питер Брейгель написал «Крестьянскую свадьбу» около 1567 года. Невесту найти несложно: она сидит под зелёной тканью, над её головой бумажная корона. А вот где жених, спорят до сих пор, его на картине явно не видно.", "До Брейгеля крестьян почти не делали главными героями. Он вместе с другом ходил на деревенские праздники, переодевшись крестьянином, и наблюдал. Двое мужчин несут миски с кашей на снятой с петель двери, мальчик в огромной шапке облизывает тарелку. Так выглядела настоящая жизнь Фландрии XVI века."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Pieter Bruegel the Elder", "src": "media/img/f9e9cbaf49-1000.webp", "w": 1000, "h": 691, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg/1280px-Pieter_Bruegel_the_Elder_-_Peasant_Wedding_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Историческая картина", "d": "Важные события прошлого: битвы, договоры, коронации.", "c": "Веласкес. «Сдача Бреды»: побеждённый отдаёт ключи от города", "more": ["В 1625 году испанская армия после долгой осады взяла голландский город Бреду. Через десять лет придворный художник Диего Веласкес написал момент сдачи. Голландский командир протягивает ключи от города, а испанский генерал Спинола не даёт ему встать на колени и дружески кладёт руку на плечо.", "Справа строй испанцев с длинными пиками, их так много, что картину иногда называют «Копья». Веласкес показал не торжество победителя, а уважение к побеждённому. Историческая картина считалась тогда самым почётным жанром: она учила зрителя примерами из прошлого."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Velazquez-The_Surrender_of_Breda.jpg", "lic": "Public domain", "by": "Diego Velázquez", "src": "media/img/c2f87ed612-1000.webp", "w": 1000, "h": 825, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Velazquez-The_Surrender_of_Breda.jpg/1280px-Velazquez-The_Surrender_of_Breda.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Чем рисуют: техники", "p": "Техника отвечает на вопрос «чем и на чём?». От неё зависит, как произведение выглядит и сколько проживёт.", "items": [{"t": "Фреска", "d": "Роспись по сырой штукатурке.", "c": "Джотто. Фреска в часовне в Падуе, около 1305 года", "more": ["Слово «фреска» происходит от итальянского fresco, «свежий». Художник покрывает сырой штукатуркой ровно тот участок стены, который успеет расписать за день. Краска впитывается и, высыхая, становится частью стены. Исправить ошибку можно, только сбив штукатурку и начав заново.", "Около 1305 года Джотто расписал часовню Скровеньи в Падуе: почти сорок сцен из жизни Христа и Марии. На этой фреске ученики оплакивают Христа. Люди склоняются над телом, ангелы в небе рыдают, а две фигуры сидят к нам спиной. Так живо и по-человечески горе до Джотто не изображали. С него начинается путь к Возрождению."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Giotto_-_Scrovegni_-_-36-_-_Lamentation_(The_Mourning_of_Christ)_adj.jpg", "lic": "Public domain", "by": "Giotto", "src": "media/img/1a7c11dd20-1000.webp", "w": 1000, "h": 925, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Giotto_-_Scrovegni_-_-36-_-_Lamentation_%28The_Mourning_of_Christ%29_adj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Мозаика", "d": "Изображение из кусочков стекла и камня.", "c": "Императрица Феодора. Равенна, VI век", "more": ["Мозаику набирают из маленьких кубиков цветного стекла, которые называют смальтой. Для золотого фона внутрь стеклянного кубика запаивали тонкую золотую фольгу. Кубики ставили под разным наклоном, чтобы они по-разному ловили свет, и стены мерцали при свечах.", "Эта мозаика в церкви Сан-Витале в итальянском городе Равенна сделана около 547 года. Византийская императрица Феодора несёт в храм золотую чашу. Византийцы любили мозаику ещё и потому, что она не выцветает: этим цветам почти полторы тысячи лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Mosaic_of_Theodora_-_Basilica_San_Vitale_(Ravenna).jpg", "lic": "CC BY-SA 4.0", "by": "Petar Milošević", "src": "media/img/b7c048832f-1000.webp", "w": 1000, "h": 592, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Mosaic_of_Theodora_-_Basilica_San_Vitale_%28Ravenna%29.jpg/1280px-Mosaic_of_Theodora_-_Basilica_San_Vitale_%28Ravenna%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Темпера", "d": "Краски на яичном желтке. Ими писали иконы.", "c": "Андрей Рублёв. «Троица»", "more": ["Художник растирал цветной порошок и смешивал его с яичным желтком и водой. Такая краска сохнет за минуты, поэтому писали тонкими слоями, один поверх другого. Основой служила деревянная доска, покрытая белым левкасом, это смесь мела и клея.", "Андрей Рублёв написал «Троицу» в начале XV века для Троице-Сергиева монастыря. На ней три ангела, которые пришли в гости к Аврааму, и одновременно образ Бога в трёх лицах. Фигуры вписаны в круг, без начала и конца: так Рублёв показал согласие и единство. Сейчас икона хранится в Третьяковской галерее."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Angelsatmamre-trinity-rublev-1410.jpg", "lic": "Public domain", "by": "Andrei Rublev", "src": "media/img/567e733b41-1000.webp", "w": 1000, "h": 1245, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Angelsatmamre-trinity-rublev-1410.jpg/1280px-Angelsatmamre-trinity-rublev-1410.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Масло", "d": "Краски на растительном масле.", "c": "Ван Эйк. В зеркале на стене видна вся комната", "more": ["Масляные краски сохнут медленно, по нескольку дней. Их можно смешивать прямо на картине, накладывать прозрачные слои один на другой и писать мельчайшие детали. Нидерландские художники XV века довели эту технику до совершенства, и потом она распространилась по всей Европе.", "Посмотрите на выпуклое зеркало на стене этого портрета 1434 года. В нём отражается вся комната со спины и ещё двое людей в дверях. Один из них, вероятно, сам художник. Над зеркалом надпись на латыни: «Ян ван Эйк был здесь». Такую точность до масляных красок получить было невозможно."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Eyck_-_Arnolfini_Portrait.jpg", "lic": "Public domain", "by": "Jan van Eyck", "src": "media/img/fc05e7255e-1000.webp", "w": 1000, "h": 1368, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/1280px-Van_Eyck_-_Arnolfini_Portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Акварель", "d": "Прозрачные краски на воде, по бумаге.", "c": "Дюрер. «Заяц»", "more": ["Акварель разводят водой, и сквозь слой краски просвечивает бумага. Поэтому белого цвета в акварели обычно нет: белым остаётся сама бумага. Ошибку почти невозможно исправить, работать нужно быстро и точно.", "Дюрер нарисовал «Зайца» в 1502 году. Шерсть сделана тысячами тонких мазков, а в глазу зайца отражается окно мастерской. Рисунок очень хрупкий: его хранят в Вене и показывают публике редко, чтобы краски не выцвели на свету."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer_-_Hare,_1502_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Albrecht Dürer", "src": "media/img/81fb234d1c-1000.webp", "w": 1000, "h": 1105, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg/1280px-Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Как художник обманывает глаз: приёмы", "p": "Картина плоская, но мы видим в ней глубину и объём. Этого добиваются особыми приёмами.", "items": [{"t": "Перспектива", "d": "Иллюзия глубины: дальнее меньше, линии сходятся в одну точку.", "c": "Перуджино. Плиты площади ведут взгляд к храму", "more": ["Линейную перспективу придумали во Флоренции около 1420 года. Архитектор Филиппо Брунеллески показал, что все параллельные линии, которые уходят вдаль, на картине должны сходиться в одной точке на горизонте. С тех пор художники строят пространство почти по законам геометрии.", "Перуджино расписал эту стену Сикстинской капеллы в Риме в 1482 году. Плиты площади нарисованы как расчерченная сетка, и все её линии сходятся к двери храма в центре. Наш взгляд сам идёт туда. Фигуры вдали становятся меньше, и плоская стена превращается в огромную площадь."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Christ_Handing_the_Keys_to_St._Peter_by_Pietro_Perugino.jpg", "lic": "Public domain", "by": "Pietro Perugino", "src": "media/img/d566659d89-1000.webp", "w": 1000, "h": 619, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Christ_Handing_the_Keys_to_St._Peter_by_Pietro_Perugino.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Светотень", "d": "Объём через контраст света и тени.", "c": "Караваджо. Лица и руки выступают из темноты", "more": ["Итальянцы называли этот приём кьяроскуро, буквально «светло-тёмное». Резкий переход от света к тени делает предметы объёмными, как будто их можно потрогать. Художник Караваджо довёл приём до предела: фон у него почти чёрный, а свет падает узким лучом, как от прожектора.", "На картине 1601 года двое учеников ужинают со случайным странником и вдруг узнают в нём воскресшего Христа. Один вскакивает со стула, другой раскидывает руки. Свет выхватывает лица и руки, и кажется, что персонажи вот-вот выйдут из картины к нам. Корзина с фруктами стоит на самом краю стола и, кажется, сейчас упадёт."], "img": {"page": "https://commons.wikimedia.org/wiki/File:1602-3_Caravaggio,Supper_at_Emmaus_National_Gallery,_London.jpg", "lic": "Public domain", "by": "Caravaggio", "src": "media/img/30559d6da5-1000.webp", "w": 1000, "h": 711, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/1602-3_Caravaggio%2CSupper_at_Emmaus_National_Gallery%2C_London.jpg/1280px-1602-3_Caravaggio%2CSupper_at_Emmaus_National_Gallery%2C_London.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a1", "title": "Первобытность и Древний Египет", "period": "40 000 лет до н. э. — IV век до н. э.", "intro": [], "traits": ["Наскальная живопись: охра, уголь, звери в движении", "Египетский канон: голова в профиль, плечи анфас", "Размер фигуры = её важность", "Монументальность: пирамиды, сфинкс, храмы", "Искусство служит культу мёртвых и вечности"], "works": [{"t": "Росписи пещеры Ласко", "a": "Неизвестные мастера (Франция)", "y": "около 17 000 лет до н. э.", "d": "Сотни быков, лошадей и оленей, нарисованных углём и глиной. Пещеру нашли подростки в 1940 году.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg", "lic": "Public domain", "by": "EU", "src": "media/img/fcc28a34f4-1000.webp", "w": 1000, "h": 656, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Lascaux_painting.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["В 1940 году четверо подростков во Франции искали подземный ход и случайно провалились в пещеру. На стенах они увидели сотни нарисованных зверей: быков, лошадей, оленей. Рисункам около 17 000 лет.", "Художники работали в полной темноте, при свете каменных ламп с животным жиром. Краски делали из красной и жёлтой глины и угля. Часть краски выдували через полую косточку, как из баллончика.", "После открытия в пещеру пошли тысячи туристов. От их дыхания на стенах начала расти плесень, и рисунки стали портиться. В 1963 году пещеру закрыли. Сейчас посетители смотрят точную копию, построенную рядом."]}, {"t": "Бюст Нефертити", "a": "Скульптор Тутмос", "y": "около 1345 г. до н. э.", "d": "Жена фараона Эхнатона. Эпоха Эхнатона — редкий момент, когда египетский канон стал мягче и живее.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Nofretete_Neues_Museum.jpg", "lic": "CC BY-SA 3.0", "by": "Philip Pikart", "src": "media/img/e03c2fb10a-1000.webp", "w": 1000, "h": 1464, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Nofretete_Neues_Museum.jpg/1280px-Nofretete_Neues_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Нефертити была женой фараона Эхнатона. Бюст сделал скульптор Тутмос около 1345 года до нашей эры. Его нашли в 1912 году в развалинах мастерской Тутмоса.", "Скульптура сделана из известняка, покрыта тонким слоем гипса и раскрашена. Посмотрите на глаза: правый вставлен из горного хрусталя, а левый так и остался пустым. Почему, никто точно не знает. Может быть, это была учебная модель для других мастеров.", "Эхнатон хотел поклоняться одному богу, солнцу, и при нём искусство стало мягче и живее, чем обычно в Египте. Сейчас бюст хранится в Берлине."]}, {"t": "Пирамиды Гизы", "a": "Архитекторы фараонов IV династии", "y": "около 2500 г. до н. э.", "d": "Гробницы фараонов Хуфу, Хафра и Менкаура. Пирамида Хеопса — единственное сохранившееся из семи чудес света.", "img": {"page": "https://commons.wikimedia.org/wiki/File:All_Gizah_Pyramids.jpg", "lic": "CC BY-SA 2.0", "by": "Ricardo Liberato", "src": "media/img/dedccf333e-1000.webp", "w": 1000, "h": 665, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/All_Gizah_Pyramids.jpg/1280px-All_Gizah_Pyramids.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Три большие пирамиды построили для трёх фараонов: Хуфу (его ещё называют Хеопсом), его сына Хафра и внука Менкаура. Самая большая, пирамида Хуфу, появилась около 2560 года до нашей эры. Её строили примерно двадцать лет.", "Она сложена из двух миллионов каменных блоков. Каждый весит в среднем как два легковых автомобиля. Высота была 146 метров, почти как пятидесятиэтажный дом. Почти четыре тысячи лет это было самое высокое здание на Земле.", "Раньше думали, что пирамиды строили рабы. Но рядом нашли посёлок строителей с пекарнями и могилами. Оказалось, работали обычные египтяне за еду и плату. Камни тянули на санях по дорогам и насыпям, а песок поливали водой, чтобы сани легче скользили.", "Сначала пирамиды были облицованы гладким белым камнем и блестели на солнце. Потом облицовку разобрали на постройки, и стали видны ступеньки из блоков."]}, {"t": "Маска Тутанхамона", "a": "Египетские мастера", "y": "около 1323 г. до н. э.", "d": "Золото, лазурит, стекло. Маска закрывала лицо мумии юного фараона, гробницу которого нашли нетронутой в 1922 году.", "img": {"page": "https://commons.wikimedia.org/wiki/File:CairoEgMuseumTaaMaskMostlyPhotographed.jpg", "lic": "Public domain", "by": "Roland Unger", "src": "media/img/52271ee97b-1000.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/CairoEgMuseumTaaMaskMostlyPhotographed.jpg/1280px-CairoEgMuseumTaaMaskMostlyPhotographed.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Тутанхамон стал фараоном в девять лет и умер примерно в девятнадцать. Великим правителем он не был, зато сегодня его знает весь мир.", "Его гробница была маленькой и спрятанной, поэтому грабители её не нашли. В 1922 году её открыл англичанин Говард Картер. Внутри было больше пяти тысяч вещей: колесницы, мебель, украшения, игры.", "Мумию положили в три гроба, вложенных друг в друга, как матрёшка. Два внешних деревянные, покрыты золотом, а самый маленький, внутренний, отлит из чистого золота. Маска была надета прямо на голову мумии внутри этого золотого гроба. Сама маска сделана из золота весом больше десяти килограммов и украшена синим камнем лазуритом и цветным стеклом. Египтяне верили, что золото не тускнеет, как и тело бога."]}], "quiz": [{"q": "Как изображали человека по египетскому канону?", "o": ["Полностью в профиль", "Голова и ноги в профиль, плечи анфас", "Полностью анфас", "Со спины"], "a": 1, "e": "Так каждая часть тела видна в самом «понятном» ракурсе."}, {"q": "Для чего в первую очередь служило искусство Египта?", "o": ["Для украшения жилищ", "Для обеспечения вечной жизни после смерти", "Для торговли", "Для развлечения"], "a": 1, "e": "Гробницы, статуи и росписи помогали душе жить в вечности."}, {"q": "Чем рисовали первобытные художники?", "o": ["Масляными красками", "Охрой и углём", "Акварелью", "Темперой на яйце"], "a": 1, "e": "Природные пигменты: охра (красная и жёлтая глина), уголь, мел."}], "why": ["Египтяне создали одну из первых в мире систем письма, первые огромные каменные постройки и правила рисования, которые не менялись почти три тысячи лет. Их сфинксов и обелиски потом повторяли повсюду, два настоящих египетских сфинкса стоят даже на набережной Невы в Петербурге. А пещерные рисунки показывают, что человек начал рисовать задолго до того, как научился писать."], "groups": [{"h": "Первые художники", "p": "Пещерные рисунки находят по всему миру. Краски делали из глины и угля.", "items": [{"t": "Пещера Ласко", "d": "Сотни зверей, около 17 000 лет назад.", "c": "Франция", "more": ["Около 17 000 лет назад охотники нарисовали в пещере на юге Франции около 600 животных и вырезали на стенах ещё полторы тысячи изображений. Работали при свете каменных светильников с животным жиром.", "Краски делали из охры, это красная и жёлтая глина, и из угля. Иногда краску выдували через полую кость прямо на стену. Зачем рисовали, точно неизвестно. Возможно, это были обряды перед охотой или рассказы о ней. Как пещеру нашли, читайте в разделе «Произведения»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg", "lic": "Public domain", "by": "EU", "src": "media/img/fcc28a34f4-1000.webp", "w": 1000, "h": 656, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1e/Lascaux_painting.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Пещера Шове", "d": "Около 36 000 лет. Объём за счёт выступов скалы.", "c": "Львы на охоте", "more": ["Пещеру Шове во Франции нашли в 1994 году. Её рисункам около 36 000 лет, вдвое больше, чем в Ласко. Здесь больше всего хищников: львы, медведи, шерстистые носороги.", "Художник выбирал выступы и выпуклости скалы, чтобы спина или голова зверя выглядели объёмными. Некоторые звери нарисованы с несколькими парами ног, словно бегут. Это похоже на первую в истории попытку показать движение."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Lions_painting,_Chauvet_Cave_(museum_replica).jpg", "lic": "Public domain", "by": "HTO", "src": "media/img/1a1d14f43b-1000.webp", "w": 1000, "h": 854, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Lions_painting%2C_Chauvet_Cave_%28museum_replica%29.jpg/1280px-Lions_painting%2C_Chauvet_Cave_%28museum_replica%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Первые статуэтки", "d": "Фигурки-обереги из камня и кости.", "c": "«Венера Виллендорфская», 11 см, около 25 000 лет", "more": ["Фигурку нашли в 1908 году в Австрии у деревни Виллендорф. Высота всего 11 сантиметров, она помещается в ладони. Её вырезали из известняка около 25 000 лет назад и раскрасили красной охрой.", "Лица у неё нет, голова покрыта как будто косами. Учёные считают, что это символ плодородия и благополучия, оберег, который носили с собой. Название «Венера» дали археологи в шутку, в честь римской богини красоты."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_of_Willendorf_frontview_retouched_2.jpg", "lic": "CC BY 2.5", "by": "User:MatthiasKabel", "src": "media/img/12389dba14-1000.webp", "w": 1000, "h": 1644, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Venus_of_Willendorf_frontview_retouched_2.jpg/1280px-Venus_of_Willendorf_frontview_retouched_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Как узнать египетское искусство", "p": "Если видите эти признаки, перед вами почти наверняка Египет.", "items": [{"t": "Голова сбоку, плечи спереди", "d": "Главное правило египетского канона.", "c": "Небамун охотится на птиц. Роспись гробницы", "more": ["Небамун был писцом, который вёл учёт зерна в храме. Около 1350 года до нашей эры его гробницу расписали сценами счастливой жизни. Здесь он охотится на птиц в зарослях папируса вместе с женой и дочерью, а его кот ловит добычу.", "Египтяне рисовали не то, что видит глаз в одно мгновение, а то, как предмет устроен. Голова лучше узнаётся сбоку, глаз и плечи спереди, ноги сбоку. Фигура выглядит необычно, зато в ней есть всё. Египтяне верили, что изображение будет жить вместо человека в загробном мире, поэтому ни одна часть тела не должна была потеряться."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Tomb_of_Nebamun.jpg", "lic": "Public domain", "by": "anonymous", "src": "media/img/e75471c9b9-1000.webp", "w": 1000, "h": 852, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Tomb_of_Nebamun.jpg/1280px-Tomb_of_Nebamun.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Кто важнее, тот крупнее", "d": "Размер фигуры показывает её важность.", "c": "Палетка Нармера, около 5000 лет", "more": ["Каменная палетка сделана около 3100 года до нашей эры. Это одна из первых записей истории: царь Нармер объединил Верхний и Нижний Египет в одно государство.", "Нармер замахивается булавой на врага, он почти вдвое выше всех. За ним маленький слуга несёт его сандалии. Размер здесь показывает не расстояние, как в перспективе, а важность. Этот приём египтяне сохранили на три тысячи лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Narmer_palette_(obverse).jpg", "lic": "Public domain", "by": "anonymous", "src": "media/img/f78c1b74f9-1000.webp", "w": 1000, "h": 1446, "remote": "https://upload.wikimedia.org/wikipedia/commons/5/57/Narmer_palette_%28obverse%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Рисунки рядом с письменами", "d": "Иероглифы подписывают, кто изображён и что происходит.", "c": "«Книга мёртвых». Сердце умершего взвешивают на весах", "more": ["«Книга мёртвых» это свиток папируса с заклинаниями, который клали в гробницу. Он подсказывал умершему, как пройти через загробный мир. Этот свиток сделан для писца Хунефера около 1300 года до нашей эры.", "На картинке загробный суд. Слева бог с головой шакала Анубис ведёт Хунефера к весам. На одной чаше лежит сердце человека, на другой перо богини правды Маат. Египтяне верили, что в сердце хранится память обо всех поступках. Если сердце окажется тяжелее пера, человек жил нечестно, и его съест чудовище Амамат с головой крокодила, которое ждёт у весов.", "Бог мудрости Тот с головой птицы ибиса записывает результат. Сердце Хунефера оказалось лёгким, и справа его ведут к Осирису, владыке загробного мира. Иероглифы над фигурами это подписи и тексты молитв. В Египте изображение и письмо всегда шли рядом, ведь сами иероглифы тоже маленькие рисунки."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Book_of_the_Dead_of_Hunefer_sheet_3.jpg", "lic": "Public domain", "by": "Hunefer", "src": "media/img/62d67ae425-1000.webp", "w": 1000, "h": 457, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Book_of_the_Dead_of_Hunefer_sheet_3.jpg/1280px-Book_of_the_Dead_of_Hunefer_sheet_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Огромные каменные постройки", "d": "Пирамиды, храмы и сфинксы, рассчитанные на вечность.", "c": "Большой сфинкс в Гизе", "more": ["Большой сфинкс вырезан прямо в скале около 2500 года до нашей эры. Его длина 73 метра, высота 20. У него тело льва, символ силы, и голова фараона, скорее всего Хафры, чья пирамида стоит рядом.", "Тысячи лет сфинкса заносило песком по самую шею, и в древности его не раз откапывали. Нос отбит, когда и кем, точно неизвестно. Сфинкс сторожил дорогу к пирамидам. Его размеры должны были показать мощь фараона и вечность его власти."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Great_Sphinx_(%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84).jpg", "lic": "CC BY-SA 4.0", "by": "Petar Milošević", "src": "media/img/4acef234c4-1000.webp", "w": 1000, "h": 646, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Great_Sphinx_%28%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84%29.jpg/1280px-Great_Sphinx_%28%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%87%D9%88%D9%84%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a2", "title": "Античность: Греция и Рим", "period": "VIII век до н. э. — V век н. э.", "intro": [], "traits": ["Человек — мера всех вещей", "Идеальные пропорции и гармония", "Контрапост — живая поза с опорой на одну ногу", "Ордера в архитектуре: дорический, ионический, коринфский", "Рим: реалистичный портрет, арки, купола"], "works": [{"t": "Дискобол", "a": "Мирон (римская копия)", "y": "около 450 г. до н. э.", "d": "Атлет за миг до броска. Мирон «остановил» движение — для того времени смелый эксперимент.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG", "lic": "CC BY-SA 4.0", "by": "Livioandronico2013", "src": "media/img/7b0a35bc6a-1000.webp", "w": 1000, "h": 1672, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG/1280px-Discobolus_in_National_Roman_Museum_Palazzo_Massimo_alle_Terme.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Скульптор Мирон сделал эту статую около 450 года до нашей эры. Атлет на секунду замер перед броском диска: тело закручено, рука с диском отведена назад.", "Это смелый эксперимент. Мирон «остановил» быстрое движение, как фотограф, хотя фотографии не будет ещё две тысячи лет. При этом лицо атлета спокойно. Греки считали, что достойный человек сохраняет самообладание даже в самом напряжённом деле.", "Бронзовый оригинал утерян. До нас дошли только римские копии из мрамора, которые римляне массово заказывали для своих вилл."]}, {"t": "Венера Милосская", "a": "Предположительно Александрос Антиохийский", "y": "около 130 г. до н. э.", "d": "Эпоха эллинизма. Руки утрачены, но статуя стала символом женской красоты. Хранится в Лувре.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg", "lic": "Public domain", "by": "Unknown artistUnknown artist", "src": "media/img/c5268119fe-1000.webp", "w": 1000, "h": 1678, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Venus_de_Milo_Louvre_Ma399_n4.jpg/1280px-Venus_de_Milo_Louvre_Ma399_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Статую нашёл крестьянин в 1820 году на острове Милос. Французский моряк уговорил посла купить её, и вскоре она оказалась в Лувре.", "Это эпоха эллинизма, около 130 года до нашей эры. Посмотрите на позу: лёгкий изгиб тела, ткань соскальзывает с бёдер, голова повёрнута. Она спокойная, как классика, но мягче и живее.", "Руки утрачены. Как она их держала, неизвестно. Существует много версий: с яблоком, с зеркалом, со щитом. Возможно, именно эта загадка сделала статую такой знаменитой."]}, {"t": "Ника Самофракийская", "a": "Неизвестный скульптор", "y": "около 190 г. до н. э.", "d": "Богиня победы на носу корабля. Мрамор передаёт ветер и мокрую ткань — вершина эллинистической динамики.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Nike_of_Samothrake_Louvre_Ma2369_n4.jpg", "lic": "Public domain", "by": "", "src": "media/img/53813a5b17-1000.webp", "w": 1000, "h": 1515, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Nike_of_Samothrake_Louvre_Ma2369_n4.jpg/1280px-Nike_of_Samothrake_Louvre_Ma2369_n4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Ника это богиня победы. Статую поставили на острове Самофракия около 190 года до нашей эры в честь победы в морском сражении. Она стояла на мраморном носу корабля, как будто только что опустилась на него с неба.", "Лица и рук нет, но фигура полна движения. Ветер прижимает мокрую ткань к телу, крылья развёрнуты назад. Скульптор передал в мраморе то, что почти невозможно передать в камне: воздух и ветер.", "Сейчас Ника стоит в Лувре наверху парадной лестницы, и зрители поднимаются к ней снизу, как когда-то моряки."]}, {"t": "Парфенон", "a": "Иктин и Калликрат, скульптор Фидий", "y": "447–438 гг. до н. э.", "d": "Храм Афины на Акрополе — эталон дорического ордера. Колонны чуть наклонены и утолщены, чтобы храм казался идеально ровным.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Parthenon_in_Athens.jpg", "lic": "CC BY 2.0", "by": "Steve Swayne", "src": "media/img/72aa7cef8d-1000.webp", "w": 1000, "h": 703, "remote": "https://upload.wikimedia.org/wikipedia/commons/d/da/The_Parthenon_in_Athens.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Главный храм Афин построили на холме Акрополь с 447 по 432 год до нашей эры. Им руководил правитель Перикл, работали архитекторы Иктин и Калликрат, скульптурами занимался Фидий.", "Храм посвящён Афине-Деве, покровительнице города. На фронтонах и по всему периметру шли скульптуры: битвы богов, шествие афинян. Изначально всё было раскрашено яркими красками, белым мрамор стал только со временем.", "Колонны чуть наклонены и утолщены посередине, чтобы здание выглядело идеально ровным издалека. Это дорический ордер, самый строгий из трёх греческих ордеров. Часть скульптур Парфенона сейчас хранится в Британском музее, и Греция давно просит их вернуть."]}, {"t": "Колизей", "a": "Римские строители", "y": "72–80 гг. н. э.", "d": "Амфитеатр на 50 000 зрителей. Римская формула: арки, бетон и три греческих ордера на фасаде.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Colosseo_2020.jpg", "lic": "CC BY-SA 4.0", "by": "FeaturedPics", "src": "media/img/9059ffbfcd-1000.webp", "w": 1000, "h": 701, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Colosseo_2020.jpg/1280px-Colosseo_2020.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Колизей открыли в 80 году после 100 дней игр. Он вмещал около 50 000 зрителей. Здесь шли бои гладиаторов, травля зверей, казни и даже, по некоторым свидетельствам, морские сражения в залитой водой арене.", "Под ареной был целый подземный этаж с клетками и подъёмниками, звери появлялись прямо из-под песка. От солнца зрителей закрывал огромный тент, его натягивали моряки.", "Римляне построили Колизей из бетона и камня всего за десять лет. На фасаде три яруса арок, а на колоннах три греческих ордера один над другим. Так римляне соединили греческую красоту и свою инженерию."]}], "quiz": [{"q": "Что такое контрапост?", "o": ["Тип колонны", "Поза с опорой на одну ногу, создающая живое равновесие", "Техника литья бронзы", "Роспись вазы"], "a": 1, "e": "Контрапост оживил скульптуру и вернулся в эпоху Возрождения (вспомните «Давида» Микеланджело)."}, {"q": "Какой храм стоит на афинском Акрополе?", "o": ["Пантеон", "Колизей", "Парфенон", "Храм Артемиды"], "a": 2, "e": "Парфенон посвящён Афине-Деве. Пантеон — в Риме."}, {"q": "Что римляне добавили к греческому искусству?", "o": ["Иероглифы", "Правдивый портрет и арочные конструкции", "Иконопись", "Золотой фон"], "a": 1, "e": "Римский портрет честен: морщины, лысины, характер. А арки и бетон дали огромные пространства."}], "why": ["Греки первыми сделали главным героем искусства человека, его тело, ум и характер. Римляне взяли греческие идеи и добавили инженерную мощь: бетон, арки, купола. Колонны на фасадах театров, банков и музеев, статуи в парках, даже здание Капитолия в Вашингтоне выросли отсюда. Без античности не понять ни Возрождение, ни классицизм."], "groups": [{"h": "Как греки искали идеал", "p": "За триста лет греческая скульптура прошла путь от застывших фигур до бурного движения. Сравните три статуи по порядку.", "items": [{"t": "Архаика: фигура как столб", "d": "Ранние статуи стоят прямо, руки прижаты, на лице улыбка.", "c": "Курос из Анависоса, около 530 года до н. э.", "more": ["Такие статуи юношей называют куросами. Их ставили на могилах и в храмах. Видно влияние Египта: левая нога выставлена вперёд, тело неподвижно, руки опущены вдоль боков.", "Странная улыбка на лице не означает радость. Учёные называют её «архаической улыбкой». Скорее всего, так скульпторы пытались оживить лицо, ещё не умея передавать настоящие эмоции."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Kroisos_Kouros,_NAMA_3851.jpg", "lic": "CC BY-SA 4.0", "by": "Yair-haklai", "src": "media/img/971da50533-1000.webp", "w": 1000, "h": 2549, "remote": "https://upload.wikimedia.org/wikipedia/commons/2/24/Kroisos_Kouros%2C_NAMA_3851.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Классика: контрапост", "d": "Фигура опирается на одну ногу, и всё тело приходит в живое равновесие.", "c": "Поликлет. «Копьеносец», римская копия", "more": ["Около 440 года до нашей эры скульптор Поликлет написал трактат «Канон», где рассчитал идеальные пропорции тела. Например, голова должна составлять седьмую часть роста. Статую «Копьеносец» он сделал как наглядный пример этих правил.", "Посмотрите на ноги. Одна держит вес тела, другая расслаблена и отставлена назад. От этого бёдра наклоняются в одну сторону, а плечи в другую. Такую позу называют контрапостом. Фигура стоит спокойно, но кажется, что она может сделать шаг. Оригинал из бронзы не сохранился, до нас дошли римские копии в мраморе."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Doryphoros_from_Pompeii_(Naples).jpg", "lic": "CC BY-SA 4.0", "by": "Yair-haklai", "src": "media/img/91444c7285-1000.webp", "w": 1000, "h": 2170, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Doryphoros_from_Pompeii_%28Naples%29.jpg/1280px-Doryphoros_from_Pompeii_%28Naples%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Эллинизм: драма и движение", "d": "Позднее искусство показывает страдание, борьбу, напряжение мышц.", "c": "«Лаокоон и сыновья», I век до н. э.", "more": ["По легенде, жрец Лаокоон предупреждал троянцев не вносить в город деревянного коня. Боги, которые хотели гибели Трои, послали змей, и те задушили Лаокоона и его сыновей.", "Скульпторы с острова Родос показали самый страшный момент. Тело выгнуто, мышцы напряжены, лицо искажено болью. Рядом со спокойным «Копьеносцем» разница огромная. Статую нашли в Риме в 1506 году, и на раскопки пришёл посмотреть Микеланджело. Она сильно повлияла на его собственные работы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Laocoon_and_His_Sons.jpg", "lic": "CC BY-SA 4.0", "by": "Hagesandros, Athenedoros, and Polydoros", "src": "media/img/ec294ecf62-1000.webp", "w": 1000, "h": 899, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Laocoon_and_His_Sons.jpg/1280px-Laocoon_and_His_Sons.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Вазопись", "d": "Греки расписывали глиняные сосуды сценами из мифов.", "c": "Эксекий. Ахилл и Аякс играют в кости", "more": ["Греческие картины на досках почти все погибли, поэтому о греческой живописи мы знаем в основном по вазам. Мастер Эксекий около 530 года до нашей эры сам сделал этот сосуд и сам его расписал, о чём оставил подпись.", "Два героя Троянской войны во время передышки играют в кости. Оба в доспехах, щиты рядом. Над Ахиллом надпись «четыре», над Аяксом «три»: Ахилл выигрывает. Это чернофигурная техника: фигуры чёрным лаком по рыжей глине, детали процарапаны иглой."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Achilles_and_Ajax_playing_dice,_Attic_black-figured_amphora,_signed_by_Exekias_as_both_painter_and_potter,_540-530_BC,_inv._16757_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01049.jpg", "lic": "Public domain", "by": "Daderot", "src": "media/img/c381a33021-1000.webp", "w": 1000, "h": 1500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Achilles_and_Ajax_playing_dice%2C_Attic_black-figured_amphora%2C_signed_by_Exekias_as_both_painter_and_potter%2C_540-530_BC%2C_inv._16757_-_Museo_Gregoriano_Etrusco_-_Vatican_Museums_-_DSC01049.jpg/1280px-thumbnail.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Что придумали римляне", "p": "Римляне ценили практичность. Их главные открытия касаются строительства и правдивого портрета.", "items": [{"t": "Купол и бетон", "d": "Римляне изобрели прочный бетон и научились перекрывать огромные залы куполом.", "c": "Пантеон в Риме, около 125 года", "more": ["Пантеон был храмом всех богов. Его купол диаметром 43 метра почти две тысячи лет оставался самым большим в мире и до сих пор остаётся самым большим куполом из неармированного бетона.", "Наверху круглое отверстие диаметром 9 метров, через него в храм падает луч солнца и медленно движется по стенам в течение дня. Чтобы купол не рухнул под собственным весом, наверху римляне добавляли в бетон лёгкую вулканическую пемзу, а внизу тяжёлый камень."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pantheon_(Rome),_Dome_interior.jpg", "lic": "CC0", "by": "Wilfredor", "src": "media/img/5c11a0fa37-1000.webp", "w": 1000, "h": 856, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Pantheon_%28Rome%29%2C_Dome_interior.jpg/1280px-Pantheon_%28Rome%29%2C_Dome_interior.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Арки и акведуки", "d": "Арка распределяет вес и позволяет строить высоко и надолго.", "c": "Акведук Пон-дю-Гар, Франция, I век", "more": ["Акведук это водопровод. По этому мосту вода шла в римский город Ним за 50 километров. Высота почти 50 метров, три яруса арок. Камни уложены без раствора, они держатся только за счёт точного веса и формы.", "Уклон канала наверху меньше 25 сантиметров на километр, такая точность поражает инженеров и сегодня. Римские арки, своды и купола потом станут основой архитектуры на две тысячи лет вперёд."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Pont_du_Gard_BLS.jpg", "lic": "CC BY-SA 3.0", "by": "Benh LIEU SONG (Flickr)", "src": "media/img/185b2effbf-1000.webp", "w": 1000, "h": 386, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Pont_du_Gard_BLS.jpg/1280px-Pont_du_Gard_BLS.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Правдивый портрет", "d": "Греки изображали идеал, римляне показывали человека таким, какой он есть.", "c": "Император Каракалла, около 215 года", "more": ["Римляне хранили дома восковые маски умерших предков, поэтому ценили точное сходство. Морщины, лысина, тяжёлый подбородок, всё изображали честно.", "Император Каракалла был жестоким правителем, и скульптор этого не скрыл. Голова резко повёрнута, брови сдвинуты, взгляд подозрительный. Сам император любил этот образ: он хотел, чтобы его боялись."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Bust_Caracalla.jpg", "lic": "CC BY-SA 3.0", "by": "Herodotptlomeu (talk)", "src": "media/img/8af5a1df59-1000.webp", "w": 1000, "h": 750, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/41/Bust_Caracalla.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Римская живопись", "d": "Стены домов расписывали фресками, и многие сохранились под пеплом Везувия.", "c": "Вилла Мистерий, Помпеи, I век до н. э.", "more": ["В 79 году вулкан Везувий засыпал пеплом города Помпеи и Геркуланум. Пепел сохранил дома вместе с росписями, и благодаря этому мы видим, как выглядела римская живопись.", "В одном из залов виллы по всем стенам идёт непрерывная сцена: женщины проходят обряд посвящения в таинства бога Диониса. Насыщенный красный фон так и называют «помпейским красным»."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Roman_fresco_Villa_dei_Misteri_Pompeii_005b.jpg", "lic": "Public domain", "by": "original files by WolfgangRieger", "src": "media/img/dcbb1b78d2-1000.webp", "w": 1000, "h": 1198, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3c/Roman_fresco_Villa_dei_Misteri_Pompeii_005b.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "a3", "title": "Средневековье: икона, романика, готика", "period": "V — XIV век", "intro": [], "traits": ["Золотой фон — символ божественного света", "Плоские фигуры, обратная перспектива", "Мозаика, икона, витраж, книжная миниатюра", "Готика: стрельчатые арки, витражи, устремлённость вверх", "Анонимность: мастер служит Богу, а не славе"], "works": [{"t": "Троица", "a": "Андрей Рублёв", "y": "1411 или 1425–1427", "d": "Три ангела у стола — образ Святой Троицы. Фигуры вписаны в круг — символ вечности и согласия. Главная русская икона, хранится в Третьяковской галерее.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Angelsatmamre-trinity-rublev-1410.jpg", "lic": "Public domain", "by": "Andrei Rublev", "src": "media/img/567e733b41-1000.webp", "w": 1000, "h": 1245, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Angelsatmamre-trinity-rublev-1410.jpg/1280px-Angelsatmamre-trinity-rublev-1410.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Андрей Рублёв был монахом и написал эту икону в начале XV века, около 1411 или 1425 года, для Троицкого собора в монастыре Сергия Радонежского.", "Сюжет взят из Библии: к старцу Аврааму пришли три странника, и он угощал их у дуба. Христиане увидели в них образ Бога в трёх лицах. Рублёв убрал всё лишнее: самого Авраама, его жену, слуг. Остались три ангела вокруг стола с чашей.", "Фигуры вписаны в круг, головы склонены друг к другу. Это образ любви и согласия. Нежные голубые, золотистые и зелёные цвета делают икону тихой и светлой. В 1551 году церковный собор постановил писать Троицу так, как писал Рублёв."]}, {"t": "Собор Парижской Богоматери", "a": "Строители-готы", "y": "1163–1345", "d": "Образец ранней готики: розы-витражи, контрфорсы, химеры. Собор вдохновил Гюго на роман.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Notre-Dame_de_Paris_2013-07-24.jpg", "lic": "CC BY-SA 3.0", "by": "P e z i", "src": "media/img/a720a76e0c-1000.webp", "w": 1000, "h": 1350, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Notre-Dame_de_Paris_2013-07-24.jpg/1280px-Notre-Dame_de_Paris_2013-07-24.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Строительство началось в 1163 году и продолжалось почти двести лет. Собор стоит на острове посреди Сены, в самом сердце Парижа.", "На фасаде три портала со скульптурами и огромная роза-витраж. Сзади видны аркбутаны, каменные опоры, которые держат стены снаружи. Знаменитые химеры на крыше появились позже, в XIX веке, их добавил архитектор Виолле-ле-Дюк при реставрации.", "После Французской революции собор обветшал и мог быть снесён. Его спас Виктор Гюго: в 1831 году он написал роман «Собор Парижской Богоматери», и Париж решил восстановить храм. В 2019 году собор сильно пострадал от пожара, рухнул шпиль. В декабре 2024 года его открыли после реставрации."]}, {"t": "Оплакивание Христа", "a": "Джотто ди Бондоне", "y": "около 1305", "d": "Фреска в капелле Скровеньи. Лица полны горя, фигуры объёмны — Джотто первым вернул живописи человеческие чувства.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Giotto_-_Scrovegni_-_-36-_-_Lamentation_(The_Mourning_of_Christ)_adj.jpg", "lic": "Public domain", "by": "Giotto", "src": "media/img/1a7c11dd20-1000.webp", "w": 1000, "h": 925, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Giotto_-_Scrovegni_-_-36-_-_Lamentation_%28The_Mourning_of_Christ%29_adj.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Около 1305 года богатый банкир Энрико Скровеньи заказал роспись своей домовой часовни в Падуе художнику Джотто. Тот покрыл стены почти сорока сценами из жизни Марии и Христа.", "Здесь близкие оплакивают снятого с креста Христа. Мария обнимает тело сына, Иоанн раскинул руки от горя, ангелы в небе плачут и мечутся. Горная гряда идёт по диагонали вниз и ведёт наш взгляд к лицам Марии и Христа.", "Главное новшество Джотто в том, что фигуры объёмные и тяжёлые, они стоят на земле. Две фигуры сидят к нам спиной, как будто мы стоим рядом. До Джотто так не делали. Через сто лет художники Возрождения назовут его своим учителем."]}, {"t": "Император Юстиниан со свитой", "a": "Византийские мастера", "y": "около 547", "d": "Мозаика в Равенне. Фигуры парят без тени, смотрят прямо на нас — так выглядит власть, освящённая небом.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Meister_von_San_Vitale_in_Ravenna.jpg", "lic": "Public domain", "by": "Meister von San Vitale in Ravenna", "src": "media/img/a845c3d3d2-1000.webp", "w": 1000, "h": 1353, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Meister_von_San_Vitale_in_Ravenna.jpg/1280px-Meister_von_San_Vitale_in_Ravenna.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Мозаика украшает церковь Сан-Витале в Равенне, её закончили около 547 года. Напротив неё мозаика с императрицей Феодорой.", "Юстиниан в пурпурной одежде с нимбом несёт золотое блюдо для хлеба причастия. Справа священники, слева воины и придворные. Все стоят в ряд, смотрят прямо на нас, ноги будто не касаются земли.", "Так византийцы показывали, что власть императора священна, он наместник Бога. Любопытно, что сам Юстиниан никогда не был в Равенне. Мозаика заменяла его присутствие."]}], "quiz": [{"q": "Что означает золотой фон в иконе?", "o": ["Богатство заказчика", "Божественный свет, небесный мир", "Солнечный день", "Пустыню"], "a": 1, "e": "Золото — не «место», а свет иного мира."}, {"q": "Какие черты отличают готику?", "o": ["Купола и плоские крыши", "Стрельчатые арки, витражи, высота", "Пирамиды и обелиски", "Колонны дорического ордера"], "a": 1, "e": "Готический собор весь стремится вверх, а стены превращаются в витражи."}, {"q": "Кто написал икону «Троица»?", "o": ["Феофан Грек", "Дионисий", "Андрей Рублёв", "Симон Ушаков"], "a": 2, "e": "Андрей Рублёв, начало XV века."}, {"q": "Какой художник предвестил Возрождение, вернув фигурам объём и эмоции?", "o": ["Джотто", "Рембрандт", "Ван Эйк", "Боттичелли"], "a": 0, "e": "Джотто работал около 1300 года — за век до расцвета Ренессанса."}], "why": ["После падения Рима в 476 году Европа на тысячу лет стала христианской. Искусство теперь рассказывало не о красоте тела, а о Боге и спасении души. Многие люди не умели читать, и росписи, витражи и иконы были для них Библией в картинках. В этой главе вы поймёте, почему средневековые фигуры плоские, а соборы такие высокие, и откуда взялась русская икона."], "groups": [{"h": "Византия: свет и золото", "p": "Восточная Римская империя со столицей в Константинополе прожила ещё тысячу лет. От неё Русь получила христианство и иконопись.", "items": [{"t": "Купол как небо", "d": "Огромный купол над храмом символизирует небо.", "c": "Собор Святой Софии в Константинополе, 537 год", "more": ["Император Юстиниан построил Святую Софию всего за пять лет. Её купол диаметром около 31 метра опирается на четыре арки, а у основания прорезан сорока окнами. Из-за этого кажется, что купол парит над храмом на свету.", "По летописи, послы киевского князя Владимира, побывав здесь, сказали, что не знали, на небе они или на земле. Вскоре Русь приняла христианство из Византии. В 1453 году город захватили турки, и собор стал мечетью."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Interior_of_Hagia_Sophia_(8)_-_Istanbul_(2022).jpg", "lic": "CC BY-SA 4.0", "by": "ImanFakhri", "src": "media/img/9a17f8be88-1000.webp", "w": 1000, "h": 1333, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Interior_of_Hagia_Sophia_%288%29_-_Istanbul_%282022%29.jpg/1280px-Interior_of_Hagia_Sophia_%288%29_-_Istanbul_%282022%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Икона: окно в другой мир", "d": "Икона показывает не земной мир, а небесный, поэтому в ней свои правила.", "c": "Владимирская икона Богоматери, XII век", "more": ["Икону написали в Константинополе и около 1131 года привезли на Русь. Её считали покровительницей Москвы и много раз носили по городу во время нашествий.", "Посмотрите: Младенец прижимается щекой к щеке матери. Этот тип иконы называют «Умиление». Фон золотой, это свет Царства Небесного. Фигуры плоские, без теней, потому что в небесном мире нет обычного земного света, который отбрасывает тень."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Virgin_of_Vladimir.jpg", "lic": "Public domain", "by": "Michel Bakni", "src": "media/img/9b635a556f-1000.webp", "w": 1000, "h": 1456, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Virgin_of_Vladimir.jpg/1280px-Virgin_of_Vladimir.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Романский стиль: крепость веры", "p": "В XI и XII веках на Западе строили массивные каменные храмы с толстыми стенами и маленькими окнами.", "items": [{"t": "Толстые стены, полукруглые арки", "d": "Романские соборы похожи на крепости.", "c": "Собор в Шпайере, Германия, XI век", "more": ["Название «романский» придумали в XIX веке: этот стиль похож на римский, у него такие же полукруглые арки. Своды делали из камня, и они были очень тяжёлыми. Чтобы стены выдержали вес, их строили толстыми, а окна делали маленькими.", "Собор в Шпайере строили императоры, он был самым большим храмом Европы своего времени. Внутри полутемно и торжественно. Такой храм ощущался как надёжная крепость веры в неспокойное время."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Aerial_image_of_the_Speyer_Cathedral_(view_from_the_southwest).jpg", "lic": "CC BY-SA 4.0", "by": "Carsten Steger", "src": "media/img/5c8558262f-1000.webp", "w": 1000, "h": 738, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Aerial_image_of_the_Speyer_Cathedral_%28view_from_the_southwest%29.jpg/1280px-Aerial_image_of_the_Speyer_Cathedral_%28view_from_the_southwest%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Вышивка-летопись", "d": "Длинная история в картинках, как комикс.", "c": "Ковёр из Байё, около 1070 года", "more": ["Это полотно длиной почти 70 метров с вышивкой шерстью. Оно рассказывает, как нормандский герцог Вильгельм завоевал Англию в 1066 году.", "Сцены идут одна за другой, с подписями на латыни, как кадры комикса. На этом фрагменте люди показывают на небо, где летит комета. Это комета Галлея, она действительно появилась весной 1066 года, и её сочли знаком беды для английского короля."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Bayeux_Tapestry_32-33_comet_Halley_Harold.jpg", "lic": "Public domain", "by": "Myrabella", "src": "media/img/e9267b627a-1000.webp", "w": 1000, "h": 642, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Bayeux_Tapestry_32-33_comet_Halley_Harold.jpg/1280px-Bayeux_Tapestry_32-33_comet_Halley_Harold.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Готика: всё стремится вверх", "p": "С середины XII века строители нашли способ сделать стены лёгкими, а храмы очень высокими.", "items": [{"t": "Стены из стекла", "d": "Стрельчатые своды и наружные опоры позволили заменить стены витражами.", "c": "Сент-Шапель в Париже, 1248 год", "more": ["Секрет готики в стрельчатой арке и аркбутанах, наружных каменных «костылях», которые подпирают стены снаружи. Вес свода уходит на эти опоры, и стену можно почти целиком заменить окнами.", "Король Людовик IX построил Сент-Шапель для хранения реликвии, которую считали терновым венцом Христа. Витражи занимают около 600 квадратных метров и показывают больше тысячи библейских сцен. Когда светит солнце, кажется, что стоишь внутри драгоценного камня."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Sainte-Chapelle,_Paris,_upper_chapel_windows.jpg", "lic": "CC0", "by": "Gerda Arendt", "src": "media/img/46498a171d-1000.webp", "w": 1000, "h": 750, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Sainte-Chapelle%2C_Paris%2C_upper_chapel_windows.jpg/1280px-Sainte-Chapelle%2C_Paris%2C_upper_chapel_windows.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Роза", "d": "Огромное круглое окно-витраж на фасаде.", "c": "Северная роза собора в Шартре, около 1230 года", "more": ["Витраж собирают из кусочков цветного стекла, соединённых свинцовыми полосками. Стекло окрашивали ещё при варке: добавляли металлы, кобальт давал синий, медь красный.", "Синий цвет Шартра такой глубокий, что его называют «шартрским синим», и повторить его рецепт до сих пор не удаётся точно. Свет считался образом Бога, поэтому цветные окна делали храм «небесным Иерусалимом» на земле."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Chartres_-_cath%C3%A9drale_-_rosace_nord.jpg", "lic": "Public domain", "by": "Eusebius", "src": "media/img/1e536f9172-1000.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Chartres_-_cath%C3%A9drale_-_rosace_nord.jpg/1280px-Chartres_-_cath%C3%A9drale_-_rosace_nord.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Книжная миниатюра", "d": "Рукописные книги украшали маленькими картинами.", "c": "«Великолепный часослов герцога Беррийского», октябрь", "more": ["Книгопечатания ещё не было, книги переписывали от руки и украшали рисунками. Самая знаменитая из них сделана для французского герцога братьями Лимбург около 1415 года.", "Каждый месяц календаря показан сценой. В октябре крестьяне сеют зерно, а за рекой стоит настоящий парижский дворец Лувр, каким он был тогда. На полях стоит пугало в виде лучника, чтобы отгонять птиц. Здесь уже появляется интерес к реальному миру, предвестие Возрождения."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Les_Tr%C3%A8s_Riches_Heures_du_duc_de_Berry_octobre.jpg", "lic": "Public domain", "by": "Limbourg brothers / Barthélemy d'Eyck", "src": "media/img/7ce709c192-1000.webp", "w": 1000, "h": 1667, "remote": "https://upload.wikimedia.org/wikipedia/commons/f/f5/Les_Tr%C3%A8s_Riches_Heures_du_duc_de_Berry_octobre.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}]}]}, {"id": "a4", "title": "Возрождение", "period": "XV — XVI век", "intro": [], "traits": ["Гуманизм: человек в центре мира", "Линейная перспектива и анатомическая точность", "Античные сюжеты наравне с библейскими", "Сфумато, масляная живопись", "Титаны: Леонардо, Микеланджело, Рафаэль"], "works": [{"t": "Рождение Венеры", "a": "Сандро Боттичелли", "y": "около 1485", "d": "Языческая богиня выходит из моря на раковине. Для христианской Флоренции — смелый жест. Линии плавные, как в танце.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg", "lic": "Public domain", "by": "Sandro Botticelli", "src": "media/img/d1f4f16c8b-1000.webp", "w": 1000, "h": 628, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg/1280px-Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Сандро Боттичелли написал картину около 1485 года во Флоренции, скорее всего для семьи Медичи. Это одна из первых больших картин с языческой богиней после тысячи лет христианского искусства.", "Богиня любви Венера родилась из морской пены и плывёт к берегу на раковине. Слева её подгоняют боги ветров, справа нимфа встречает её с плащом в цветах. Поза Венеры повторяет античные статуи: Боттичелли видел их в коллекции Медичи.", "Линии плавные, фигуры лёгкие, будто танцуют. Боттичелли интересовала не анатомия, а красота и поэзия. Через несколько лет под влиянием проповедника Савонаролы он сжёг часть своих «языческих» работ, но эта уцелела."]}, {"t": "Мона Лиза (Джоконда)", "a": "Леонардо да Винчи", "y": "1503–1519", "d": "Самая известная картина мира. Обратите внимание на сфумато: уголки губ и глаз растворены в дымке, поэтому улыбка «ускользает».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mona_Lisa,_by_Leonardo_da_Vinci,_from_C2RMF_retouched.jpg", "lic": "Public domain", "by": "Leonardo da Vinci", "src": "media/img/b6403bc945-1000.webp", "w": 1000, "h": 1490, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/1280px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Леонардо начал портрет около 1503 года. Скорее всего, это Лиза Герардини, жена флорентийского торговца Франческо дель Джокондо, отсюда второе название. Леонардо так и не отдал картину заказчику и возил её с собой до конца жизни.", "Главный приём здесь сфумато, по-итальянски «как дым». Контуры не обведены линией, а растворяются в мягких тенях. Особенно у уголков губ и глаз. Поэтому кажется, что Мона Лиза то улыбается, то грустит.", "Пейзаж за спиной фантастический, слева и справа он на разной высоте. В 1911 году итальянский рабочий украл картину из Лувра, и её два года искали по всему миру. После этого она стала самой знаменитой картиной на планете."]}, {"t": "Сотворение Адама", "a": "Микеланджело Буонарроти", "y": "около 1511", "d": "Фреска потолка Сикстинской капеллы. Пальцы Бога и Адама почти касаются — в этом зазоре вся драма.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Michelangelo_-_Creation_of_Adam_(cropped).jpg", "lic": "Public domain", "by": "Michelangelo", "src": "media/img/9cda9ecdae-1000.webp", "w": 1000, "h": 454, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg/1280px-Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1508 году папа Юлий II поручил Микеланджело расписать потолок Сикстинской капеллы. Микеланджело считал себя скульптором и сопротивлялся, но за четыре года написал площадь больше 500 квадратных метров, работая на лесах под самым сводом.", "Эта сцена самая известная. Бог в окружении ангелов протягивает руку к Адаму, чтобы передать ему жизнь. Адам вялый, он ещё не ожил. Между их пальцами крошечный зазор, и в нём всё напряжение момента.", "Тело Адама написано как античная скульптура. Некоторые врачи заметили, что фигура Бога с ангелами по форме похожа на человеческий мозг. Случайно это или нет, неизвестно, но Микеланджело хорошо знал анатомию."]}, {"t": "Афинская школа", "a": "Рафаэль Санти", "y": "1509–1511", "d": "Платон и Аристотель в центре, вокруг — великие мыслители. Идеальная перспектива: все линии сходятся к двум философам.", "img": {"page": "https://commons.wikimedia.org/wiki/File:%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg", "lic": "Public domain", "by": "Raphael", "src": "media/img/88562caed1-1000.webp", "w": 1000, "h": 776, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg/1280px-%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Рафаэль написал эту фреску в 1509–1511 годах в покоях папы в Ватикане. Ему было всего около двадцати шести лет.", "Под величественными арками собрались философы и учёные Древней Греции. В центре Платон указывает вверх, в мир идей, а его ученик Аристотель указывает вниз, на реальный мир. Так Рафаэль показал два главных пути в философии.", "Многим философам Рафаэль дал лица своих современников: Платон похож на Леонардо, а Гераклит в центре на переднем плане на Микеланджело. Себя художник тоже нарисовал справа, он смотрит прямо на нас. Все линии здания сходятся к двум главным фигурам, это образец перспективы."]}, {"t": "Портрет четы Арнольфини", "a": "Ян ван Эйк", "y": "1434", "d": "Северное Возрождение. В выпуклом зеркале на стене отражена вся комната и сам художник.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Eyck_-_Arnolfini_Portrait.jpg", "lic": "Public domain", "by": "Jan van Eyck", "src": "media/img/fc05e7255e-1000.webp", "w": 1000, "h": 1368, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/1280px-Van_Eyck_-_Arnolfini_Portrait.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Фламандский художник Ян ван Эйк написал портрет в 1434 году. На нём итальянский купец Джованни Арнольфини и его жена в доме в городе Брюгге.", "Ван Эйк одним из первых в совершенстве освоил масляную живопись. Посмотрите на детали: каждый волосок собачки, блеск латунной люстры, апельсины на подоконнике. Апельсины были дорогими, и это знак богатства.", "В выпуклом зеркале на стене отражается вся комната и ещё двое людей у двери. Над зеркалом надпись: «Ян ван Эйк был здесь. 1434». Возможно, художник был свидетелем важного события в жизни этой пары."]}, {"t": "Давид", "a": "Микеланджело Буонарроти", "y": "1501–1504", "d": "Пятиметровый мраморный юноша перед боем с Голиафом. Классический контрапост — привет от Греции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:%27David%27_by_Michelangelo_Fir_JBU004.jpg", "lic": "CC BY 3.0", "by": "Jörg Bittner Unna", "src": "media/img/36bbc1e88e-1000.webp", "w": 1000, "h": 1500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/%27David%27_by_Michelangelo_Fir_JBU004.jpg/1280px-%27David%27_by_Michelangelo_Fir_JBU004.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Микеланджело было 26 лет, когда в 1501 году он взялся за огромный кусок мрамора, который сорок лет лежал во дворе собора. Другие скульпторы отказались от него, считая испорченным. Через три года статуя высотой больше пяти метров была готова.", "По Библии, юный пастух Давид победил великана Голиафа камнем из пращи. Обычно Давида изображали после победы, с головой врага. Микеланджело показал момент до боя: Давид собран, брови нахмурены, праща перекинута через плечо.", "Поза построена на контрапосте, как у греческих статуй. Голова и руки немного больше нормы: статуя должна была стоять высоко на соборе и смотреться снизу. Флорентийцы увидели в Давиде символ своего маленького города, который не боится сильных врагов."]}], "quiz": [{"q": "Что такое гуманизм?", "o": ["Вера в магию", "Взгляд, ставящий человека в центр мира", "Стиль архитектуры", "Техника фрески"], "a": 1, "e": "Гуманисты верили в достоинство и возможности человека."}, {"q": "Как называется дымчатая манера Леонардо, смягчающая контуры?", "o": ["Сфумато", "Импасто", "Пуантилизм", "Гризайль"], "a": 0, "e": "Sfumato — «исчезающий как дым»."}, {"q": "В каком городе началось итальянское Возрождение?", "o": ["Рим", "Венеция", "Флоренция", "Милан"], "a": 2, "e": "Флоренция при Медичи — колыбель Ренессанса."}, {"q": "Кто из этих художников — представитель Северного Возрождения?", "o": ["Рафаэль", "Ян ван Эйк", "Боттичелли", "Тициан"], "a": 1, "e": "Ван Эйк работал во Фландрии и прославился масляной живописью."}], "why": ["Возрождение изменило то, как мы видим мир. Художники изучили анатомию, придумали перспективу и вернули искусству интерес к человеку. Многое из того, что сегодня кажется нормальным для картины, придумано именно тогда: глубина, объём, живые лица, точные пропорции. Это самая известная эпоха в истории искусства, и её работы вы точно уже видели."], "groups": [{"h": "Наука и искусство вместе", "p": "Художники Возрождения были и учёными. Они изучали тело, геометрию, оптику.", "items": [{"t": "Пропорции человека", "d": "Художники вычисляли идеальные пропорции тела.", "c": "Леонардо да Винчи. «Витрувианский человек», около 1490", "more": ["Римский архитектор Витрувий писал, что тело человека с раскинутыми руками и ногами вписывается и в круг, и в квадрат. Леонардо проверил это на рисунке. Он измерял людей и записал, что размах рук равен росту, а ладонь равна четырём пальцам.", "Леонардо тайно вскрывал умерших, чтобы понять, как устроены мышцы и кости, и оставил сотни анатомических рисунков. Знание анатомии позволило художникам рисовать тело точнее, чем когда-либо раньше."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vitruvian_Man_by_Leonardo_da_Vinci.jpg", "lic": "CC BY-SA 4.0", "by": "Paris Orlando", "src": "media/img/5d9a454d9c-1000.webp", "w": 1000, "h": 1421, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Vitruvian_Man_by_Leonardo_da_Vinci.jpg/1280px-Vitruvian_Man_by_Leonardo_da_Vinci.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Купол Брунеллески", "d": "Архитектор решил задачу, которую считали невозможной.", "c": "Купол собора во Флоренции, 1420–1436", "more": ["Собор во Флоренции строили больше ста лет, но над ним зияла огромная дыра шириной 45 метров. Никто не знал, как перекрыть её куполом: не было таких длинных деревянных опор для строительства.", "Филиппо Брунеллески изучил римский Пантеон и придумал купол из двух оболочек, внутренней и внешней, с кирпичами, уложенными «ёлочкой». Купол держал сам себя во время строительства. Это самый большой кирпичный купол в мире. Тот же Брунеллески открыл правила линейной перспективы."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Florence,_Italy,_Brunelleschi%27s_Dome_of_Florence_Cathedral.jpg", "lic": "CC BY 4.0", "by": "Vyacheslav Argenberg", "src": "media/img/7f3408f659-1000.webp", "w": 1000, "h": 667, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Florence%2C_Italy%2C_Brunelleschi%27s_Dome_of_Florence_Cathedral.jpg/1280px-Florence%2C_Italy%2C_Brunelleschi%27s_Dome_of_Florence_Cathedral.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Северное Возрождение", "p": "В Нидерландах и Германии Возрождение шло своим путём: меньше античности, больше точности и религиозных чувств.", "items": [{"t": "Художник как личность", "d": "Художник впервые пишет себя с достоинством учёного и мастера.", "c": "Альбрехт Дюрер. Автопортрет, 1500", "more": ["В Средние века художник считался ремесленником, как сапожник. Дюрер изобразил себя прямо, фронтально, как обычно изображали только Христа. Справа надпись: «Я, Альбрехт Дюрер из Нюрнберга, написал себя вечными красками в 28 лет».", "Дюрер ездил в Италию, изучал перспективу и пропорции и привёз эти идеи в Германию. Его гравюры продавались по всей Европе, и он стал первым художником, который прославился благодаря печати."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Albrecht_D%C3%BCrer_-_1500_self-portrait_(High_resolution_and_detail).jpg", "lic": "Public domain", "by": "Albrecht Dürer", "src": "media/img/b8ac429923-1000.webp", "w": 1000, "h": 1383, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Albrecht_D%C3%BCrer_-_1500_self-portrait_%28High_resolution_and_detail%29.jpg/1280px-Albrecht_D%C3%BCrer_-_1500_self-portrait_%28High_resolution_and_detail%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Фантазия и мораль", "d": "Странные миры, полные символов.", "c": "Иероним Босх. «Сад земных наслаждений», около 1500", "more": ["Это триптих, картина из трёх створок. Слева рай, где Бог знакомит Адама и Еву. В центре люди предаются удовольствиям среди огромных ягод и птиц. Справа ад с музыкальными инструментами-пытками и чудовищами.", "Босх предупреждал, к чему ведут грехи. Смысл многих деталей до сих пор разгадывают. Через четыреста лет его фантазии вдохновят сюрреалистов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution.jpg", "lic": "Public domain", "by": "Hieronymus Bosch", "src": "media/img/cdc9c499d7-1000.webp", "w": 1000, "h": 569, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution.jpg/1280px-The_Garden_of_Earthly_Delights_by_Bosch_High_Resolution.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a5", "title": "Барокко", "period": "XVII век", "intro": [], "traits": ["Динамика, диагональные композиции", "Резкий контраст света и тени", "Театральность, пышность, эмоции на пределе", "Синтез искусств: архитектура + скульптура + живопись", "Голландия: бытовой жанр и натюрморт"], "works": [{"t": "Призвание апостола Матфея", "a": "Караваджо", "y": "1599–1600", "d": "Луч света следует за жестом Христа и падает на сборщика податей. Свет здесь — сам призыв.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Calling_of_Saint_Matthew-Caravaggo_(1599-1600).jpg", "lic": "Public domain", "by": "Caravaggio", "src": "media/img/0184cd4f33-1000.webp", "w": 1000, "h": 1028, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/The_Calling_of_Saint_Matthew-Caravaggo_%281599-1600%29.jpg/1280px-The_Calling_of_Saint_Matthew-Caravaggo_%281599-1600%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Караваджо написал картину в 1599–1600 годах для церкви в Риме. По Евангелию, Христос позвал сборщика налогов Матфея, и тот оставил всё и пошёл за ним.", "Сцена происходит в обычной римской таверне. Люди в модной одежде считают деньги. Справа входит Христос и указывает на Матфея. Луч света из невидимого окна идёт следом за его рукой и падает на лица. Матфей показывает на себя, будто спрашивает: «Я?»", "Караваджо писал святых как простых людей, иногда моделями служили уличные бродяги. Многим это не нравилось. Но его резкий свет из темноты, тенебросо, подхватили художники по всей Европе."]}, {"t": "Ночной дозор", "a": "Рембрандт ван Рейн", "y": "1642", "d": "Групповой портрет стрелковой роты, превращённый в живую сцену. На самом деле действие дневное — картина потемнела от лака.", "img": {"page": "https://commons.wikimedia.org/wiki/File:La_ronda_de_noche,_por_Rembrandt_van_Rijn.jpg", "lic": "Public domain", "by": "Rembrandt", "src": "media/img/056817c627-1000.webp", "w": 1000, "h": 814, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg/1280px-La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1642 году отряд городской стражи Амстердама заказал Рембрандту групповой портрет. Такие портреты обычно выглядели как ряды голов, и каждый платил за своё место.", "Рембрандт превратил портрет в живую сцену: капитан отдаёт приказ, отряд выступает, кто-то заряжает мушкет, бьёт барабан, бежит девочка с курицей на поясе, символом отряда. Картина огромная, около 4 на 4,5 метра.", "Название «Ночной дозор» появилось позже: лак со временем потемнел, и сцена стала казаться ночной. На самом деле это день. Говорят, что заказчики были недовольны, потому что не всех хорошо видно, но это скорее легенда."]}, {"t": "Менины", "a": "Диего Веласкес", "y": "1656", "d": "Загадка-картина: художник пишет королевскую чету, отражённую в зеркале, а смотрим на сцену мы — с их места.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Las_Meninas,_by_Diego_Vel%C3%A1zquez,_from_Prado_in_Google_Earth.jpg", "lic": "Public domain", "by": "Diego Velázquez", "src": "media/img/394994c256-1000.webp", "w": 1000, "h": 1151, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg/1280px-Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Испанский придворный художник Диего Веласкес написал картину в 1656 году. В центре маленькая инфанта Маргарита, дочь короля, вокруг неё фрейлины, по-испански менины, карлики и собака.", "Слева сам Веласкес стоит у огромного холста с кистью. Кого он пишет? В зеркале на дальней стене отражаются король и королева. Значит, они стоят там, где стоим мы, зрители, и все смотрят на них.", "Получается игра: мы видим сцену глазами короля. Картину считают одной из самых загадочных в истории. Пикассо написал по её мотивам 58 своих вариантов."]}, {"t": "Девушка с жемчужной серёжкой", "a": "Ян Вермеер", "y": "около 1665", "d": "«Северная Мона Лиза». Тихий голландский свет, ультрамарин и один блик на жемчуге.", "img": {"page": "https://commons.wikimedia.org/wiki/File:1665_Girl_with_a_Pearl_Earring.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/1f01b6178c-1000.webp", "w": 1000, "h": 1184, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/1280px-1665_Girl_with_a_Pearl_Earring.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Ян Вермеер жил в городе Делфт и написал эту работу около 1665 года. Это не портрет на заказ, а этюд головы в экзотическом костюме, голландцы называли такие работы «тронье».", "Девушка обернулась через плечо, губы приоткрыты, будто хочет что-то сказать. Фон тёмный, почти чёрный, поэтому лицо и тюрбан светятся. Синий цвет сделан из лазурита, привезённого из Афганистана, он стоил дороже золота.", "Жемчужина нарисована всего двумя мазками: блик сверху и отражение воротника снизу. Возможно, это вообще не жемчуг, а полированное олово или стекло, слишком уж она большая. Имя девушки неизвестно."]}, {"t": "Экстаз святой Терезы", "a": "Джан Лоренцо Бернини", "y": "1647–1652", "d": "Скульптура как театральная сцена: мрамор превращён в облака и складки, сверху льётся настоящий свет из скрытого окна.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Ecstasy_of_Saint_Teresa_September_2015-2a.jpg", "lic": "CC BY-SA 4.0", "by": "Gian Lorenzo Bernini", "src": "media/img/ed744cd141-1000.webp", "w": 1000, "h": 1585, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Ecstasy_of_Saint_Teresa_September_2015-2a.jpg/1280px-Ecstasy_of_Saint_Teresa_September_2015-2a.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Скульптор и архитектор Джан Лоренцо Бернини создал эту композицию в 1647–1652 годах для капеллы в римской церкви.", "Святая Тереза из Авилы описала видение: ангел пронзил её сердце золотой стрелой, и она почувствовала одновременно боль и огромную любовь к Богу. Бернини показал этот момент. Тереза парит на мраморном облаке, ангел улыбается.", "Это настоящий театр. Сверху льётся свет из скрытого окна, золотые лучи из бронзы падают на фигуры. По бокам капеллы Бернини поместил скульптуры заказчиков в ложах, как зрителей в театре. Мрамор у него выглядит как мягкая ткань и пух облаков."]}], "quiz": [{"q": "Какой приём особенно характерен для Караваджо?", "o": ["Золотой фон", "Резкий луч света из темноты", "Пуантилизм", "Обратная перспектива"], "a": 1, "e": "Тенебросо — «тёмная манера»: фигуры вырваны из мрака светом."}, {"q": "Чем барокко отличается от Возрождения?", "o": ["Спокойствием и симметрией", "Движением, драмой, театральностью", "Плоскостью изображения", "Отказом от сюжета"], "a": 1, "e": "Возрождение — гармония, барокко — страсть и движение."}, {"q": "В какой стране работали Вермеер и Рембрандт?", "o": ["Испания", "Италия", "Голландия", "Франция"], "a": 2, "e": "Золотой век голландской живописи — XVII век."}], "why": ["Барокко родилось в XVII веке, когда католическая церковь и короли хотели поразить людей, вызвать сильные чувства. Отсюда драма, роскошь и театральность. А в протестантской Голландии в то же время появилось совсем другое, тихое искусство для обычных горожан. Поняв эти два пути, вы увидите, как искусство зависит от того, кто его заказывает."], "groups": [{"h": "Искусство, которое потрясает", "p": "Церковь и монархи использовали искусство, чтобы показать свою силу и славу.", "items": [{"t": "Движение и страсть", "d": "Диагонали, бурные жесты, тела в движении.", "c": "Рубенс. «Снятие с креста», 1614", "more": ["Питер Пауль Рубенс из Антверпена был самым успешным художником Европы, у него была огромная мастерская с учениками. Эту картину он написал для собора в родном городе.", "Тело Христа соскальзывает вниз по белому полотну, и все фигуры подхватывают его. Композиция построена по диагонали сверху вниз, от этого кажется, что всё происходит прямо сейчас. Белая ткань притягивает взгляд к центру. Это типичный приём барокко: зритель должен почувствовать, а не просто посмотреть."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Peter_Paul_Rubens_-_Descent_from_the_Cross_-_WGA20212.jpg", "lic": "Public domain", "by": "Peter Paul Rubens", "src": "media/img/b778a01789-1000.webp", "w": 1000, "h": 586, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Peter_Paul_Rubens_-_Descent_from_the_Cross_-_WGA20212.jpg/1280px-Peter_Paul_Rubens_-_Descent_from_the_Cross_-_WGA20212.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Дворец как театр", "d": "Архитектура барокко ослепляет роскошью.", "c": "Зеркальная галерея Версаля, 1684", "more": ["Король Франции Людовик XIV превратил охотничий домик в огромный дворец Версаль. Так он показывал, что вся власть в стране принадлежит ему. Его называли «король-солнце».", "В галерее 357 зеркал напротив семнадцати окон. Зеркала тогда были очень дорогими, их умели делать только в Венеции, а французы переманили мастеров. Днём галерея наполнена светом, вечером тысячи свечей отражались в стёклах. Позже по образцу Версаля строили дворцы по всей Европе, включая Петергоф."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Chateau_Versailles_Galerie_des_Glaces.jpg", "lic": "CC BY-SA 3.0", "by": "Myrabella", "src": "media/img/8e414e2d8a-1000.webp", "w": 1000, "h": 664, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Chateau_Versailles_Galerie_des_Glaces.jpg/1280px-Chateau_Versailles_Galerie_des_Glaces.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Голландия: искусство для горожан", "p": "В Голландии не было пышного двора, а церковь запрещала картины в храмах. Картины покупали обычные горожане для своих домов.", "items": [{"t": "Тихие сцены дома", "d": "Будничные занятия, свет из окна, порядок и покой.", "c": "Вермеер. «Молочница», около 1660", "more": ["Служанка аккуратно наливает молоко. Больше ничего не происходит, но от картины трудно оторваться. Свет падает из окна слева, на хлебе блестят крошечные точки краски, похожие на крупинки света.", "Голландцы гордились чистотой, трудом и порядком в доме, и такие картины показывали эти ценности. Вермеер работал медленно и писал около двух картин в год, поэтому их сохранилось так мало."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Johannes Vermeer", "src": "media/img/e301c142dc-1000.webp", "w": 1000, "h": 1121, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg/1280px-Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Свет души", "d": "Рембрандт находил в тени глубину чувств.", "c": "Рембрандт. Автопортрет, 1669", "more": ["Рембрандт написал около восьмидесяти автопортретов за жизнь. Молодым он изображал себя в дорогих нарядах, когда был богат и знаменит. Потом он разорился, потерял жену и сына, дом продали за долги.", "Этот портрет написан в год смерти. Старое усталое лицо выходит из темноты, руки сложены. В нём нет ни позы, ни самолюбования. Рембрандт честно показывает, что сделала с ним жизнь, и от этого портрет кажется живым разговором."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Rembrandt", "src": "media/img/b30387ec73-1000.webp", "w": 1000, "h": 1295, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg/1280px-Rembrandt_van_Rijn_-_Self-Portrait_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a6", "title": "Классицизм и романтизм", "period": "XVIII — первая половина XIX века", "intro": [], "traits": ["Классицизм: долг, разум, античные сюжеты, чёткий рисунок", "Романтизм: чувства, стихия, свобода, мистика", "Романтический герой одинок и противостоит миру", "Классицизм — линия, романтизм — цвет", "Интерес к национальной истории и фольклору"], "works": [{"t": "Клятва Горациев", "a": "Жак-Луи Давид", "y": "1784", "d": "Манифест классицизма: братья клянутся отцу сражаться за Рим. Мужчины — прямые линии долга, женщины справа — мягкие линии горя.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Anne-Louis Girodet / After Jacques-Louis David", "src": "media/img/22bf98d9da-1000.webp", "w": 1000, "h": 780, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg/1280px-Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Жак-Луи Давид написал картину в 1784 году. Сюжет из истории Древнего Рима: три брата Горации клянутся отцу, что будут сражаться за Рим с тремя братьями из враждебного города, даже ценой жизни.", "Композиция очень чёткая. Три арки, три группы. Слева братья: прямые ноги, вытянутые руки, всё как натянутые струны. В центре отец с мечами. Справа плачущие женщины, их линии мягкие и согнутые. Одна из них невеста врага, другая сестра врага.", "Смысл ясен: долг перед родиной выше личных чувств. Через пять лет начнётся Французская революция, и картина станет для революционеров символом гражданской доблести."]}, {"t": "Свобода, ведущая народ", "a": "Эжен Делакруа", "y": "1830", "d": "Июльская революция в Париже. Аллегория Свободы с флагом идёт через баррикаду — символ Франции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg", "lic": "Public domain", "by": "Eugène Delacroix", "src": "media/img/0c3bfae6f4-1000.webp", "w": 1000, "h": 802, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg/1280px-Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В июле 1830 года парижане три дня сражались на баррикадах и свергли короля Карла X. Эжен Делакруа сам на баррикадах не был, но той же осенью написал эту картину.", "Женщина с трёхцветным флагом и во фригийском колпаке это не реальный человек, а аллегория Свободы. За ней идут люди разных сословий: рабочий с саблей, буржуа в цилиндре с ружьём, мальчишка с пистолетами. Под ногами погибшие.", "Тела, дым, движение вперёд, цвета флага повторяются по всей картине. Это романтизм: чувство порыва важнее точного рисунка. Сегодня Марианна, женщина во фригийском колпаке, символ Франции, её изображают на марках и монетах."]}, {"t": "Странник над морем тумана", "a": "Каспар Давид Фридрих", "y": "около 1818", "d": "Икона романтизма: одинокий человек спиной к нам перед бескрайней природой.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg", "lic": "Public domain", "by": "Caspar David Friedrich", "src": "media/img/e5489bdc04-1000.webp", "w": 1000, "h": 1281, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg/1280px-Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Немецкий художник Каспар Давид Фридрих написал картину около 1818 года. Человек в тёмном пальто стоит на скале спиной к нам и смотрит на горы, утопающие в тумане.", "Мы не видим его лица и смотрим вместе с ним. Это любимый приём Фридриха: зритель становится героем картины. Перед бескрайней природой человек одинок и мал, но он поднялся на вершину.", "Для романтиков природа была путём к Богу и к самому себе. Сегодня эта картина стала символом всего романтизма и часто появляется на обложках книг о философии."]}, {"t": "Третье мая 1808 года", "a": "Франсиско Гойя", "y": "1814", "d": "Расстрел испанских повстанцев французами. Белая рубаха и раскинутые руки — образ жертвы на все времена.", "img": {"page": "https://commons.wikimedia.org/wiki/File:El_Tres_de_Mayo,_by_Francisco_de_Goya,_from_Prado_thin_black_margin.jpg", "lic": "Public domain", "by": "El_Tres_de_Mayo,_by_Francisco_de_Goya,_from_Prado_in_Google_Earth.jpg: Francisco", "src": "media/img/e92f790510-1000.webp", "w": 1000, "h": 772, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_thin_black_margin.jpg/1280px-El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_thin_black_margin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1808 году армия Наполеона заняла Испанию. 2 мая жители Мадрида восстали, а ночью и утром 3 мая французы расстреливали пленных. Франсиско Гойя написал картину в 1814 году, после изгнания французов.", "Солдаты стоят ровным рядом спиной к нам, лиц не видно, они как машина. Напротив жертвы. Человек в белой рубашке раскинул руки, на ладони виден след, похожий на рану от гвоздя. Он как распятый мученик.", "Свет от большого фонаря падает на него, а остальное в темноте. До Гойи войну обычно изображали как подвиг. Он первым показал её как бессмысленное убийство. Эта картина повлияла на многие антивоенные работы, включая «Гернику» Пикассо."]}, {"t": "Последний день Помпеи", "a": "Карл Брюллов", "y": "1830–1833", "d": "Первая русская картина с мировой славой. Классицистические фигуры в романтической катастрофе.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Karl Bryullov", "src": "media/img/7a055b23ec-1000.webp", "w": 1000, "h": 702, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg/1280px-Karl_Brullov_-_The_Last_Day_of_Pompeii_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Карл Брюллов побывал на раскопках Помпей и шесть лет работал над картиной, закончив её в 1833 году. Размер почти 5 на 6,5 метра.", "Извержение Везувия, 79 год. Рушатся здания и статуи, небо разрывает молния. Люди пытаются спасти близких: сыновья несут старика-отца, мать обнимает дочерей. В левом углу художник изобразил себя с ящиком красок.", "Фигуры прекрасны, как античные статуи, это от классицизма. А катастрофа, страх и ночное зарево от романтизма. Картину с восторгом встретили в Риме и Париже, и это был первый мировой успех русской живописи. Гоголь назвал её «светлым воскресением живописи»."]}], "quiz": [{"q": "Что ставит на первое место классицизм?", "o": ["Личные чувства", "Долг и разум", "Мистику", "Впечатление момента"], "a": 1, "e": "Классицизм учит: долг перед обществом выше личного."}, {"q": "Какие темы любят романтики?", "o": ["Порядок и симметрию", "Стихию, свободу, одиночество героя", "Геометрические фигуры", "Повседневный быт"], "a": 1, "e": "Буря, ночь, горы, революция — всё, что сильнее разума."}, {"q": "Кто написал «Последний день Помпеи»?", "o": ["Илья Репин", "Карл Брюллов", "Иван Айвазовский", "Василий Суриков"], "a": 1, "e": "Карл Брюллов, 1833 год."}], "why": ["В конце XVIII века Европа увлеклась раскопками Помпей и античностью и решила, что искусство должно учить разуму и долгу. Так появился классицизм. Через несколько десятилетий молодые художники восстали: им было важнее чувство, свобода и тайна. Это романтизм. Петербург, Пушкин, Брюллов, Айвазовский выросли из этих двух течений, и спор между разумом и чувством идёт в искусстве до сих пор."], "groups": [{"h": "Классицизм: разум и порядок", "p": "Образец снова античность, а главная ценность долг перед обществом.", "items": [{"t": "Колоннады и симметрия", "d": "Здания строят по античным правилам: портики, колонны, строгий порядок.", "c": "Казанский собор в Петербурге, 1811", "more": ["Архитектор Андрей Воронихин строил собор десять лет. Его полукруглая колоннада из 96 колонн охватывает площадь, как раскрытые руки. Образец понятен: колоннада собора Святого Петра в Риме.", "Петербург почти весь построен в стиле классицизма: Адмиралтейство, Биржа, Сенат. После войны 1812 года собор стал памятником победе. Здесь похоронен фельдмаршал Кутузов и хранятся французские знамёна."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Kazan_Cathedral_Saint_Petersburg.jpg", "lic": "CC BY-SA 3.0", "by": "This Photo was taken by Wolfgang Moroder.  \n\nFeel free to use my photos, but ple", "src": "media/img/3a8181e131-1000.webp", "w": 1000, "h": 452, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Kazan_Cathedral_Saint_Petersburg.jpg/1280px-Kazan_Cathedral_Saint_Petersburg.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Мрамор как античность", "d": "Скульпторы подражали грекам: гладкий белый мрамор, идеальные тела.", "c": "Антонио Канова. «Психея, оживлённая поцелуем Амура», 1793", "more": ["По мифу, девушка Психея открыла запретный сосуд и уснула мёртвым сном. Её возлюбленный, бог любви Амур, разбудил её поцелуем.", "Итальянец Антонио Канова был самым знаменитым скульптором своего времени. Посмотрите, как фигуры образуют букву X, а руки складываются в круг вокруг лиц. Мрамор отполирован так гладко, что кажется тёплой кожей. Классицизм, но в нём уже есть нежность и чувство."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Psyche_Revived_by_Cupid%27s_Kiss,_Louvre_22_July_2017.jpg", "lic": "CC0", "by": "Joe deSousa", "src": "media/img/b50a95b65c-1000.webp", "w": 1000, "h": 668, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Psyche_Revived_by_Cupid%27s_Kiss%2C_Louvre_22_July_2017.jpg/1280px-Psyche_Revived_by_Cupid%27s_Kiss%2C_Louvre_22_July_2017.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Романтизм: чувство и свобода", "p": "Романтики любили бурю, ночь, катастрофы, экзотику и одиноких героев.", "items": [{"t": "Катастрофа и надежда", "d": "Романтики писали трагические события своего времени.", "c": "Жерико. «Плот „Медузы“», 1819", "more": ["В 1816 году французский корабль «Медуза» сел на мель у берегов Африки. Капитан и офицеры уплыли на шлюпках, а 147 человек бросили на наспех сколоченном плоту. Через 13 дней в живых осталось 15.", "Теодор Жерико разговаривал с выжившими, изучал тела в больнице и построил макет плота. Картина огромная, семь метров в ширину. Фигуры поднимаются пирамидой к человеку, который машет платком далёкому кораблю. Это обвинение властям и одновременно образ надежды."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Theodore_Gericault_Raft_of_the_Medusa-1.jpg", "lic": "Public domain", "by": "Théodore Géricault (1791-1824)", "src": "media/img/c8dda73790-1000.webp", "w": 1000, "h": 678, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c2/Theodore_Gericault_Raft_of_the_Medusa-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Свет и стихия", "d": "Цвет и свет важнее чёткого рисунка.", "c": "Тёрнер. «Последний рейс корабля „Отважный“», 1839", "more": ["Старый военный парусник «Отважный» сражался в знаменитой битве при Трафальгаре. Здесь маленький чёрный пароход тащит его на разборку. Уходит эпоха парусов, приходит эпоха пара.", "Уильям Тёрнер писал так свободно, что современники ругали его картины за «туман». Посмотрите на закат: он горит, как огонь. Корабль-призрак бледный, почти растворяется в воздухе. Через несколько десятилетий импрессионисты будут учиться у Тёрнера."], "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Fighting_Temeraire,_JMW_Turner,_National_Gallery.jpg", "lic": "Public domain", "by": "J. M. W. Turner", "src": "media/img/6fd8772780-1000.webp", "w": 1000, "h": 743, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/The_Fighting_Temeraire%2C_JMW_Turner%2C_National_Gallery.jpg/1280px-The_Fighting_Temeraire%2C_JMW_Turner%2C_National_Gallery.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Романтический портрет", "d": "Не важная особа, а живой человек с внутренним миром.", "c": "Кипренский. Портрет Пушкина, 1827", "more": ["Портрет заказал друг поэта Антон Дельвиг. Пушкину было 28 лет. Он в клетчатом шотландском плаще, руки скрещены, взгляд направлен куда-то в сторону.", "Позади статуя музы с лирой, знак поэтического вдохновения. Сам Пушкин написал о портрете: «Себя как в зеркале я вижу, но это зеркало мне льстит». Это самый известный прижизненный портрет поэта."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Orest_Kiprensky_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BF%D0%BE%D1%8D%D1%82%D0%B0_%D0%90.%D0%A1.%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD%D0%B0_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/7f8c1f87ea-1000.webp", "w": 1000, "h": 1158, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Orest_Kiprensky_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BF%D0%BE%D1%8D%D1%82%D0%B0_%D0%90.%D0%A1.%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD%D0%B0_-_Google_Art_Project.jpg/1280px-Orest_Kiprensky_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%BF%D0%BE%D1%8D%D1%82%D0%B0_%D0%90.%D0%A1.%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD%D0%B0_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a7", "title": "Реализм и импрессионизм", "period": "вторая половина XIX века", "intro": [], "traits": ["Реализм: правда жизни, социальные темы, простые люди", "Передвижники в России: Репин, Суриков, Перов, Левитан", "Импрессионизм: свет, воздух, мимолётное впечатление", "Живопись на пленэре (на открытом воздухе)", "Раздельный мазок, светлая палитра"], "works": [{"t": "Бурлаки на Волге", "a": "Илья Репин", "y": "1870–1873", "d": "Одиннадцать бурлаков тянут баржу. Каждый — отдельная судьба, а молодой Ларька в центре поднимает голову — будто бунтует.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Ilia_Efimovich_Repin_(1844-1930)_-_Volga_Boatmen_(1870-1873).jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/8c2c6391f0-1000.webp", "w": 1000, "h": 462, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Ilia_Efimovich_Repin_%281844-1930%29_-_Volga_Boatmen_%281870-1873%29.jpg/1280px-Ilia_Efimovich_Repin_%281844-1930%29_-_Volga_Boatmen_%281870-1873%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Молодой Илья Репин увидел бурлаков на Неве и был потрясён контрастом: рядом нарядная публика гуляет, а люди, как скот, тянут баржу. Летом 1870 года он поехал на Волгу, жил среди бурлаков и делал зарисовки. Картину закончил в 1873 году.", "Бурлаки тащили суда против течения на длинной лямке. Здесь одиннадцать человек, и у каждого свой характер. Впереди мудрый Канин, бывший священник. В центре молодой Ларька поправляет лямку и поднимает голову, будто не хочет мириться с такой жизнью.", "Картину купил великий князь Владимир Александрович, и она объехала выставки Европы. Она сделала Репина знаменитым."]}, {"t": "Впечатление. Восходящее солнце", "a": "Клод Моне", "y": "1872", "d": "Картина, давшая имя целому направлению. Порт Гавра в утренней дымке, оранжевое солнце из нескольких мазков.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Monet_-_Impression,_Sunrise.jpg", "lic": "Public domain", "by": "Claude Monet", "src": "media/img/d79ad960ff-1000.webp", "w": 1000, "h": 776, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Monet_-_Impression%2C_Sunrise.jpg/1280px-Monet_-_Impression%2C_Sunrise.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Клод Моне написал вид порта в городе Гавр утром 1872 года. Туман, силуэты кораблей, лодки, и оранжевый круг солнца с бликом на воде, всё буквально несколькими мазками.", "В 1874 году группа молодых художников, которых не пускали на официальный парижский Салон, устроила свою выставку. Моне назвал эту картину «Впечатление», по-французски impression. Критик Луи Леруа в насмешку назвал всех участников «импрессионистами». Художникам название понравилось, и они его оставили.", "Интересно, что солнце на картине той же яркости, что и небо вокруг. Если сделать её чёрно-белой, солнце почти исчезнет. Его выделяет только цвет."]}, {"t": "Бал в Мулен де ла Галетт", "a": "Пьер Огюст Ренуар", "y": "1876", "d": "Танцы на Монмартре. Солнечные пятна скользят по одежде и лицам — сама радость жизни.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Pierre-Auguste_Renoir,_Le_Moulin_de_la_Galette.jpg", "lic": "Public domain", "by": "Pierre-Auguste Renoir", "src": "media/img/4850d8c9de-1000.webp", "w": 1000, "h": 745, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Pierre-Auguste_Renoir%2C_Le_Moulin_de_la_Galette.jpg/1280px-Pierre-Auguste_Renoir%2C_Le_Moulin_de_la_Galette.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Мулен де ла Галетт это танцевальное кафе возле старой мельницы на холме Монмартр в Париже. По воскресеньям сюда приходили рабочие, швеи, художники. Пьер Огюст Ренуар написал картину в 1876 году прямо на месте.", "Друзья Ренуара позировали ему, сидя за столиками. Солнце пробивается сквозь листву и рассыпается пятнами по одежде, лицам и земле. Ренуар писал тени не серыми, а голубыми и сиреневыми, как они выглядят в солнечный день.", "Картина передаёт ощущение счастливого летнего дня. Ренуар говорил, что картина должна быть приятной и радостной, неприятного в жизни и так хватает."]}, {"t": "Над вечным покоем", "a": "Исаак Левитан", "y": "1894", "d": "Пейзаж настроения: маленькая церковь и кладбище над бескрайним простором. Левитан называл картину самой своей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:LevitanAboveEternalPeace.jpg", "lic": "Public domain", "by": "Isaac Levitan", "src": "media/img/2a3260c8a1-1000.webp", "w": 1000, "h": 723, "remote": "https://upload.wikimedia.org/wikipedia/commons/0/08/LevitanAboveEternalPeace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Исаак Левитан написал картину в 1894 году на озере Удомля в Тверской губернии. Маленькая деревянная церковь и старое кладбище стоят на высоком берегу, а внизу огромная вода и тяжёлые облака.", "Сам Левитан писал, что в этой картине весь он, его характер. Человеческая жизнь и вечность природы, маленький огонёк в окне церкви и бесконечный простор. Такие картины называют пейзажем настроения: главное не вид, а чувство, которое он вызывает.", "Левитан был учеником Саврасова и другом Чехова. Картину купил Павел Третьяков для своей галереи."]}, {"t": "Голубые танцовщицы", "a": "Эдгар Дега", "y": "около 1897", "d": "Дега любил балет, но показывал его закулисье. Пастель, необычный ракурс — будто подсмотренный кадр.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edgar_Degas_-_Blue_Dancers_(1898_Pushkin_Museum).jpg", "lic": "Public domain", "by": "Edgar Degas", "src": "media/img/5f2527d3eb-1000.webp", "w": 1000, "h": 983, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Edgar_Degas_-_Blue_Dancers_%281898_Pushkin_Museum%29.jpg/1280px-Edgar_Degas_-_Blue_Dancers_%281898_Pushkin_Museum%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Эдгар Дега больше всего любил писать балет, но не спектакль, а закулисье: репетиции, разминку, усталость, поправленные лямки платья.", "Здесь четыре балерины в голубых пачках готовятся к выходу. Мы видим их сверху и сбоку, фигуры обрезаны краем картины, как на случайном снимке. Дега увлекался фотографией и японскими гравюрами, отсюда такие необычные ракурсы.", "Картина сделана пастелью, это цветные мелки. К старости зрение Дега ухудшилось, и он перешёл на пастель, потому что ей можно работать быстро и крупными штрихами. Цвета стали ярче и смелее."]}], "quiz": [{"q": "Откуда взялось слово «импрессионизм»?", "o": ["Из названия картины Моне «Впечатление»", "Из имени художника", "Из названия кафе", "Из манифеста Курбе"], "a": 0, "e": "«Impression, soleil levant» Моне, выставка 1874 года."}, {"q": "Как назывались русские реалисты, возившие выставки по стране?", "o": ["Мирискусники", "Передвижники", "Бубновалетовцы", "Символисты"], "a": 1, "e": "Товарищество передвижных художественных выставок, с 1870 года."}, {"q": "Что главное для импрессиониста?", "o": ["Мораль и долг", "Мгновенное впечатление: свет и воздух", "Геометрия формы", "Религиозный смысл"], "a": 1, "e": "Импрессионисты ловили мимолётное состояние природы."}], "why": ["Во второй половине XIX века художники решили писать то, что видят вокруг, а не мифы и героев. Реалисты показывали жизнь простых людей и социальную несправедливость. Импрессионисты пошли дальше и стали ловить мгновение: свет, воздух, движение. С этого момента живопись становится современной, и почти всё искусство XX века вырастает из импрессионизма."], "groups": [{"h": "Реализм: правда жизни", "p": "Художники рисуют крестьян, рабочих, бедных. Это было вызовом: такие сюжеты считали недостойными больших картин.", "items": [{"t": "Тяжёлый труд", "d": "Простые люди становятся героями больших картин.", "c": "Милле. «Сборщицы колосьев», 1857", "more": ["После жатвы бедным разрешали подбирать оставшиеся на поле колоски. Жан-Франсуа Милле показал трёх крестьянок, которые весь день гнут спину ради горсти зерна. Вдали виден богатый урожай, стога и телега.", "Богатые зрители испугались картины: им показалось, что она призывает к бунту. Милле же просто уважал крестьянский труд и писал фигуры спокойными и величественными, как статуи."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project_2.jpg", "lic": "Public domain", "by": "Jean-François Millet", "src": "media/img/4d54f6ccfc-1000.webp", "w": 1000, "h": 748, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project_2.jpg/1280px-Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Передвижники", "d": "Русские художники возили свои выставки по стране.", "c": "Перов. «Тройка», 1866", "more": ["Трое маленьких учеников мастерового зимой тащат по Москве огромную бочку с водой. Ветер, мороз, сзади помогает подтолкнуть прохожий. Дети измучены.", "В 1870 году русские реалисты создали Товарищество передвижных художественных выставок. Они возили картины по городам, чтобы искусство увидели не только в столицах. Василий Перов был одним из основателей. Мальчика в центре он писал с крестьянского сына Васи, который вскоре умер. Позже мать мальчика пришла к Перову и долго молилась у картины."], "img": {"page": "https://commons.wikimedia.org/wiki/File:%D0%A2%D1%80%D0%BE%D0%B9%D0%BA%D0%B0_-_%D0%92%D0%B0%D1%81%D0%B8%D0%BB%D0%B8%D0%B9_%D0%93%D1%80%D0%B8%D0%B3%D0%BE%D1%80%D1%8C%D0%B5%D0%B2%D0%B8%D1%87_%D0%9F%D0%B5%D1%80%D0%BE%D0%B2_(1866).jpg", "lic": "Public domain", "by": "Vasily Perov", "src": "media/img/5e295a21ce-1000.webp", "w": 1000, "h": 730, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/%D0%A2%D1%80%D0%BE%D0%B9%D0%BA%D0%B0_-_%D0%92%D0%B0%D1%81%D0%B8%D0%BB%D0%B8%D0%B9_%D0%93%D1%80%D0%B8%D0%B3%D0%BE%D1%80%D1%8C%D0%B5%D0%B2%D0%B8%D1%87_%D0%9F%D0%B5%D1%80%D0%BE%D0%B2_%281866%29.jpg/1280px-%D0%A2%D1%80%D0%BE%D0%B9%D0%BA%D0%B0_-_%D0%92%D0%B0%D1%81%D0%B8%D0%BB%D0%B8%D0%B9_%D0%93%D1%80%D0%B8%D0%B3%D0%BE%D1%80%D1%8C%D0%B5%D0%B2%D0%B8%D1%87_%D0%9F%D0%B5%D1%80%D0%BE%D0%B2_%281866%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "История как драма", "d": "Исторические картины передвижников показывают характеры и столкновения.", "c": "Суриков. «Боярыня Морозова», 1887", "more": ["В XVII веке в России произошёл раскол церкви. Боярыня Феодосия Морозова отказалась принять новые обряды. Её арестовали и увозят на санях. Она поднимает руку с двумя пальцами, старым крестным знамением, и не сдаётся.", "Толпа реагирует по-разному: кто-то смеётся, кто-то плачет, нищий юродивый повторяет её жест. Василий Суриков долго искал лицо боярыни и нашёл его у своей тётки. Снег он писал с натуры, ходил по сугробам после проезда саней."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Surikov_Boyarynya_Morozova_gtg.jpg", "lic": "Public domain", "by": "Vasily Surikov", "src": "media/img/88b56450b6-1000.webp", "w": 1000, "h": 500, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Surikov_Boyarynya_Morozova_gtg.jpg/1280px-Surikov_Boyarynya_Morozova_gtg.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Импрессионизм: мгновение и свет", "p": "Художники вышли с мольбертами на улицу и писали быстро, отдельными мазками, чтобы поймать меняющийся свет.", "items": [{"t": "Один мотив, разный свет", "d": "Одно и то же место в разное время дня выглядит по-разному.", "c": "Моне. Руанский собор на закате, 1894", "more": ["Клод Моне снял комнату напротив собора в Руане и написал его фасад больше тридцати раз: утром, днём, вечером, в солнце и в тумане. Он работал над несколькими холстами сразу и менял их, когда менялся свет.", "Камень на этих картинах то голубой, то розовый, то золотой. Моне показывал, что цвет предмета не постоянен: мы видим свет, который от него отражается. Собор здесь почти растворился в воздухе."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Claude_Monet_-_Rouen_Cathedral,_Facade_(Sunset).JPG", "lic": "Public domain", "by": "Claude Monet", "src": "media/img/b2bd4bed00-1000.webp", "w": 1000, "h": 1560, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Claude_Monet_-_Rouen_Cathedral%2C_Facade_%28Sunset%29.JPG/1280px-Claude_Monet_-_Rouen_Cathedral%2C_Facade_%28Sunset%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Пруд с кувшинками", "d": "В поздних картинах Моне почти исчезает горизонт.", "c": "Моне. «Кувшинки»", "more": ["В деревне Живерни Моне устроил сад с прудом, японским мостиком и кувшинками и почти тридцать лет писал только его, около 250 картин.", "В поздних работах нет ни неба, ни берега. Только вода, отражения облаков и цветы на поверхности. Зритель как будто смотрит вниз в пруд. К концу жизни Моне почти ослеп, и краски стали ещё ярче и свободнее. Многие видят в этих картинах шаг к абстрактному искусству."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Claude_Monet_-_Seerosen.jpg", "lic": "Public domain", "by": "Claude Monet", "src": "media/img/90db12e7ee-1000.webp", "w": 1000, "h": 741, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Claude_Monet_-_Seerosen.jpg/1280px-Claude_Monet_-_Seerosen.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a8", "title": "Постимпрессионизм и модерн", "period": "1880-е — 1910-е", "intro": [], "traits": ["Ван Гог: экспрессивный мазок, яркий цвет", "Сезанн: геометрия формы — отец современного искусства", "Гоген: плоские яркие пятна, экзотика", "Модерн: плавные линии, орнамент, золото", "Символизм: сны, тревога, внутренний мир"], "works": [{"t": "Звёздная ночь", "a": "Винсент ван Гог", "y": "1889", "d": "Написана в лечебнице Сен-Реми. Небо закручено в вихри, кипарис взлетает пламенем — пейзаж души.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Vincent van Gogh", "src": "media/img/ffa8e3768f-1000.webp", "w": 1000, "h": 792, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg/1280px-Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["В 1889 году Ван Гог добровольно лёг в лечебницу в городке Сен-Реми на юге Франции. Из окна палаты он видел холмы и деревню. Картину он написал по памяти, днём, в мастерской.", "Небо закручено вихрями, звёзды и луна горят огромными кругами света. Слева тёмный кипарис поднимается, как пламя. Деревня внизу спокойная и тихая, в окнах огоньки. Многие видят в этом контраст бурного внутреннего мира художника и мирной жизни.", "Ван Гог считал картину неудачной. Сейчас это одна из самых узнаваемых картин в мире, она хранится в Нью-Йорке, в Музее современного искусства."]}, {"t": "Гора Сент-Виктуар", "a": "Поль Сезанн", "y": "около 1904", "d": "Сезанн писал эту гору десятки раз, строя пейзаж из цветовых плоскостей. Пикассо называл его «отцом всех нас».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Montagne_Sainte-Victoire,_par_Paul_C%C3%A9zanne_108.jpg", "lic": "Public domain", "by": "Paul Cézanne", "src": "media/img/2ed60c49d5-1000.webp", "w": 1000, "h": 794, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Montagne_Sainte-Victoire%2C_par_Paul_C%C3%A9zanne_108.jpg/1280px-Montagne_Sainte-Victoire%2C_par_Paul_C%C3%A9zanne_108.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Поль Сезанн жил в городе Экс-ан-Прованс и больше шестидесяти раз изобразил гору Сент-Виктуар, которая видна оттуда.", "На поздних картинах гора, деревья и дома сложены из цветовых плоскостей, как из кирпичиков. Тёплые цвета выступают вперёд, холодные голубые уходят назад. Так Сезанн строит пространство цветом, без привычной перспективы.", "Молодые художники ездили к Сезанну учиться. Пикассо назвал его «отцом всех нас». Без Сезанна не было бы кубизма и абстракции."]}, {"t": "Откуда мы? Кто мы? Куда мы идём?", "a": "Поль Гоген", "y": "1897–1898", "d": "Таитянская притча о жизни: читается справа налево, от младенца до старости.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Paul_Gauguin_-_D%27ou_venons-nous.jpg", "lic": "Public domain", "by": "Paul Gauguin", "src": "media/img/42835591cb-1000.webp", "w": 1000, "h": 380, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Paul_Gauguin_-_D%27ou_venons-nous.jpg/1280px-Paul_Gauguin_-_D%27ou_venons-nous.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Поль Гоген бросил работу биржевого маклера, оставил семью и уехал на остров Таити в Тихом океане, чтобы жить простой жизнью. Картину он написал в 1897 году, когда был тяжело болен и думал о смерти.", "Её читают справа налево. Справа младенец, начало жизни. В центре человек срывает плод, это зрелость. Слева старуха, которая ждёт конца. Синий идол на заднем плане символизирует потустороннее.", "Цвета плоские и яркие, без теней, контуры обведены. Гоген учился у японских гравюр и средневековых витражей. Это картина-размышление о смысле жизни, отсюда и название в виде трёх вопросов."]}, {"t": "Поцелуй", "a": "Густав Климт", "y": "1907–1908", "d": "«Золотой период» Климта: настоящее сусальное золото, мужской орнамент из прямоугольников, женский — из кругов.", "img": {"page": "https://commons.wikimedia.org/wiki/File:The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg", "lic": "Public domain", "by": "Gustav Klimt", "src": "media/img/1ff5535fac-1000.webp", "w": 1000, "h": 1003, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg/1280px-The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Венский художник Густав Климт написал картину в 1907–1908 годах. Её сразу купило государство, ещё до окончания выставки.", "Влюблённые стоят на краю цветущего луга, у самого обрыва. Их одежды сливаются в одно золотое облако. У мужчины в узоре прямоугольники, у женщины круги и цветы. Так Климт показал мужское и женское начало.", "Отец Климта был ювелиром и гравёром по золоту, и Климт использовал настоящее сусальное золото. Он вдохновлялся византийскими мозаиками, которые видел в Равенне. Этот период его творчества называют золотым."]}, {"t": "Крик", "a": "Эдвард Мунк", "y": "1893", "d": "Мунк описал миг, когда «почувствовал бесконечный крик природы». Символ тревоги нового века.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edvard_Munch,_1893,_The_Scream,_oil,_tempera_and_pastel_on_cardboard,_91_x_73_cm,_National_Gallery_of_Norway.jpg", "lic": "Public domain", "by": "Edvard Munch", "src": "media/img/2119e6f136-1000.webp", "w": 1000, "h": 1241, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Edvard_Munch%2C_1893%2C_The_Scream%2C_oil%2C_tempera_and_pastel_on_cardboard%2C_91_x_73_cm%2C_National_Gallery_of_Norway.jpg/1280px-Edvard_Munch%2C_1893%2C_The_Scream%2C_oil%2C_tempera_and_pastel_on_cardboard%2C_91_x_73_cm%2C_National_Gallery_of_Norway.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Норвежский художник Эдвард Мунк описал в дневнике: он шёл с друзьями на закате, небо стало кроваво-красным, друзья ушли вперёд, а он остановился и почувствовал огромный бесконечный крик, проходящий сквозь природу.", "Фигура на переднем плане не кричит, а слышит крик и зажимает уши. Её лицо похоже на череп. Линии неба, воды и тела изгибаются волнами, только мост прямой.", "Мунк сделал несколько версий: две картины, пастели и литографии. Картина стала символом тревоги современного человека. Это начало экспрессионизма, искусства, где главное передать сильное чувство."]}], "quiz": [{"q": "Кого называют «отцом современного искусства»?", "o": ["Моне", "Сезанна", "Ренуара", "Курбе"], "a": 1, "e": "Сезанн строил форму геометрически — из этого выросли кубизм и абстракция."}, {"q": "Какой стиль около 1900 года любил плавные растительные линии и орнамент?", "o": ["Барокко", "Модерн (ар-нуво)", "Кубизм", "Классицизм"], "a": 1, "e": "Модерн: Климт, Муха, Гауди, Шехтель."}, {"q": "Куда уехал Гоген в поисках первозданной жизни?", "o": ["В Японию", "На Таити", "В Египет", "В Россию"], "a": 1, "e": "Полинезия, Таити — его главные картины написаны там."}], "why": ["К концу XIX века молодым художникам импрессионизма стало мало. Им хотелось передать не только свет, но и чувства, порядок, символы. Каждый пошёл своим путём, и от этих путей разошлись дороги всего искусства XX века: экспрессионизм, кубизм, абстракция. Одновременно возник модерн, первый стиль, который охватил всё сразу, от зданий до афиш и ложек."], "groups": [{"h": "Четыре пути после импрессионизма", "p": "Художников этого времени называют постимпрессионистами. Общего стиля у них нет, у каждого свой метод.", "items": [{"t": "Цвет как чувство", "d": "Ван Гог усиливал цвет, чтобы передать эмоцию.", "c": "Ван Гог. «Подсолнухи», 1888", "more": ["Винсент Ван Гог написал серию подсолнухов в Арле на юге Франции, чтобы украсить комнату для своего друга Гогена. Жёлтый был для него цветом солнца, дружбы и надежды.", "Здесь почти всё жёлтое: фон, ваза, цветы. Краска положена толстыми рельефными мазками, их можно почти потрогать. Одни цветы распустились, другие уже вянут. При жизни Ван Гог продал всего одну картину, а в 1987 году одна из его «Подсолнухов» стала самой дорогой картиной в мире."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vincent_van_Gogh_-_Sunflowers_(1888,_National_Gallery_London).jpg", "lic": "Public domain", "by": "Vincent van Gogh", "src": "media/img/7625bce43c-1000.webp", "w": 1000, "h": 1271, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Vincent_van_Gogh_-_Sunflowers_%281888%2C_National_Gallery_London%29.jpg/1280px-Vincent_van_Gogh_-_Sunflowers_%281888%2C_National_Gallery_London%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Форма как порядок", "d": "Сезанн строил предметы из простых форм.", "c": "Сезанн. «Корзина с яблоками», около 1893", "more": ["Поль Сезанн говорил, что всё в природе можно свести к шару, цилиндру и конусу. Его яблоки тяжёлые и плотные, как будто из камня.", "Посмотрите внимательнее: край стола слева и справа на разной высоте, бутылка наклонена, корзина видна сверху, а стол сбоку. Сезанн показывает предметы сразу с нескольких точек зрения. Через пятнадцать лет Пикассо и Брак разовьют эту идею в кубизм."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg", "lic": "Public domain", "by": "Paul Cézanne", "src": "media/img/11ebd1d159-1000.webp", "w": 1000, "h": 800, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg/1280px-Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Точки вместо мазков", "d": "Сёра складывал картину из мелких цветных точек.", "c": "Сёра. «Воскресный день на острове Гранд-Жатт», 1884–1886", "more": ["Жорж Сёра изучал научные книги о цвете и решил не смешивать краски на палитре. Он ставил рядом крошечные точки чистого цвета, а глаз зрителя сам смешивает их на расстоянии. Этот метод назвали пуантилизмом, от французского point, «точка».", "Работа над картиной заняла два года. Парижане отдыхают на острове посреди Сены. Фигуры застывшие, как статуи, всё очень упорядоченно. Подойдите близко, и картина распадётся на точки, отойдите, и снова сложится."], "img": {"page": "https://commons.wikimedia.org/wiki/File:A_Sunday_on_La_Grande_Jatte,_Georges_Seurat,_1884.jpg", "lic": "Public domain", "by": "Georges Seurat", "src": "media/img/5892cb3721-1000.webp", "w": 1000, "h": 666, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/A_Sunday_on_La_Grande_Jatte%2C_Georges_Seurat%2C_1884.jpg/1280px-A_Sunday_on_La_Grande_Jatte%2C_Georges_Seurat%2C_1884.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Модерн: красота во всём", "p": "Около 1900 года стиль модерн охватил всю Европу. Его узнают по плавным изогнутым линиям, растительным узорам и женским фигурам.", "items": [{"t": "Дом как живое существо", "d": "Архитекторы модерна избегали прямых углов.", "c": "Антонио Гауди. Дом Бальо, Барселона, 1906", "more": ["Испанский архитектор Антонио Гауди перестроил обычный жилой дом для богатого текстильщика. Фасад покрыт мозаикой из цветной керамики и стекла, балконы похожи на маски, колонны на кости.", "Крышу Гауди сделал в виде спины дракона с чешуёй, а башенку с крестом в виде копья святого Георгия, который победил дракона. Внутри почти нет прямых линий, всё плавное, как в морской раковине. Гауди говорил, что прямая линия принадлежит людям, а кривая Богу."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Facade_of_Casa_Batll%C3%B3.jpg", "lic": "CC BY 4.0", "by": "Mattsjc", "src": "media/img/5e58e6ca9e-1000.webp", "w": 1000, "h": 1333, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Facade_of_Casa_Batll%C3%B3.jpg/1280px-Facade_of_Casa_Batll%C3%B3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Афиша как искусство", "d": "Плакаты модерна собирали как картины.", "c": "Альфонс Муха. Афиша «Жисмонда», 1894", "more": ["На Рождество 1894 года знаменитой актрисе Саре Бернар срочно понадобилась афиша для спектакля. Все художники были в отпуске, и заказ получил никому не известный чех Альфонс Муха.", "Он сделал высокую узкую афишу почти в рост человека: актриса в византийском наряде, мягкие пастельные цвета, мозаичный нимб. Парижане срывали афиши с улиц, чтобы забрать домой. Сара Бернар подписала с Мухой договор на шесть лет, и его стиль стал лицом модерна."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Alphonse_Mucha_-_Poster_for_Victorien_Sardou%27s_Gismonda_starring_Sarah_Bernhardt.jpg", "lic": "Public domain", "by": "Alphonse Mucha / Adam Cuerden", "src": "media/img/64de535394-1000.webp", "w": 1000, "h": 2829, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Alphonse_Mucha_-_Poster_for_Victorien_Sardou%27s_Gismonda_starring_Sarah_Bernhardt.jpg/1280px-Alphonse_Mucha_-_Poster_for_Victorien_Sardou%27s_Gismonda_starring_Sarah_Bernhardt.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Русский символизм", "d": "Таинственные образы и мозаичный мазок.", "c": "Врубель. «Демон сидящий», 1890", "more": ["Михаил Врубель иллюстрировал поэму Лермонтова «Демон». Демон у него не злой, а одинокий и печальный, сильный юноша, который тоскует.", "Мазки положены гранями, как кристаллы или мозаика, цветы вокруг похожи на камни. Врубель много лет возвращался к образу Демона, это стало главной темой его жизни. Его считают первым русским художником модерна."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Vrubel_Demon.jpg", "lic": "Public domain", "by": "Mikhail Vrubel", "src": "media/img/625e6f6d2f-1000.webp", "w": 1000, "h": 531, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Vrubel_Demon.jpg/1280px-Vrubel_Demon.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}, {"id": "a9", "title": "Авангард XX века", "period": "1905 — 1930-е", "intro": [], "traits": ["Фовизм: «дикий» чистый цвет", "Кубизм: предмет разложен на грани", "Абстракция: картина без сюжета", "Русский авангард: Малевич (супрематизм), Кандинский", "Сюрреализм: логика сна и подсознания"], "works": [{"t": "Чёрный супрематический квадрат", "a": "Казимир Малевич", "y": "1915", "d": "Манифест супрематизма. На выставке 1915 года Малевич повесил его в «красный угол», где в русском доме висит икона.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kazimir_Malevich,_1915,_Black_Suprematic_Square,_oil_on_linen_canvas,_79.5_x_79.5_cm,_Tretyakov_Gallery,_Moscow.jpg", "lic": "Public domain", "by": "Kazimir Malevich", "src": "media/img/2819ba4ed9-1000.webp", "w": 1000, "h": 1000, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Kazimir_Malevich%2C_1915%2C_Black_Suprematic_Square%2C_oil_on_linen_canvas%2C_79.5_x_79.5_cm%2C_Tretyakov_Gallery%2C_Moscow.jpg/1280px-Kazimir_Malevich%2C_1915%2C_Black_Suprematic_Square%2C_oil_on_linen_canvas%2C_79.5_x_79.5_cm%2C_Tretyakov_Gallery%2C_Moscow.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Казимир Малевич показал «Чёрный квадрат» в декабре 1915 года в Петрограде на выставке «0,10». Он повесил его под потолком в углу, где в русском доме висит икона.", "Малевич назвал своё направление супрематизм, от латинского «высший». Он считал, что картина не должна изображать предметы. Чёрный квадрат на белом это «ноль форм», точка, с которой начинается новое искусство из чистых фигур и цвета.", "Квадрат на самом деле не идеальный, стороны немного разные. Под чёрной краской учёные нашли другие изображения и надпись карандашом. Малевич потом написал ещё несколько версий квадрата. Картина хранится в Третьяковской галерее."]}, {"t": "Композиция VII", "a": "Василий Кандинский", "y": "1913", "d": "Кандинский мыслил картину как симфонию: цвета звучат, линии играют мелодию. Одна из вершин ранней абстракции.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Vassily_Kandinsky,_1913_-_Composition_7.jpg", "lic": "Public domain", "by": "Wassily Kandinsky", "src": "media/img/c7747cc859-1000.webp", "w": 1000, "h": 657, "remote": "https://upload.wikimedia.org/wikipedia/commons/b/b4/Vassily_Kandinsky%2C_1913_-_Composition_7.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}, "story": ["Василий Кандинский был юристом и в 30 лет бросил карьеру ради живописи. Он одним из первых пришёл к абстракции, картине без узнаваемых предметов.", "Кандинский слышал цвета как музыку: жёлтый звучал для него как труба, синий как виолончель. Свои большие абстракции он называл «композициями», как музыкальные произведения. «Композицию VII» он написал в 1913 году за четыре дня, после тридцати подготовительных эскизов.", "Здесь можно угадать мотивы Апокалипсиса, всемирного потопа и воскресения, но они растворены в вихре цвета. Картина хранится в Третьяковской галерее."]}, {"t": "Композиция с красным, синим и жёлтым", "a": "Пит Мондриан", "y": "1930", "d": "Только прямые линии и три основных цвета. Стиль Мондриана потом разошёлся по дизайну, моде и архитектуре.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Piet_Mondriaan,_1930_-_Mondrian_Composition_II_in_Red,_Blue,_and_Yellow.jpg", "lic": "Public domain", "by": "Piet Mondrian", "src": "media/img/fe74d0d700-1000.webp", "w": 1000, "h": 1014, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Piet_Mondriaan%2C_1930_-_Mondrian_Composition_II_in_Red%2C_Blue%2C_and_Yellow.jpg/1280px-Piet_Mondriaan%2C_1930_-_Mondrian_Composition_II_in_Red%2C_Blue%2C_and_Yellow.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Голландский художник Пит Мондриан начинал с обычных пейзажей деревьев. Постепенно он упрощал их, пока не остались только линии.", "В его зрелых картинах есть только чёрные горизонтальные и вертикальные линии, белый фон и три основных цвета: красный, синий, жёлтый. Мондриан искал гармонию и равновесие, как в музыке или математике.", "Его стиль ушёл далеко за пределы живописи. Платье Ива Сен-Лорана 1965 года, обложки, мебель, плитка в метро повторяют решётки Мондриана."]}, {"t": "Красный конь (Купание красного коня)", "a": "Кузьма Петров-Водкин", "y": "1912", "d": "Конь цвета иконного киновари, сферическая перспектива. Современники видели в нём предчувствие судьбы России.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Bathing_of_a_Red_Horse_(Petrov-Vodkin).jpg", "lic": "Public domain", "by": "Kuzma Petrov-Vodkin", "src": "media/img/30ebf4db21-1000.webp", "w": 1000, "h": 880, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Bathing_of_a_Red_Horse_%28Petrov-Vodkin%29.jpg/1280px-Bathing_of_a_Red_Horse_%28Petrov-Vodkin%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, "story": ["Кузьма Петров-Водкин написал картину в 1912 году. Он вырос на Волге, в детстве купал лошадей и потом писал этюды в деревне.", "Конь не настоящего цвета, а ярко-красного, как киноварь на древних иконах. Мальчик на нём хрупкий и задумчивый. Земля и озеро немного выгнуты, будто мы видим кусочек планеты. Петров-Водкин называл это сферической перспективой.", "Через два года началась Первая мировая война, потом революция. Многие увидели в красном коне предчувствие судьбы России. Сам художник говорил, что просто учился у икон чистому цвету."]}], "quiz": [{"q": "Как называется направление Малевича?", "o": ["Кубизм", "Супрематизм", "Фовизм", "Сюрреализм"], "a": 1, "e": "Супрематизм — от лат. supremus, «высший»: превосходство чистой формы и цвета."}, {"q": "Что такое абстракция?", "o": ["Портрет в профиль", "Живопись без изображения узнаваемых предметов", "Пейзаж ночью", "Копия античной статуи"], "a": 1, "e": "Абстракция говорит формой и цветом, как музыка звуком."}, {"q": "Кубисты…", "o": ["Писали только кубы", "Раскладывали предмет на грани, показывая с разных сторон", "Писали на пленэре", "Копировали иконы"], "a": 1, "e": "Пикассо и Брак показывали предмет одновременно с нескольких точек зрения."}], "why": ["Начало XX века перевернуло искусство. Фотография научилась точно изображать мир, и художникам больше не нужно было копировать реальность. Они начали искать новый язык: чистый цвет, разложенные формы, картины совсем без изображения. Многое в современном дизайне, логотипах и архитектуре выросло из авангарда, и русские художники сыграли в нём одну из главных ролей."], "groups": [{"h": "Освобождение цвета и формы", "p": "Цвет и форма больше не обязаны быть похожими на настоящие.", "items": [{"t": "Фовизм: дикий цвет", "d": "Цвет выбирают по чувству, а не по правде.", "c": "Анри Матисс. «Женщина в шляпе», 1905", "more": ["Анри Матисс написал портрет своей жены. Лицо у неё зелёное, розовое и жёлтое, фон из пятен. На выставке 1905 года критик назвал Матисса и его друзей «дикими», по-французски fauves. Так появилось слово «фовизм».", "Матисс не хотел сделать жену некрасивой. Он считал, что цвет должен передавать радость и силу, а не точный оттенок кожи. Позже его картины «Танец» и «Музыку» заказал русский коллекционер Сергей Щукин, и сейчас они в Эрмитаже."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Matisse-Woman-with-a-Hat.jpg", "lic": "Public domain", "by": "Henri Matisse", "src": "media/img/d858d65f04-1000.webp", "w": 1000, "h": 1361, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Matisse-Woman-with-a-Hat.jpg/1280px-Matisse-Woman-with-a-Hat.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Экспрессионизм", "d": "Цвет и форма передают внутренний мир.", "c": "Франц Марк. «Синий конь», 1911", "more": ["Немецкий художник Франц Марк считал, что животные чище и честнее людей. Каждому цвету он приписывал смысл: синий означал мужское, духовное начало, жёлтый женское и радостное.", "Вместе с Кандинским он основал группу «Синий всадник». Марк погиб на Первой мировой войне в 1916 году, ему было 36 лет."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Marc,_Franz_-_Blue_Horse_I_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Franz Marc", "src": "media/img/f27edba562-1000.webp", "w": 1000, "h": 1335, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Marc%2C_Franz_-_Blue_Horse_I_-_Google_Art_Project.jpg/1280px-Marc%2C_Franz_-_Blue_Horse_I_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Футуризм: скорость", "d": "Итальянцы восхищались машинами и скоростью.", "c": "Боччони. «Уникальные формы непрерывности в пространстве», 1913", "more": ["Футуристы, от латинского «будущее», объявили, что гоночный автомобиль прекраснее античной статуи. Они хотели показать в искусстве движение и скорость нового века.", "Скульптура Умберто Боччони изображает шагающего человека, но воздух как будто обтекает и рвёт его форму. Это напоминает фотографию на длинной выдержке. Изображение статуи сегодня есть на итальянской монете в 20 евроцентов."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Unique_Forms_of_Continuity_in_Space_MET_DT6411.jpg", "lic": "CC0", "by": "Umberto Boccioni", "src": "media/img/e8d3b6e1bd-1000.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Unique_Forms_of_Continuity_in_Space_MET_DT6411.jpg/1280px-Unique_Forms_of_Continuity_in_Space_MET_DT6411.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}, {"h": "Русский авангард", "p": "В 1910–1920-х годах Россия стала одним из центров нового искусства. После революции авангард пошёл в плакаты, архитектуру и дизайн.", "items": [{"t": "Плакат из геометрии", "d": "Простые фигуры рассказывают политическую историю.", "c": "Эль Лисицкий. «Клином красным бей белых», 1919", "more": ["Во время Гражданской войны Лазарь Лисицкий, ученик Малевича, сделал плакат из одних фигур. Красный треугольник, Красная армия, врезается в белый круг, армию белых.", "Здесь нет ни одного человека, но смысл понятен с первого взгляда. Такой язык простых форм, цвета и коротких надписей потом перешёл в рекламу, логотипы и графический дизайн всего мира."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Beat_the_Whites_with_the_Red_Wedge.jpg", "lic": "Public domain", "by": "El Lissitzky", "src": "media/img/c132978d7b-1000.webp", "w": 1000, "h": 819, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Beat_the_Whites_with_the_Red_Wedge.jpg/1280px-Beat_the_Whites_with_the_Red_Wedge.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Башня-мечта", "d": "Архитектура будущего, которую так и не построили.", "c": "Модель башни Татлина, реконструкция", "more": ["В 1919 году Владимир Татлин спроектировал памятник Третьему Интернационалу: наклонную спиральную башню из стали высотой 400 метров, выше Эйфелевой. Внутри должны были вращаться залы с разной скоростью: раз в год, раз в месяц, раз в день.", "Построить её было невозможно, в стране не хватало даже металла. Остались только модели. Но башня стала символом авангарда: искусство должно было не украшать жизнь, а строить новый мир."], "img": {"page": "https://commons.wikimedia.org/wiki/File:Model_of_Tatlin_Tower,_Royal_Academy,_London,_27_Feb_2012.jpg", "lic": "CC BY-SA 3.0", "by": "TobyJ", "src": "media/img/46908d9acb-1000.webp", "w": 1000, "h": 1333, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Model_of_Tatlin_Tower%2C_Royal_Academy%2C_London%2C_27_Feb_2012.jpg/1280px-Model_of_Tatlin_Tower%2C_Royal_Academy%2C_London%2C_27_Feb_2012.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}]}]}], "music": [{"id": "m0", "title": "Как слушать музыку", "period": "Азбука", "intro": ["Музыка складывается из нескольких «кирпичиков». Мелодия — то, что можно напеть. Ритм — пульс и рисунок длительностей. Гармония — аккорды, на которых держится мелодия. Тембр — «окраска» звука: скрипку не спутаешь с трубой.", "Ещё важны темп (быстро или медленно), динамика (громко или тихо: форте и пиано) и лад. Мажор обычно звучит светло, минор — грустно или тревожно.", "Классическую музыку легче слушать, если знать её формы. Симфония — большое сочинение для оркестра из нескольких частей. Соната — то же для одного-двух инструментов. Концерт — солист соревнуется с оркестром. Опера — драма, где поют, а балет — где танцуют. Включите примеры ниже и попробуйте услышать разницу."], "traits": ["Мелодия, ритм, гармония, тембр", "Мажор — светло, минор — грустно", "Темп: адажио (медленно), аллегро (быстро), престо (очень быстро)", "Динамика: пиано (тихо), форте (громко)", "Формы: симфония, соната, концерт, опера, балет"], "works": [{"t": "Симфония № 5, часть 1", "a": "Людвиг ван Бетховен", "y": "1808", "d": "Четыре ноты «та-та-та-там» — самая узнаваемая тема в истории. Это мотив: короткая ячейка, из которой вырастает вся часть. Минор, аллегро, форте.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor,_op._67_-_i._allegro_con_brio.ogg", "lic": "Public domain", "by": "Ludwig van Beethoven", "src": "media/audio/e4d31e8acd.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e6/Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor%2C_op._67_-_i._allegro_con_brio.ogg/Ludwig_van_Beethoven_-_symphony_no._5_in_c_minor%2C_op._67_-_i._allegro_con_brio.ogg.mp3"}}, {"t": "Сюита для виолончели № 1, Прелюдия", "a": "Иоганн Себастьян Бах", "y": "около 1720", "d": "Один инструмент — и целый мир. Послушайте тембр виолончели: тёплый, близкий к человеческому голосу. Мажор.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bach_-_Cello_Suite_no._1_in_G_major,_BWV_1007_-_I._Pr%C3%A9lude.ogg", "lic": "Public domain", "by": "Bach, Johann-Sebastian.", "src": "media/audio/dd1ea7ee35.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9d/Bach_-_Cello_Suite_no._1_in_G_major%2C_BWV_1007_-_I._Pr%C3%A9lude.ogg/Bach_-_Cello_Suite_no._1_in_G_major%2C_BWV_1007_-_I._Pr%C3%A9lude.ogg.mp3"}}, {"t": "Полёт шмеля", "a": "Николай Римский-Корсаков", "y": "1900", "d": "Пример темпа «престо»: стремительные пассажи изображают жужжание. Это музыкальная звукопись.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Rimsky-Korsakov_-_flight_of_the_bumblebee.oga", "lic": "Public domain", "by": "Composition: Nikolai Rimsky-Korsakov. Performer: US Army Band", "src": "media/audio/0eeda89ef7.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c0/Rimsky-Korsakov_-_flight_of_the_bumblebee.oga/Rimsky-Korsakov_-_flight_of_the_bumblebee.oga.mp3"}}], "quiz": [{"q": "Как называется «окраска» звука, по которой мы отличаем скрипку от трубы?", "o": ["Темп", "Тембр", "Ритм", "Лад"], "a": 1, "e": "Тембр — индивидуальный цвет звучания инструмента или голоса."}, {"q": "Что означает «аллегро»?", "o": ["Медленно", "Тихо", "Быстро, весело", "Громко"], "a": 2, "e": "Allegro — «весело», то есть скоро. Медленно — adagio."}, {"q": "Как называется крупное сочинение для оркестра из нескольких частей?", "o": ["Соната", "Симфония", "Романс", "Этюд"], "a": 1, "e": "Симфония — обычно четыре части. Соната — для одного-двух инструментов."}, {"q": "Какой лад чаще звучит светло и радостно?", "o": ["Минор", "Мажор", "Хроматика", "Пентатоника"], "a": 1, "e": "Мажор — светлый, минор — печальный или драматичный."}]}, {"id": "m1", "title": "Средневековье", "period": "V — XIV век", "intro": ["Самая древняя музыка Европы, дошедшая до нас в записи нот, — церковная. Григорианский хорал — одноголосное пение на латыни, без инструментов и без чёткого ритма. Оно плавное, как молитва, и звучит в храме будто из вечности.", "Именно монахи придумали нотную запись: Гвидо д’Ареццо около 1000 года дал нотам названия, от которых пошли наши «до-ре-ми».", "Постепенно к одному голосу добавился второй и третий — так родилась полифония (многоголосие). А за стенами монастырей пели трубадуры и менестрели: о любви, рыцарях и весне."], "traits": ["Григорианский хорал: одноголосие, латынь, без инструментов", "Музыка служит молитве", "Рождение нотной записи (Гвидо д’Ареццо)", "Рождение многоголосия (полифонии)", "Светская музыка трубадуров и менестрелей"], "works": [{"t": "Rorate caeli (григорианский хорал)", "a": "Анонимный церковный распев", "y": "Средние века", "d": "Адвентский распев «Кропите, небеса». Одна мелодическая линия, свободный ритм — так звучали храмы тысячу лет назад.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Rorate_Caeli_~_Gregorian_Chant.ogg", "lic": "CC BY-SA 4.0", "by": "Inritter", "src": "media/audio/f768d50581.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/f8/Rorate_Caeli_~_Gregorian_Chant.ogg/Rorate_Caeli_~_Gregorian_Chant.ogg.mp3"}}, {"t": "O frondens virga", "a": "Хильдегарда Бингенская", "y": "XII век", "d": "Хильдегарда — аббатиса, мистик, учёный и одна из первых композиторов, чьё имя мы знаем.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:O_frondens.ogg", "lic": "CC BY-SA 3.0", "by": "Hildegard of Bingen / user:Makemi", "src": "media/audio/f542345302.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/3/37/O_frondens.ogg/O_frondens.ogg.mp3"}}, {"t": "Sumer is icumen in («Лето пришло»)", "a": "Анонимный английский автор", "y": "около 1260", "d": "Один из древнейших светских канонов: голоса вступают по очереди с одной мелодией. Песня о весне и кукушке.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Sumer_Is_Icumen_In_(13th_century_English_round).ogg", "lic": "CC BY-SA 4.0", "by": "Brandtnight2000", "src": "media/audio/d409d413f1.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/0/06/Sumer_Is_Icumen_In_%2813th_century_English_round%29.ogg/Sumer_Is_Icumen_In_%2813th_century_English_round%29.ogg.mp3"}}], "quiz": [{"q": "Что такое григорианский хорал?", "o": ["Оркестровая симфония", "Одноголосное церковное пение на латыни", "Танец при дворе", "Опера на библейский сюжет"], "a": 1, "e": "Названо в честь папы Григория I."}, {"q": "Кто дал нотам названия, от которых произошли «до-ре-ми»?", "o": ["Бах", "Гвидо д’Ареццо", "Палестрина", "Моцарт"], "a": 1, "e": "Около 1000 года, по первым слогам строк гимна св. Иоанну."}, {"q": "Как называется многоголосие, где каждый голос ведёт свою мелодию?", "o": ["Монодия", "Полифония", "Гомофония", "Унисон"], "a": 1, "e": "Полифония — «много звуков»."}]}, {"id": "m2", "title": "Возрождение", "period": "XV — XVI век", "intro": ["Музыка Ренессанса — это прежде всего хоровая полифония удивительной чистоты. Несколько голосов сплетаются в ровную, прозрачную ткань, и ни один не главнее другого.", "Вершина церковной музыки — Джованни Пьерлуиджи да Палестрина. Легенда гласит, что его месса «спасла» многоголосие, когда церковь хотела его запретить: слова в ней звучат ясно.", "Светская музыка тоже расцвела: итальянские мадригалы о любви, лютневые песни, танцы. В конце эпохи Монтеверди сделает шаг к барокко — и создаст одну из первых опер."], "traits": ["Хоровая полифония a cappella (без инструментов)", "Равноправие голосов, мягкая гармония", "Месса и мотет — церковные жанры", "Мадригал — светская песня о любви", "Лютня — главный домашний инструмент"], "works": [{"t": "Vestiva i colli", "a": "Джованни Палестрина", "y": "1566", "d": "Светский мадригал церковного мастера. Голоса текут спокойно, без резких скачков — фирменная ясность Палестрины.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg", "lic": "CC BY 4.0", "by": "Palestrina", "src": "media/audio/4ca1e6fd73.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/de/Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg/Palestrina_-_Vestiva_i_colli_-_Prima_parte.ogg.mp3"}}, {"t": "Agnus Dei", "a": "Джованни Палестрина", "y": "XVI век", "d": "Часть мессы. Прислушайтесь: голоса вступают друг за другом, как волны.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg", "lic": "Public domain", "by": "Palestrina", "src": "media/audio/57adbf9b3d.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c5/Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg/Palestrina_Agnus_Dei_from_Missa_in_Festis_Apostolorum.ogg.mp3"}}, {"t": "Greensleeves («Зелёные рукава»)", "a": "Английская народная песня", "y": "XVI век", "d": "Самая знаменитая мелодия елизаветинской Англии. Легенда приписывает её Генриху VIII.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Greensleeves_Correct_Melody.ogg", "lic": "Public domain", "by": "Traditional English folk song", "src": "media/audio/3ca8312013.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/Greensleeves_Correct_Melody.ogg/Greensleeves_Correct_Melody.ogg.mp3"}}, {"t": "Cruda Amarilli", "a": "Клаудио Монтеверди", "y": "1605", "d": "Поздний мадригал с острыми диссонансами — Монтеверди уже на пороге барокко.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Monteverdi_-_cruda_amarilli.ogg", "lic": "CC BY-SA 2.0", "by": "", "src": "media/audio/0b27d76300.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Monteverdi_-_cruda_amarilli.ogg/Monteverdi_-_cruda_amarilli.ogg.mp3"}}], "quiz": [{"q": "Что значит «a cappella»?", "o": ["С оркестром", "Пение без инструментального сопровождения", "Очень быстро", "Для органа"], "a": 1, "e": "Буквально «как в капелле» — только голоса."}, {"q": "Кто — главный мастер церковной полифонии Возрождения?", "o": ["Вивальди", "Палестрина", "Гайдн", "Шопен"], "a": 1, "e": "Палестрина, Рим, XVI век."}, {"q": "Мадригал — это…", "o": ["Церковная месса", "Светская многоголосная песня", "Танец", "Инструмент"], "a": 1, "e": "Мадригалы пели о любви и природе."}]}, {"id": "m3", "title": "Барокко", "period": "1600 — 1750", "intro": ["Эпоха барокко подарила миру оперу, концерт, сонату, ораторию и оркестр. Музыка стала эффектной, контрастной, полной украшений. Её фундамент — басо континуо: непрерывный бас, над которым строятся аккорды (часто играл клавесин).", "Три великих имени: Вивальди (Венеция) — мастер концерта, его «Времена года» знает каждый. Бах (Германия) — гений полифонии, фуги и органа. Гендель (Германия, Англия) — короли опер и ораторий, «Аллилуйя» из «Мессии».", "Узнать барокко на слух: постоянный ровный пульс, клавесин или орган, моторное движение, украшения-трели и игра контрастов громко/тихо, соло/все."], "traits": ["Рождение оперы (Монтеверди, 1607)", "Басо континуо, звучание клавесина и органа", "Концерт: солист против оркестра, контраст", "Фуга — вершина полифонии", "Бах, Вивальди, Гендель"], "works": [{"t": "Времена года: «Весна», 1 часть", "a": "Антонио Вивальди", "y": "1725", "d": "Программная музыка: скрипки щебечут как птицы, журчат ручьи, гремит гроза. К каждому концерту Вивальди написал сонет.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga", "lic": "CC BY-SA 4.0", "by": "Antonio Vivaldi", "src": "media/audio/1608612918.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/ff/Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga/Vivaldi_-_Four_Seasons_1_Spring_mvt_1_Allegro_-_John_Harrison_violin.oga.mp3"}}, {"t": "Токката и фуга ре минор", "a": "Иоганн Себастьян Бах", "y": "около 1704", "d": "Органная пьеса в оркестровой версии Стоковского (запись 1927 года). Грозное начало знакомо всем по кино.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:PDP-CH_-_Philadelphia_Orchestra,_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor,_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac", "lic": "Public domain", "by": "", "src": "media/audio/9b14423118.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/PDP-CH_-_Philadelphia_Orchestra%2C_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor%2C_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac/PDP-CH_-_Philadelphia_Orchestra%2C_Leopold_Stokowski_-_Toccata_and_Fugue_in_D_minor%2C_BWV_565_-_Bach_-_Hmv-d1428-5-0761.flac.mp3"}}, {"t": "Бранденбургский концерт № 3", "a": "Иоганн Себастьян Бах", "y": "1721", "d": "Ровный «моторный» пульс и переклички групп струнных — образец барочного концерта.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg", "lic": "CC BY-SA 2.0", "by": "Johann Sebastian Bach", "src": "media/audio/23a0896ac5.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg/Bach_-_Brandenburg_Concerto_No._3_-_1._Allegro.ogg.mp3"}}, {"t": "«Аллилуйя» из оратории «Мессия»", "a": "Георг Фридрих Гендель", "y": "1741", "d": "По традиции на этом хоре публика встаёт — говорят, так впервые сделал король Георг II.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Handel_-_messiah_-_44_hallelujah.ogg", "lic": "CC BY-SA 2.0", "by": "Composer: Georg Friedrich Händel; Performed by: MIT Concert Choir; Directed by W", "src": "media/audio/17b9907669.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/ce/Handel_-_messiah_-_44_hallelujah.ogg/Handel_-_messiah_-_44_hallelujah.ogg.mp3"}}, {"t": "Ария (Air)", "a": "Иоганн Себастьян Бах", "y": "около 1730", "d": "Из оркестровой сюиты № 3. Мелодия парит над шагающим басом — тем самым басо континуо.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Air_(Bach).ogg", "lic": "Public domain", "by": "", "src": "media/audio/2bcfaba4de.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/1/1e/Air_%28Bach%29.ogg/Air_%28Bach%29.ogg.mp3"}}], "quiz": [{"q": "Какой жанр родился в эпоху барокко?", "o": ["Симфоническая поэма", "Опера", "Джаз", "Мадригал"], "a": 1, "e": "Первая сохранившаяся великая опера — «Орфей» Монтеверди, 1607."}, {"q": "Кто написал «Времена года»?", "o": ["Бах", "Гендель", "Вивальди", "Моцарт"], "a": 2, "e": "Антонио Вивальди, «рыжий священник» из Венеции."}, {"q": "Какой инструмент — «голос» барокко, на нём часто играли басо континуо?", "o": ["Рояль", "Клавесин", "Саксофон", "Арфа"], "a": 1, "e": "Фортепиано появится позже, а в барокко звучали клавесин и орган."}, {"q": "Фуга — это…", "o": ["Танец", "Полифоническая пьеса, где тема проходит по очереди во всех голосах", "Песня без слов", "Оркестровое вступление к опере"], "a": 1, "e": "Бах — величайший мастер фуги."}]}, {"id": "m4", "title": "Венская классика", "period": "1750 — 1820", "intro": ["Классицизм в музыке — это ясность, баланс и красота формы. Вместо сложной полифонии барокко — понятная мелодия с аккомпанементом. Сложились главные формы: симфония, соната, струнный квартет, классический концерт.", "Центр эпохи — Вена, и три её героя: Гайдн («отец симфонии», написал их больше ста), Моцарт (гений, писавший с детства во всех жанрах) и Бетховен (превратил музыку в драму и борьбу — мост к романтизму).", "На смену клавесину пришло фортепиано: оно умеет играть и тихо, и громко (отсюда название). Оркестр стал больше и разнообразнее."], "traits": ["Ясная мелодия + аккомпанемент", "Сонатная форма: экспозиция, разработка, реприза", "Симфония из четырёх частей", "Фортепиано вытесняет клавесин", "Гайдн, Моцарт, Бетховен"], "works": [{"t": "Маленькая ночная серенада, 1 часть", "a": "Вольфганг Амадей Моцарт", "y": "1787", "d": "Эталон классической ясности: изящные фразы, симметрия, лёгкость.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg", "lic": "CC BY-SA 2.0", "by": "Wolfgang Amadeus Mozart", "src": "media/audio/1d88e5c0b6.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/24/Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg/Mozart_-_Eine_kleine_Nachtmusik_-_1._Allegro.ogg.mp3"}}, {"t": "Турецкий марш (Рондо в турецком стиле)", "a": "Вольфганг Амадей Моцарт", "y": "1783", "d": "Финал фортепианной сонаты. В Вене тогда была мода на «янычарскую» музыку.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_(Turkish_March).ogg", "lic": "CC BY-SA 3.0 de", "by": "Bernd Krueger", "src": "media/audio/512a2dd145.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bf/Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_%28Turkish_March%29.ogg/Mozart_-_Piano_Sonata_No._11_in_A_major_-_III._Allegro_%28Turkish_March%29.ogg.mp3"}}, {"t": "Симфония № 94 «Сюрприз», 2 часть", "a": "Йозеф Гайдн", "y": "1791", "d": "Тихая простая тема — и вдруг удар всего оркестра. Говорят, Гайдн хотел разбудить задремавшую публику.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Haydn;_Symphony_No._94_%22Surprise%22,_2._Andante.ogg", "lic": "Public domain", "by": "Boston Symphony Orchestra\n\nSerge Koussevitzky", "src": "media/audio/0ce9b31532.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/42/Haydn%3B_Symphony_No._94_%22Surprise%22%2C_2._Andante.ogg/Haydn%3B_Symphony_No._94_%22Surprise%22%2C_2._Andante.ogg.mp3"}}, {"t": "Реквием: Lacrimosa", "a": "Вольфганг Амадей Моцарт", "y": "1791", "d": "Последнее, над чем работал Моцарт: он умер, успев написать лишь восемь тактов «Лакримозы».", "audio": {"page": "https://commons.wikimedia.org/wiki/File:W._A._Mozart_-_Requiem_-_8._Lacrimosa_(Herbert_von_Karajan,_Wiener_Philharmoniker,_Wiener_Singverein,_1960).ogg", "lic": "Public domain", "by": "Wolfgang Amadeus Mozart", "src": "media/audio/a15c6d3970.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/0/04/W._A._Mozart_-_Requiem_-_8._Lacrimosa_%28Herbert_von_Karajan%2C_Wiener_Philharmoniker%2C_Wiener_Singverein%2C_1960%29.ogg/W._A._Mozart_-_Requiem_-_8._Lacrimosa_%28Herbert_von_Karajan%2C_Wiener_Philharmoniker%2C_Wiener_Singverein%2C_1960%29.ogg.mp3"}}, {"t": "«Лунная» соната, 3 часть", "a": "Людвиг ван Бетховен", "y": "1801", "d": "После знаменитой тихой первой части — буря. У Бетховена классическая форма наполняется страстью.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Beethoven_Moonlight_3rd_movement.ogg", "lic": "CC BY-SA 2.0 de", "by": "Ludwig van Beethoven", "src": "media/audio/01c1914487.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/d4/Beethoven_Moonlight_3rd_movement.ogg/Beethoven_Moonlight_3rd_movement.ogg.mp3"}}], "quiz": [{"q": "Кого называют «отцом симфонии»?", "o": ["Моцарта", "Бетховена", "Гайдна", "Баха"], "a": 2, "e": "Гайдн написал 104 симфонии и закрепил её форму."}, {"q": "Какой инструмент пришёл на смену клавесину в эпоху классицизма?", "o": ["Орган", "Фортепиано", "Гитара", "Арфа"], "a": 1, "e": "Pianoforte — «тихо-громко»: удар молоточка зависит от силы нажатия."}, {"q": "Какой город — столица венской классики?", "o": ["Париж", "Вена", "Лейпциг", "Рим"], "a": 1, "e": "Все трое — Гайдн, Моцарт, Бетховен — работали в Вене."}, {"q": "Чьё творчество стало мостом от классицизма к романтизму?", "o": ["Гайдна", "Бетховена", "Вивальди", "Палестрины"], "a": 1, "e": "Бетховен — классик по форме, романтик по силе чувства."}]}, {"id": "m5", "title": "Романтизм", "period": "1820 — 1900", "intro": ["Романтики сделали музыку языком чувств. Главное — выражение личности, любви, тоски, природы, мечты. Мелодии стали длинными и певучими, гармония — смелой и красочной, оркестр — огромным.", "Расцвели миниатюры: песня (Шуберт написал их более 600), фортепианные ноктюрны и вальсы Шопена. Появился культ виртуоза — Лист и Паганини сводили публику с ума. Композиторы обращаются к фольклору своих стран: Григ в Норвегии, Дворжак в Чехии.", "В опере два гиганта: Верди в Италии и Вагнер в Германии. Вагнер мечтал о «синтезе искусств» и придумал лейтмотив — музыкальную тему-«визитку» героя."], "traits": ["Музыка как исповедь души", "Миниатюры: песня, ноктюрн, вальс, прелюдия", "Виртуозы: Лист, Паганини", "Национальные школы и фольклор", "Опера: Верди и Вагнер, лейтмотив"], "works": [{"t": "Ноктюрн ми-бемоль мажор, соч. 9 № 2", "a": "Фредерик Шопен", "y": "1832", "d": "Ноктюрн — «ночная» пьеса. Мелодия поёт как голос оперной певицы, а левая рука мягко покачивает аккомпанемент.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Chopin_Nocturne_Op_9_No_2.ogg", "lic": "CC BY-SA 3.0", "by": "Beeswaxcandle at English Wikisource and Londonjackbooks at English Wikisource", "src": "media/audio/bd368afbec.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fd/Chopin_Nocturne_Op_9_No_2.ogg/Chopin_Nocturne_Op_9_No_2.ogg.mp3"}}, {"t": "Ave Maria (Третья песня Эллен)", "a": "Франц Шуберт", "y": "1825", "d": "Песня на стихи Вальтера Скотта стала одной из самых любимых мелодий мира.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Franz_Schubert_-_Ellens_dritter_Gesang.oga", "lic": "CC BY 3.0", "by": "Composed by Franz Schubert", "src": "media/audio/564b062750.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/6/6f/Franz_Schubert_-_Ellens_dritter_Gesang.oga/Franz_Schubert_-_Ellens_dritter_Gesang.oga.mp3"}}, {"t": "Венгерская рапсодия № 2", "a": "Ференц Лист", "y": "1847", "d": "Медленное вступление и огненный пляс. Лист — величайший пианист-виртуоз своего века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg", "lic": "CC BY-SA 2.0", "by": "Franz Liszt", "src": "media/audio/5ef5468046.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg/Franz_Liszt_-_Second_Hungarian_Rhapsody.ogg.mp3"}}, {"t": "Полёт валькирий", "a": "Рихард Вагнер", "y": "1856", "d": "Из оперы «Валькирия». Девы-воительницы несутся над полем битвы — мощь вагнеровского оркестра.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Richard_Wagner_-_Ride_of_the_Valkyries.ogg", "lic": "Public domain", "by": "Richard Wagner (1813–1883)", "src": "media/audio/e260e0ce0d.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/29/Richard_Wagner_-_Ride_of_the_Valkyries.ogg/Richard_Wagner_-_Ride_of_the_Valkyries.ogg.mp3"}}, {"t": "В пещере горного короля", "a": "Эдвард Григ", "y": "1875", "d": "Из музыки к «Пер Гюнту». Одна тема повторяется всё быстрее и громче — классический пример крещендо.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg", "lic": "Public domain", "by": "Grieg, Edvard; Musopen Symphony Orchestra", "src": "media/audio/84d933de2a.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bb/Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg/Musopen_-_In_the_Hall_Of_The_Mountain_King.ogg.mp3"}}, {"t": "La donna è mobile («Сердце красавицы»)", "a": "Джузеппе Верди", "y": "1851", "d": "Песенка Герцога из оперы «Риголетто». Наутро после премьеры её насвистывала вся Венеция.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:La_Donna_E_Mobile_Rigoletto.ogg", "lic": "Public domain", "by": "Giuseppe Verdi &amp; Francesco Maria Piave", "src": "media/audio/4a5afe39a8.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/5/5a/La_Donna_E_Mobile_Rigoletto.ogg/La_Donna_E_Mobile_Rigoletto.ogg.mp3"}}], "quiz": [{"q": "Что главное в музыке романтизма?", "o": ["Строгая форма", "Выражение чувств и личности", "Церковный канон", "Танцевальный ритм"], "a": 1, "e": "Романтики видели в музыке язык души."}, {"q": "Что такое лейтмотив?", "o": ["Финал оперы", "Повторяющаяся тема-характеристика героя или идеи", "Вид танца", "Музыкальный инструмент"], "a": 1, "e": "Вагнер построил на лейтмотивах свои огромные оперы."}, {"q": "Кто написал знаменитые ноктюрны и вальсы для фортепиано?", "o": ["Вагнер", "Шопен", "Верди", "Гайдн"], "a": 1, "e": "Фредерик Шопен — «поэт фортепиано»."}, {"q": "Как называется постепенное усиление громкости?", "o": ["Диминуэндо", "Крещендо", "Стаккато", "Легато"], "a": 1, "e": "Crescendo — «вырастая». Обратное — diminuendo."}]}, {"id": "m6", "title": "Русская классическая музыка", "period": "XIX — начало XX века", "intro": ["Русская композиторская школа родилась с Михаилом Глинкой — «отцом русской музыки». Его оперы «Жизнь за царя» и «Руслан и Людмила» соединили европейское мастерство с русской песней.", "Дальше — «Могучая кучка»: Балакирев, Мусоргский, Бородин, Римский-Корсаков, Кюи. Их цель — национальная музыка: сказки, история, народные интонации. А Пётр Чайковский стал самым любимым русским композитором в мире: балеты «Лебединое озеро», «Щелкунчик», «Спящая красавица», шесть симфоний, оперы.", "На рубеже веков — Рахманинов с его колокольными аккордами и огромными мелодиями, Скрябин с мечтой о цвето-музыке и юный Стравинский, взорвавший Париж «Весной священной»."], "traits": ["Глинка — основоположник русской классической музыки", "«Могучая кучка»: национальные сюжеты и фольклор", "Чайковский: лирика, балет, симфония", "Колокольность, протяжная песенность", "Рахманинов, Скрябин, Стравинский"], "works": [{"t": "Лебединое озеро (фрагмент из 2 акта)", "a": "Пётр Чайковский", "y": "1876", "d": "Тема лебедей — гобой поверх дрожащих струнных. Один из самых узнаваемых мотивов в истории балета.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg", "lic": "Public domain", "by": "Ballet Francaise Symphony Orchestra", "src": "media/audio/ca22213b07.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/2/2b/Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg/Peter_Ilyich_Tchaikovsky-_Swan_Lake-_Extract_from_Act_2.ogg.mp3"}}, {"t": "Танец Феи Драже («Щелкунчик»)", "a": "Пётр Чайковский", "y": "1892", "d": "Чайковский первым в России использовал челесту — инструмент со звуком «хрустальных капель».", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg", "lic": "CC BY 3.0", "by": "Pyotr Ilyich Tchaikovsky", "src": "media/audio/93dc198ebb.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/9/9d/Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg/Tchaikovsky_-_Dance_of_the_Sugar_Plum_Fairy_-_The_Nutcracker.ogg.mp3"}}, {"t": "Картинки с выставки: Прогулка", "a": "Модест Мусоргский", "y": "1874", "d": "Цикл о прогулке по выставке друга-художника Гартмана. «Прогулка» — сам композитор, переходящий от картины к картине.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg", "lic": "Public domain", "by": "Modest Petrovich Mussorgsky", "src": "media/audio/ec87b265b5.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/d/df/Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg/Modest_Mussorgsky_-_pictures_at_an_exhibition_-_promenade_-_moderato_comodo_e_con_delicatezza.ogg.mp3"}}, {"t": "Полёт шмеля", "a": "Николай Римский-Корсаков", "y": "1900", "d": "Из оперы «Сказка о царе Салтане» по Пушкину: князь Гвидон, обернувшись шмелём, летит к отцу.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg", "lic": "CC BY-SA 2.0", "by": "Pianists: Neal and Nancy O'Doan", "src": "media/audio/7d45ebcdf2.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ad/Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg/Nikolai_Rimsky-Korsakov_-_Bumblebee.ogg.mp3"}}, {"t": "Прелюдия до-диез минор", "a": "Сергей Рахманинов (играет автор)", "y": "1892", "d": "Редкая историческая запись: играет сам Рахманинов. Три тяжёлых «колокольных» удара открывают пьесу.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor,_Op._3.ogg", "lic": "Public domain", "by": "Sergei Rachmaninoff", "src": "media/audio/0afd6fd1cc.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b9/Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor%2C_Op._3.ogg/Sergei_Rachmaninoff_performs_Rachmaninoff%27s_Prelude_in_C_sharp_minor%2C_Op._3.ogg.mp3"}}, {"t": "Концерт для фортепиано № 1, 1 часть", "a": "Пётр Чайковский", "y": "1875", "d": "Мощные аккорды рояля на фоне величественной темы оркестра — одно из самых ярких вступлений в музыке.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Tchaikovsky,_Concerto_No.1_in_B-flat_minor_Op.23,_I._Allegro.ogg", "lic": "CC0", "by": "Pyotr Ilyich Tchaikovsky", "src": "media/audio/2b98fc1938.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/48/Tchaikovsky%2C_Concerto_No.1_in_B-flat_minor_Op.23%2C_I._Allegro.ogg/Tchaikovsky%2C_Concerto_No.1_in_B-flat_minor_Op.23%2C_I._Allegro.ogg.mp3"}}], "quiz": [{"q": "Кого называют «отцом русской музыки»?", "o": ["Чайковского", "Глинку", "Мусоргского", "Рахманинова"], "a": 1, "e": "Михаил Глинка, оперы «Жизнь за царя» (1836) и «Руслан и Людмила» (1842)."}, {"q": "Кто НЕ входил в «Могучую кучку»?", "o": ["Мусоргский", "Бородин", "Чайковский", "Римский-Корсаков"], "a": 2, "e": "Чайковский дружил с «кучкистами», но шёл своим путём."}, {"q": "Из какой оперы «Полёт шмеля»?", "o": ["«Садко»", "«Сказка о царе Салтане»", "«Снегурочка»", "«Золотой петушок»"], "a": 1, "e": "Римский-Корсаков, опера по сказке Пушкина, 1900."}, {"q": "Какой балет НЕ принадлежит Чайковскому?", "o": ["«Лебединое озеро»", "«Щелкунчик»", "«Спящая красавица»", "«Жар-птица»"], "a": 3, "e": "«Жар-птица» — балет Стравинского (1910)."}]}, {"id": "m7", "title": "Импрессионизм и новая музыка", "period": "1890 — 1930", "intro": ["Как художники-импрессионисты ловили свет, так Клод Дебюсси ловил в музыке настроения, отблески, туман и воду. Звуки размыты, аккорды «плывут», форма свободна. Рядом — Морис Равель, мастер изысканного оркестра, и чудак Эрик Сати с его простыми и странными пьесами.", "XX век разрушает правила: Стравинский играет с острым ритмом, Шёнберг отказывается от тональности. Музыка становится разнообразной как никогда.", "А в США в это время рождается совершенно новый мир — регтайм, блюз и джаз. Им посвящена следующая глава."], "traits": ["Импрессионизм: краски, настроение, размытость", "Дебюсси, Равель, Сати", "Необычные лады и «плывущие» аккорды", "XX век: эксперименты с ритмом и тональностью", "Стравинский, Шёнберг, Прокофьев, Шостакович"], "works": [{"t": "Лунный свет (Clair de lune)", "a": "Клод Дебюсси", "y": "1905", "d": "Из «Бергамасской сюиты». Тихая, мерцающая музыка — как лунный свет на воде.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Clair_de_lune_(Claude_Debussy)_Suite_bergamasque.ogg", "lic": "Public domain", "by": "Claude Debussy", "src": "media/audio/bbacfbab82.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/b/be/Clair_de_lune_%28Claude_Debussy%29_Suite_bergamasque.ogg/Clair_de_lune_%28Claude_Debussy%29_Suite_bergamasque.ogg.mp3"}}, {"t": "Гимнопедия № 1", "a": "Эрик Сати", "y": "1888", "d": "Медленная, прозрачная, почти неподвижная музыка. Сати предвосхитил минимализм и «фоновую» музыку XX века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac", "lic": "Public domain", "by": "Mlaucke", "src": "media/audio/92a127ed15.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/a6/Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac/Satie_Gymnopedie_No_1_performed_by_Michael_Laucke.flac.mp3"}}, {"t": "Болеро", "a": "Морис Равель", "y": "1928", "d": "Одна мелодия и неизменный ритм барабана 15 минут — но каждый раз в новом тембре и всё громче. Урок оркестровки.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Bolero-Maurice_Ravel-1930.ogg", "lic": "Public domain", "by": "Maurice Ravel", "src": "media/audio/0cd80089af.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c3/Bolero-Maurice_Ravel-1930.ogg/Bolero-Maurice_Ravel-1930.ogg.mp3"}}, {"t": "Жар-птица: Поганый пляс Кащея", "a": "Игорь Стравинский", "y": "1910", "d": "Балет для «Русских сезонов» Дягилева. Резкие акценты и дикий ритм — новая музыка XX века.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg", "lic": "Public domain", "by": "", "src": "media/audio/36bce0b1a3.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/a/ab/Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg/Infernal_Dance_from_The_Firebird_by_Stravinsky.ogg.mp3"}}], "quiz": [{"q": "Кто главный композитор-импрессионист?", "o": ["Вагнер", "Дебюсси", "Бетховен", "Гендель"], "a": 1, "e": "Клод Дебюсси, хотя сам он не любил этот ярлык."}, {"q": "В чём необычность «Болеро» Равеля?", "o": ["Оно без мелодии", "Одна тема и ритм повторяются, меняются тембр и громкость", "Его играют на одном рояле", "Оно длится 2 минуты"], "a": 1, "e": "Огромное крещендо на одной теме."}, {"q": "Для чьей антрепризы Стравинский написал «Жар-птицу»?", "o": ["Сергея Дягилева", "Петра Чайковского", "Мариуса Петипа", "Анны Павловой"], "a": 0, "e": "«Русские сезоны» Дягилева в Париже, 1910."}]}, {"id": "m8", "title": "Регтайм, блюз и джаз", "period": "1890-е — 1920-е", "intro": ["В конце XIX века на юге США из встречи африканских ритмов, церковных песнопений и европейской гармонии родились новые жанры. Регтайм — фортепианная музыка с «рваным» ритмом (синкопами). Король регтайма — Скотт Джоплин.", "Блюз — грустные песни с особыми «блюзовыми» нотами и формой из 12 тактов. Из регтайма и блюза в Новом Орлеане вырос джаз: импровизация, свинг, медные духовые.", "Первая джазовая пластинка вышла в 1917 году. А в 1924-м Джордж Гершвин соединил джаз с симфонией в «Рапсодии в стиле блюз». Отсюда пойдёт вся популярная музыка XX века — от свинга до рока."], "traits": ["Синкопа — смещённый, «рваный» акцент", "Регтайм: Скотт Джоплин", "Блюз: 12 тактов, блюзовые ноты", "Джаз: импровизация и свинг", "Новый Орлеан — колыбель джаза"], "works": [{"t": "Maple Leaf Rag («Регтайм кленового листа»)", "a": "Скотт Джоплин (играет автор, 1916)", "y": "1899", "d": "Самый известный регтайм. Левая рука шагает ровно, правая — синкопирует. Запись с перфоленты механического пианино, которую набил сам Джоплин.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg", "lic": "Public domain", "by": "Scott Joplin", "src": "media/audio/8857d3a7b4.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e9/Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg/Maple_Leaf_Rag_-_played_by_Scott_Joplin_1916_sample.ogg.mp3"}}, {"t": "Livery Stable Blues", "a": "Original Dixieland Jass Band", "y": "1917", "d": "Первая в истории изданная джазовая пластинка. Кларнет, корнет и тромбон подражают животным на конюшне.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:ODJB_Livery_Stable_Blues_1917.ogg", "lic": "Public domain", "by": "Original Dixieland Jass Band (performer); Ray Lopez, Alcide Nunez (composers)", "src": "media/audio/9ef34d8c24.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/transcoded/4/42/ODJB_Livery_Stable_Blues_1917.ogg/ODJB_Livery_Stable_Blues_1917.ogg.mp3"}}, {"t": "Рапсодия в стиле блюз", "a": "Джордж Гершвин (за роялем автор)", "y": "1924", "d": "Первая запись 1924 года. Знаменитое глиссандо кларнета в начале придумал музыкант оркестра на репетиции.", "audio": {"page": "https://commons.wikimedia.org/wiki/File:1st_recording_of_Rhapsody_In_Blue_-_Paul_Whiteman_Orch._and_George_Gershwin_piano_(1924_version).ogg", "lic": "Public domain", "by": "George Gershwin and Paul Whiteman Orchestra", "src": "media/audio/3068c75e26.mp3", "remote": "https://upload.wikimedia.org/wikipedia/commons/1/16/1st_recording_of_Rhapsody_In_Blue_-_Paul_Whiteman_Orch._and_George_Gershwin_piano_%281924_version%29.ogg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original"}}], "quiz": [{"q": "Что такое синкопа?", "o": ["Медленный темп", "Смещение акцента на слабую долю", "Вид барабана", "Пение хором"], "a": 1, "e": "Синкопы делают ритм «рваным» и упругим — основа регтайма и джаза."}, {"q": "Кто «король регтайма»?", "o": ["Луи Армстронг", "Скотт Джоплин", "Джордж Гершвин", "Дюк Эллингтон"], "a": 1, "e": "Scott Joplin, «Maple Leaf Rag», 1899."}, {"q": "Какой город считают колыбелью джаза?", "o": ["Нью-Йорк", "Чикаго", "Новый Орлеан", "Лос-Анджелес"], "a": 2, "e": "New Orleans, конец XIX — начало XX века."}, {"q": "Что главное в джазе?", "o": ["Строгое следование нотам", "Импровизация и свинг", "Пение на латыни", "Отсутствие ритма"], "a": 1, "e": "Джазмен сочиняет прямо во время игры."}]}], "lit": [{"id": "l0", "title": "Как читать литературу", "period": "Азбука", "intro": ["Всю художественную литературу делят на три рода. Эпос рассказывает историю: роман, повесть, рассказ, поэма, басня. Лирика выражает чувства и мысли: стихотворение, элегия, ода. Драма разыгрывается на сцене: трагедия, комедия, драма.", "Стихи держатся на ритме. В русской поэзии главные размеры — ямб (та-ТА: «Мой дЯдя сАмых чЕстных прАвил») и хорей (ТА-та: «БУря мглОю нЕбо крОет»). Есть и трёхсложные: дактиль, амфибрахий, анапест.", "Писатели работают с тропами — образными приёмами. Эпитет — яркое определение («чудное мгновенье»). Метафора — скрытое сравнение («горит восток зарёю новой»). Олицетворение — неживое ведёт себя как живое. Узнайте эти приёмы, и тексты заиграют по-новому.", "Почти всю классику можно читать прямо здесь: тексты загружаются из Викитеки — свободной библиотеки, где лежат произведения, перешедшие в общественное достояние."], "traits": ["Три рода: эпос, лирика, драма", "Ямб (та-ТА) и хорей (ТА-та)", "Эпитет, метафора, сравнение, олицетворение", "Сюжет, композиция, герой, конфликт", "Классика — то, что перечитывают веками"], "works": [{"t": "Зимнее утро", "a": "Александр Пушкин", "y": "1829", "ws": "Зимнее утро (Пушкин)", "q": "Мороз и солнце; день чудесный!\nЕще ты дремлешь, друг прелестный —\nПора, красавица, проснись…", "d": "Лирика. Четырёхстопный ямб. Найдите эпитеты: «день чудесный», «друг прелестный».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ворона и Лисица", "a": "Иван Крылов", "y": "1807", "ws": "Ворона и Лисица (Крылов)", "q": "Уж сколько раз твердили миру,\nЧто лесть гнусна, вредна; но только всё не впрок,\nИ в сердце льстец всегда отыщет уголок.", "d": "Басня — эпос в миниатюре: короткий рассказ с моралью. Крылов сделал её народным жанром.", "img": {"page": "https://commons.wikimedia.org/wiki/File:0521Fc._Portrait_of_I.A._Krylov,_1839_(Karl_Bryullov).jpg", "lic": "Public domain", "by": "Karl Bryullov", "src": "media/img/55eee36680-360.webp", "w": 1000, "h": 1208, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/0521Fc._Portrait_of_I.A._Krylov%2C_1839_%28Karl_Bryullov%29.jpg/1280px-0521Fc._Portrait_of_I.A._Krylov%2C_1839_%28Karl_Bryullov%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "К *** («Я помню чудное мгновенье…»)", "a": "Александр Пушкин", "y": "1825", "ws": "К *** («Я помню чудное мгновенье...») (Пушкин)", "q": "Я помню чудное мгновенье:\nПередо мной явилась ты,\nКак мимолетное виденье,\nКак гений чистой красоты.", "d": "Любовная лирика, посвящённая Анне Керн. Обратите внимание на сравнение «как мимолетное виденье».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "К какому роду литературы относится трагедия?", "o": ["Эпос", "Лирика", "Драма", "Басня"], "a": 2, "e": "Трагедия и комедия — жанры драмы, они пишутся для сцены."}, {"q": "Какой стихотворный размер: та-ТА, та-ТА?", "o": ["Хорей", "Ямб", "Дактиль", "Анапест"], "a": 1, "e": "Ямб — ударение на второй слог стопы. «Мой дЯдя сАмых чЕстных прАвил»."}, {"q": "«Чудное мгновенье» — это пример…", "o": ["Метафоры", "Эпитета", "Рифмы", "Гиперболы"], "a": 1, "e": "Эпитет — художественное определение."}, {"q": "Басня — это…", "o": ["Лирическое стихотворение", "Короткий поучительный рассказ с моралью", "Пьеса", "Роман в письмах"], "a": 1, "e": "Басни писали Эзоп, Лафонтен, Крылов."}]}, {"id": "l1", "title": "Античность", "period": "VIII век до н. э. — V век н. э.", "intro": ["Европейская литература начинается с Гомера. «Илиада» рассказывает о Троянской войне и гневе Ахиллеса, «Одиссея» — о десятилетнем возвращении Одиссея домой. Эти поэмы веками учили греков, что такое честь, хитрость, верность.", "Афины V века до н. э. подарили миру театр. Трагики Эсхил, Софокл и Еврипид писали о судьбе, вине и выборе, комедиограф Аристофан смеялся над политиками.", "Рим продолжил эстафету: Вергилий написал «Энеиду», Овидий — «Метаморфозы», сборник мифов о превращениях, из которого потом черпали художники всех веков."], "traits": ["Эпос: Гомер, «Илиада» и «Одиссея»", "Театр: трагедия и комедия", "Мифы как основа сюжетов", "Рок, судьба, катарсис", "Рим: Вергилий, Овидий, Гораций"], "works": [{"t": "Илиада", "a": "Гомер (перевод Н. Гнедича)", "y": "VIII век до н. э.", "ws": "Илиада (Гомер; Гнедич)", "q": "Гнев, богиня, воспой Ахиллеса, Пелеева сына,\nГрозный, который ахеянам тысячи бедствий соделал…", "d": "Пятьдесят дней десятого года Троянской войны. Перевод Гнедича писан гекзаметром — размером Гомера.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Homer_British_Museum.jpg", "lic": "Public domain", "by": "", "src": "media/img/fbefb57a99-360.webp", "w": 1000, "h": 1260, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Homer_British_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Одиссея", "a": "Гомер (перевод В. Жуковского)", "y": "VIII век до н. э.", "ws": "Одиссея (Гомер; Жуковский)", "q": "Муза, скажи мне о том многоопытном муже, который,\nСтранствуя долго со дня, как святой Илион им разрушен…", "d": "Циклоп, сирены, волшебница Цирцея — и верная Пенелопа, ждущая двадцать лет. Первый в мире «роман-путешествие».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Homer_British_Museum.jpg", "lic": "Public domain", "by": "", "src": "media/img/fbefb57a99-360.webp", "w": 1000, "h": 1260, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Homer_British_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Царь Эдип", "a": "Софокл", "y": "около 429 г. до н. э.", "ws": "Царь Эдип (Софокл; Зелинский)", "q": "", "d": "Эдип расследует убийство царя — и выясняет, что убийца он сам. Аристотель считал эту трагедию образцовой.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sophocles_pushkin.jpg", "lic": "CC BY-SA 3.0", "by": "user:shakko", "src": "media/img/ffce1e9764-360.webp", "w": 1000, "h": 1358, "remote": "https://upload.wikimedia.org/wikipedia/commons/1/19/Sophocles_pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Метаморфозы", "a": "Овидий", "y": "8 г. н. э.", "ws": "Метаморфозы (Овидий)", "q": "", "d": "Около 250 мифов: Нарцисс, Эхо, Дедал и Икар, Орфей и Эвридика. Главная «шпаргалка» художников Возрождения и барокко."}], "quiz": [{"q": "О чём рассказывает «Илиада»?", "o": ["О странствиях Одиссея", "О Троянской войне и гневе Ахиллеса", "О сотворении мира", "О Риме"], "a": 1, "e": "Илион — другое название Трои."}, {"q": "Где родился европейский театр?", "o": ["В Риме", "В Афинах", "В Египте", "В Византии"], "a": 1, "e": "Афины, V век до н. э., праздники Диониса."}, {"q": "Что такое катарсис?", "o": ["Финальная битва", "Очищение души через сострадание и страх", "Вид стиха", "Хор в трагедии"], "a": 1, "e": "Так Аристотель описал действие трагедии на зрителя."}]}, {"id": "l2", "title": "Средневековье", "period": "V — XV век", "intro": ["Средневековая литература — это героический эпос, жития святых, рыцарские романы и летописи. У французов — «Песнь о Роланде», у немцев — «Песнь о Нибелунгах», у англичан — легенды о короле Артуре.", "На Руси главный памятник — «Слово о полку Игореве» (конец XII века): рассказ о неудачном походе князя Игоря на половцев и призыв князей к единству. Знаменит «Плач Ярославны».", "Вершина эпохи — «Божественная комедия» Данте (начало XIV века): путешествие поэта через Ад, Чистилище и Рай. Это и итог Средневековья, и первый шаг к Возрождению."], "traits": ["Героический эпос и рыцарский роман", "Религиозная литература, жития", "Древнерусская литература: летописи, «Слово»", "Аллегория и символ", "Данте — мост к Возрождению"], "works": [{"t": "Слово о полку Игореве", "a": "Неизвестный автор", "y": "конец XII века", "ws": "Слово о полку Игореве", "q": "Не лѣпо ли ны бяшетъ, братие, начяти старыми словесы трудныхъ повѣстий о пълку Игоревѣ, Игоря Святъславлича?", "d": "Поход 1185 года. Рукопись нашли в конце XVIII века, а в 1812 году она сгорела в московском пожаре."}, {"t": "Божественная комедия", "a": "Данте Алигьери (перевод Д. Мина)", "y": "1307–1321", "ws": "Божественная комедия (Данте; Мин)/ДО", "q": "Земную жизнь пройдя до половины,\nЯ очутился в сумрачном лесу…\n(перевод М. Лозинского)", "d": "Сто песен, девять кругов Ада. Проводник Данте — римский поэт Вергилий, а в Раю — возлюбленная Беатриче.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Portrait_de_Dante.jpg", "lic": "Public domain", "by": "Sandro Botticelli", "src": "media/img/03f2e287dc-360.webp", "w": 1000, "h": 1528, "remote": "https://upload.wikimedia.org/wikipedia/commons/6/6f/Portrait_de_Dante.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "О чём «Слово о полку Игореве»?", "o": ["О Куликовской битве", "О походе князя Игоря на половцев", "О крещении Руси", "О Ледовом побоище"], "a": 1, "e": "Поход 1185 года."}, {"q": "Кто ведёт Данте по Аду и Чистилищу?", "o": ["Гомер", "Вергилий", "Беатриче", "Овидий"], "a": 1, "e": "Вергилий, автор «Энеиды». В Раю его сменяет Беатриче."}, {"q": "Какой эпос — французский?", "o": ["«Песнь о Нибелунгах»", "«Песнь о Роланде»", "«Беовульф»", "«Калевала»"], "a": 1, "e": "«Песнь о Роланде», XI–XII век."}]}, {"id": "l3", "title": "Возрождение", "period": "XIV — начало XVII века", "intro": ["Гуманизм пришёл и в литературу. Петрарка написал сонеты к Лауре, Боккаччо — «Декамерон», сто живых и смешных новелл. Литература заговорила о земной любви и человеческой природе.", "Вершины позднего Возрождения — Шекспир и Сервантес (они умерли в один и тот же 1616 год). Шекспир создал «Гамлета», «Ромео и Джульетту», «Отелло», «Короля Лира», «Макбета» — героев, ставших архетипами. Сервантес написал «Дон Кихота» — первый великий роман Нового времени.", "Тургенев в знаменитой речи разделил людей на два типа: «Гамлеты» — сомневающиеся, и «Дон Кихоты» — верящие и действующие."], "traits": ["Гуманизм, земная любовь, личность", "Сонет: 14 строк (Петрарка, Шекспир)", "Новелла: Боккаччо", "Шекспир — вершина драмы", "Сервантес — рождение романа"], "works": [{"t": "Гамлет", "a": "Уильям Шекспир (перевод А. Кронеберга)", "y": "около 1600", "ws": "Гамлет (Шекспир; Кронеберг)", "q": "Быть или не быть — вот в чём вопрос.", "d": "Принц датский мстит за отца — и мучается сомнениями. Самая ставимая пьеса в мире.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Shakespeare.jpg", "lic": "Public domain", "by": "Attributed to John Taylor", "src": "media/img/91b93e3e9b-360.webp", "w": 1000, "h": 1275, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Shakespeare.jpg/1280px-Shakespeare.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ромео и Джульетта", "a": "Уильям Шекспир", "y": "1595", "ws": "Ромео и Джульетта (Шекспир)", "q": "Нет повести печальнее на свете,\nЧем повесть о Ромео и Джульетте.\n(перевод Т. Щепкиной-Куперник)", "d": "Любовь детей враждующих семей Вероны. Из этой пьесы выросли балет Прокофьева и множество фильмов.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Shakespeare.jpg", "lic": "Public domain", "by": "Attributed to John Taylor", "src": "media/img/91b93e3e9b-360.webp", "w": 1000, "h": 1275, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Shakespeare.jpg/1280px-Shakespeare.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Дон Кихот", "a": "Мигель де Сервантес", "y": "1605–1615", "ws": "Дон Кихот Ламанчский (Сервантес)", "q": "", "d": "Бедный идальго начитался рыцарских романов и отправился совершать подвиги со своим оруженосцем Санчо Пансой. Пародия, ставшая трагедией идеалиста.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Cervantes_J%C3%A1uregui.jpg", "lic": "Public domain", "by": "Attributed to Juan de Jáuregui", "src": "media/img/444076cb72-360.webp", "w": 1000, "h": 1312, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Cervantes_J%C3%A1uregui.jpg/1280px-Cervantes_J%C3%A1uregui.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Сколько строк в сонете?", "o": ["8", "12", "14", "16"], "a": 2, "e": "Сонет — 14 строк: Петрарка, Шекспир, Пушкин."}, {"q": "Кто написал «Дон Кихота»?", "o": ["Шекспир", "Сервантес", "Боккаччо", "Данте"], "a": 1, "e": "Мигель де Сервантес Сааведра."}, {"q": "Чьи слова «Быть или не быть»?", "o": ["Ромео", "Гамлета", "Макбета", "Отелло"], "a": 1, "e": "Монолог принца Гамлета, III акт."}]}, {"id": "l4", "title": "Классицизм и Просвещение", "period": "XVII — XVIII век", "intro": ["Классицизм в литературе — порядок и правила. Драма должна соблюдать три единства: места, времени и действия. Герои делятся на положительных и отрицательных, у них «говорящие» фамилии. Корнель и Расин писали трагедии, Мольер — комедии, высмеивающие пороки.", "XVIII век — эпоха Просвещения: вера в разум, науку и воспитание. Вольтер, Дидро, Руссо, Свифт («Путешествия Гулливера»). Гёте в Германии прошёл путь от бурных чувств к своему главному труду — «Фаусту».", "В России — Ломоносов, Державин, Фонвизин («Недоросль»). А в 1820-х Грибоедов в «Горе от ума» использует классицистические правила, но наполняет их живой современностью."], "traits": ["Правило трёх единств", "«Говорящие» фамилии, герои-маски", "Комедия высмеивает пороки (Мольер)", "Просвещение: вера в разум", "Гёте, Вольтер, Свифт, Фонвизин"], "works": [{"t": "Тартюф, или Обманщик", "a": "Мольер", "y": "1664", "ws": "Тартюф, или Обманщик (Мольер; Лихачёв)", "q": "", "d": "Лицемер-святоша втирается в доверие к богатому Оргону. Пьесу пять лет запрещали — церковь узнала себя.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_(1622-1673)_-_Google_Art_Project_(cropped).jpg", "lic": "Public domain", "by": "Pierre Mignard I", "src": "media/img/483bdcde10-360.webp", "w": 1000, "h": 1134, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_%281622-1673%29_-_Google_Art_Project_%28cropped%29.jpg/1280px-Pierre_Mignard_-_Portrait_de_Jean-Baptiste_Poquelin_dit_Moli%C3%A8re_%281622-1673%29_-_Google_Art_Project_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Кандид, или Оптимизм", "a": "Вольтер", "y": "1759", "ws": "Кандид, или Оптимизм (Вольтер; Сологуб)", "q": "", "d": "Философская повесть: наивный Кандид проходит через войны и бедствия, но учитель твердит, что «всё к лучшему в этом лучшем из миров». Финал: «надо возделывать свой сад».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Atelier_de_Nicolas_de_Largilli%C3%A8re,_portrait_de_Voltaire,_d%C3%A9tail_(mus%C3%A9e_Carnavalet)_-002.jpg", "lic": "Public domain", "by": "Nicolas de Largillière", "src": "media/img/75f8d54fe1-360.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Atelier_de_Nicolas_de_Largilli%C3%A8re%2C_portrait_de_Voltaire%2C_d%C3%A9tail_%28mus%C3%A9e_Carnavalet%29_-002.jpg/1280px-Atelier_de_Nicolas_de_Largilli%C3%A8re%2C_portrait_de_Voltaire%2C_d%C3%A9tail_%28mus%C3%A9e_Carnavalet%29_-002.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Фауст", "a": "Иоганн Вольфганг Гёте", "y": "1808–1832", "ws": "Фауст (Гёте)", "q": "Остановись, мгновенье, ты прекрасно!", "d": "Учёный продаёт душу Мефистофелю в обмен на мгновение полного счастья. Гёте писал «Фауста» почти 60 лет.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Goethe_(Stieler_1828).jpg", "lic": "Public domain", "by": "Joseph Karl Stieler", "src": "media/img/1b680922c8-360.webp", "w": 1000, "h": 1233, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Goethe_%28Stieler_1828%29.jpg/1280px-Goethe_%28Stieler_1828%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Горе от ума", "a": "Александр Грибоедов", "y": "1824", "ws": "Горе от ума (Грибоедов)", "q": "Карету мне, карету!", "d": "Чацкий возвращается в Москву и сталкивается с фамусовским обществом. Пушкин предсказал: половина стихов войдёт в пословицы. Так и вышло: «Счастливые часов не наблюдают»."}], "quiz": [{"q": "Что такое правило трёх единств?", "o": ["Три героя, три акта, три песни", "Единство места, времени и действия", "Три размера стиха", "Три рода литературы"], "a": 1, "e": "Действие пьесы — в одном месте, за сутки, с одной сюжетной линией."}, {"q": "Кому Фауст продаёт душу?", "o": ["Воланду", "Мефистофелю", "Люциферу", "Демону"], "a": 1, "e": "Мефистофель у Гёте — «часть силы той, что вечно хочет зла и вечно совершает благо»."}, {"q": "Кто главный герой «Горя от ума»?", "o": ["Онегин", "Чацкий", "Печорин", "Обломов"], "a": 1, "e": "Александр Андреевич Чацкий."}]}, {"id": "l5", "title": "Романтизм: от Байрона до Лермонтова", "period": "конец XVIII — середина XIX века", "intro": ["Романтики восстали против разума и правил. Их герой — одинокий бунтарь, изгнанник, мечтатель, в конфликте с обществом. Их темы — свобода, страсть, экзотика, природа, народные легенды, тайна.", "В Европе — Байрон (его «байронический герой» покорил всех), Вальтер Скотт (исторический роман), Гюго («Собор Парижской Богоматери»), Гофман, Эдгар По.", "В России романтизм начал Жуковский, его подхватили молодой Пушкин и Лермонтов. Но Пушкин быстро перерос романтизм: «Евгений Онегин» — уже реализм, «энциклопедия русской жизни» (Белинский). Лермонтов в «Герое нашего времени» создал первый русский психологический роман."], "traits": ["Романтический герой: одиночка и бунтарь", "Двоемирие: мечта против реальности", "Экзотика, история, фольклор", "Байрон, Гюго, Скотт, По", "Пушкин и Лермонтов — от романтизма к реализму"], "works": [{"t": "Евгений Онегин", "a": "Александр Пушкин", "y": "1823–1831", "ws": "Евгений Онегин (Пушкин)", "q": "Мой дядя самых честных правил,\nКогда не в шутку занемог,\nОн уважать себя заставил\nИ лучше выдумать не мог.", "d": "Роман в стихах. Пушкин придумал для него особую «онегинскую строфу» из 14 строк.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Капитанская дочка", "a": "Александр Пушкин", "y": "1836", "ws": "Капитанская дочка (Пушкин)", "q": "Береги честь смолоду.", "d": "Исторический роман о Пугачёвском бунте. Эпиграф — пословица, ставшая девизом героя Петра Гринёва.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Kiprensky_Pushkin.jpg", "lic": "Public domain", "by": "Orest Kiprensky", "src": "media/img/a9aa6bfcb8-360.webp", "w": 1000, "h": 1164, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Kiprensky_Pushkin.jpg/1280px-Kiprensky_Pushkin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Герой нашего времени", "a": "Михаил Лермонтов", "y": "1840", "ws": "Герой нашего времени (Лермонтов)", "q": "Я ехал на перекладных из Тифлиса.", "d": "Пять повестей о Печорине — «лишнем человеке», умном и разочарованном. Первый русский психологический роман.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mikhail_lermontov.jpg", "lic": "Public domain", "by": "Petr Zabolotskiy", "src": "media/img/90a19f9994-360.webp", "w": 1000, "h": 1288, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Mikhail_lermontov.jpg/1280px-Mikhail_lermontov.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Мцыри", "a": "Михаил Лермонтов", "y": "1839", "ws": "Мцыри (Лермонтов)", "q": "", "d": "Романтическая поэма: юноша-послушник бежит из монастыря на три дня свободы. Исповедь бунтаря.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Mikhail_lermontov.jpg", "lic": "Public domain", "by": "Petr Zabolotskiy", "src": "media/img/90a19f9994-360.webp", "w": 1000, "h": 1288, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Mikhail_lermontov.jpg/1280px-Mikhail_lermontov.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Собор Парижской Богоматери", "a": "Виктор Гюго", "y": "1831", "ws": "Собор Парижской Богоматери (Гюго)", "q": "", "d": "Эсмеральда, звонарь Квазимодо и мрачный Фролло. Роман спас собор: после него Париж начал реставрацию готического шедевра.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg", "lic": "Public domain", "by": "Étienne Carjat", "src": "media/img/6b06b66375-360.webp", "w": 1000, "h": 1230, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg/1280px-Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Ворон", "a": "Эдгар По (перевод В. Брюсова)", "y": "1845", "ws": "Ворон (По; Брюсов)", "q": "", "d": "Ночью к тоскующему по умершей Ленор приходит ворон и твердит одно слово: «Nevermore» — «никогда».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Edgar_Allan_Poe_daguerreotype_crop.png", "lic": "Public domain", "by": "Unknown authorUnknown author; most likely George C. Gilchrest, Samuel P. Howes, ", "src": "media/img/04d08822cc-360.webp", "w": 1000, "h": 1400, "remote": "https://upload.wikimedia.org/wikipedia/commons/8/84/Edgar_Allan_Poe_daguerreotype_crop.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "Кто назвал «Евгения Онегина» «энциклопедией русской жизни»?", "o": ["Гоголь", "Белинский", "Толстой", "Тургенев"], "a": 1, "e": "Критик Виссарион Белинский."}, {"q": "Какой роман считают первым русским психологическим романом?", "o": ["«Евгений Онегин»", "«Герой нашего времени»", "«Мёртвые души»", "«Обломов»"], "a": 1, "e": "Лермонтов, 1840 год, герой — Григорий Печорин."}, {"q": "Типичный романтический герой — это…", "o": ["Добропорядочный чиновник", "Одинокий бунтарь в конфликте с обществом", "Весёлый крестьянин", "Мудрый правитель"], "a": 1, "e": "Байронический герой: изгнанник, гордец, мечтатель."}, {"q": "Что твердит ворон в стихотворении Эдгара По?", "o": ["«Forever»", "«Nevermore»", "«Remember»", "«Goodbye»"], "a": 1, "e": "«Nevermore» — «никогда больше»."}]}, {"id": "l6", "title": "Реализм в Европе", "period": "XIX век", "intro": ["Реализм — главный стиль XIX века. Писатели изображают общество как оно есть: деньги, карьера, бедность, быт, характер, сформированный средой. Роман становится главным жанром.", "Франция: Бальзак задумал «Человеческую комедию» — около сотни романов о всём французском обществе. Флобер в «Госпоже Бовари» довёл стиль до совершенства. Стендаль, Мопассан, Золя.", "Англия: Джейн Остин с ироничными романами о браке и нравах, Диккенс с его сиротами, злодеями и сатирой, сёстры Бронте, Теккерей."], "traits": ["Типичные характеры в типичных обстоятельствах", "Социальная тема: деньги, классы, среда", "Роман — главный жанр", "Франция: Бальзак, Стендаль, Флобер", "Англия: Остин, Диккенс, Бронте"], "works": [{"t": "Шагреневая кожа", "a": "Оноре де Бальзак", "y": "1831", "ws": "Шагреневая кожа (Бальзак; Аверкиев)", "q": "", "d": "Талисман исполняет любое желание, но каждое желание сокращает кожу — и жизнь владельца. Философская притча о цене страстей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Honor%C3%A9_de_Balzac_(1842)_Detail.jpg", "lic": "Public domain", "by": "Louis-Auguste Bisson", "src": "media/img/7047817b44-360.webp", "w": 1000, "h": 909, "remote": "https://upload.wikimedia.org/wikipedia/commons/e/e6/Honor%C3%A9_de_Balzac_%281842%29_Detail.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Госпожа Бовари", "a": "Гюстав Флобер", "y": "1856", "ws": "Госпожа Бовари (Флобер; Ромм)", "q": "", "d": "Провинциальная жена врача мечтает о романтической жизни из книг. Флобер якобы сказал: «Эмма — это я».", "img": {"page": "https://commons.wikimedia.org/wiki/File:Gustave_Flaubert.jpg", "lic": "Public domain", "by": "Nadar", "src": "media/img/907809b4ae-360.webp", "w": 1000, "h": 1102, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/4f/Gustave_Flaubert.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Оливер Твист", "a": "Чарльз Диккенс", "y": "1838", "ws": "Оливер Твист (Диккенс)", "q": "", "d": "Сирота из работного дома попадает в банду лондонских воров. Диккенс заставил Англию увидеть детскую нищету.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Charles_Dickens_3.jpg", "lic": "Public domain", "by": "", "src": "media/img/310a6413ba-360.webp", "w": 1000, "h": 970, "remote": "https://upload.wikimedia.org/wikipedia/commons/4/48/Charles_Dickens_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "Как называется цикл романов Бальзака?", "o": ["«Ругон-Маккары»", "«Человеческая комедия»", "«В поисках утраченного времени»", "«Сага о Форсайтах»"], "a": 1, "e": "«Человеческая комедия» — отсылка к «Божественной комедии» Данте."}, {"q": "Какой жанр — главный для реализма?", "o": ["Ода", "Роман", "Сонет", "Трагедия"], "a": 1, "e": "Роман позволяет показать общество широко и подробно."}, {"q": "Кто автор «Оливера Твиста»?", "o": ["Теккерей", "Диккенс", "Остин", "Скотт"], "a": 1, "e": "Чарльз Диккенс."}]}, {"id": "l7", "title": "Золотой век русской прозы", "period": "1840 — 1880-е", "intro": ["Во второй половине XIX века русская литература стала мировой. Гоголь открыл «маленького человека» и сатиру на чиновничью Россию. Тургенев создал портреты поколений и «тургеневских девушек». Гончаров — Обломова, Островский — русский театр.", "Два гиганта — Достоевский и Толстой. Достоевский — бездны человеческой души, преступление и вера, споры о Боге («Преступление и наказание», «Идиот», «Братья Карамазовы»). Толстой — огромная панорама жизни, «диалектика души», поиск смысла («Война и мир», «Анна Каренина»).", "Главные темы: «маленький человек», «лишний человек», вопрос «кто виноват?» и «что делать?», судьба народа, нравственный выбор."], "traits": ["«Маленький человек» (Гоголь)", "«Лишний человек» (Онегин, Печорин, Обломов)", "Психологизм: «диалектика души»", "Нравственные и религиозные вопросы", "Гоголь, Тургенев, Достоевский, Толстой"], "works": [{"t": "Шинель", "a": "Николай Гоголь", "y": "1842", "ws": "Шинель (Гоголь)", "q": "", "d": "Бедный чиновник Акакий Акакиевич копит на новую шинель — и её крадут. Классическая повесть о «маленьком человеке».", "img": {"page": "https://commons.wikimedia.org/wiki/File:N.Gogol_by_F.Moller_(1840,_Tretyakov_gallery).jpg", "lic": "Public domain", "by": "Otto Friedrich Theodor von Möller", "src": "media/img/c7c19e60d6-360.webp", "w": 1000, "h": 1261, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg/1280px-N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Мёртвые души", "a": "Николай Гоголь", "y": "1842", "ws": "Мёртвые души (Гоголь)", "q": "И какой же русский не любит быстрой езды?", "d": "Чичиков скупает умерших крестьян, числящихся живыми. Галерея помещиков — Манилов, Коробочка, Ноздрёв, Собакевич, Плюшкин.", "img": {"page": "https://commons.wikimedia.org/wiki/File:N.Gogol_by_F.Moller_(1840,_Tretyakov_gallery).jpg", "lic": "Public domain", "by": "Otto Friedrich Theodor von Möller", "src": "media/img/c7c19e60d6-360.webp", "w": 1000, "h": 1261, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg/1280px-N.Gogol_by_F.Moller_%281840%2C_Tretyakov_gallery%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Отцы и дети", "a": "Иван Тургенев", "y": "1862", "ws": "Отцы и дети (Тургенев)", "q": "Природа не храм, а мастерская, и человек в ней работник.", "d": "Нигилист Базаров против «отцов»-либералов. Конфликт поколений, который вечно актуален.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Turgenev_by_Repin.jpg", "lic": "Public domain", "by": "Ilya Repin", "src": "media/img/c3e7d708bf-360.webp", "w": 1000, "h": 1304, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Turgenev_by_Repin.jpg/1280px-Turgenev_by_Repin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Преступление и наказание", "a": "Фёдор Достоевский", "y": "1866", "ws": "Преступление и наказание (Достоевский)", "q": "Тварь ли я дрожащая или право имею…", "d": "Студент Раскольников убивает старуху-процентщицу, чтобы проверить свою теорию. Роман о совести и искуплении.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg", "lic": "Public domain", "by": "Vasily Perov", "src": "media/img/223d7771e2-360.webp", "w": 1000, "h": 1250, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg/1280px-Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Война и мир", "a": "Лев Толстой", "y": "1865–1869", "ws": "Война и мир", "q": "— Eh bien, mon prince. Gênes et Lucques ne sont plus que des apanages…", "d": "Роман-эпопея о войне 1812 года: Наташа Ростова, Пьер Безухов, Андрей Болконский. Около 600 персонажей.", "img": {"page": "https://commons.wikimedia.org/wiki/File:L.N.Tolstoy_Prokudin-Gorsky.jpg", "lic": "Public domain", "by": "Sergei Prokudin-Gorskii", "src": "media/img/a7a4c71e8c-360.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/L.N.Tolstoy_Prokudin-Gorsky.jpg/1280px-L.N.Tolstoy_Prokudin-Gorsky.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}, {"t": "Анна Каренина", "a": "Лев Толстой", "y": "1878", "ws": "Анна Каренина (Толстой)", "q": "Все счастливые семьи похожи друг на друга, каждая несчастливая семья несчастлива по-своему.", "d": "Две линии: трагическая любовь Анны и Вронского и поиски смысла Константином Лёвиным.", "img": {"page": "https://commons.wikimedia.org/wiki/File:L.N.Tolstoy_Prokudin-Gorsky.jpg", "lic": "Public domain", "by": "Sergei Prokudin-Gorskii", "src": "media/img/a7a4c71e8c-360.webp", "w": 1000, "h": 1384, "remote": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/L.N.Tolstoy_Prokudin-Gorsky.jpg/1280px-L.N.Tolstoy_Prokudin-Gorsky.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}}], "quiz": [{"q": "Кто главный герой «Шинели»?", "o": ["Чичиков", "Акакий Акакиевич", "Раскольников", "Базаров"], "a": 1, "e": "Акакий Акакиевич Башмачкин."}, {"q": "Кем называет себя Базаров?", "o": ["Романтиком", "Нигилистом", "Славянофилом", "Декабристом"], "a": 1, "e": "Нигилист — человек, который ничего не принимает на веру."}, {"q": "Какая война в центре «Войны и мира»?", "o": ["Крымская", "Отечественная 1812 года", "Русско-турецкая", "Первая мировая"], "a": 1, "e": "Наполеоновские войны и 1812 год."}, {"q": "Что скупает Чичиков?", "o": ["Землю", "Мёртвые души — умерших крестьян", "Лошадей", "Картины"], "a": 1, "e": "Чтобы заложить их как живых в Опекунский совет."}]}, {"id": "l8", "title": "Чехов и Серебряный век", "period": "1880 — 1920-е", "intro": ["Антон Чехов изменил и прозу, и театр. Короткий рассказ, где «краткость — сестра таланта», и пьесы, где главное не в событиях, а в подтексте и настроении («Чайка», «Три сестры», «Вишнёвый сад»).", "Рубеж веков — Серебряный век русской поэзии. Символисты (Блок, Брюсов, Бальмонт) видят за миром тайну. Акмеисты (Гумилёв, Ахматова, Мандельштам) возвращают ясность и вещность. Футуристы (Маяковский, Хлебников) ломают язык. Отдельно стоят Цветаева, Есенин, Пастернак.", "Часть поэтов этой эпохи (Ахматова, Пастернак, Мандельштам) ещё охраняется авторским правом или их тексты ещё не попали в свободную библиотеку, поэтому здесь — те, кого уже можно читать свободно."], "traits": ["Чехов: подтекст, «краткость — сестра таланта»", "Символизм: Блок, Брюсов, Бальмонт", "Акмеизм: Гумилёв, Ахматова, Мандельштам", "Футуризм: Маяковский, Хлебников", "Цветаева, Есенин, Пастернак"], "works": [{"t": "Палата № 6", "a": "Антон Чехов", "y": "1892", "ws": "Палата № 6 (Чехов)", "q": "", "d": "Врач провинциальной больницы спорит с пациентом о страдании и сам оказывается в палате для душевнобольных. Ленин, прочитав, сказал, что почувствовал себя запертым в палате.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Anton_Chekhov_with_bow-tie_sepia_image.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/45a6b0ec50-360.webp", "w": 1000, "h": 1416, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Anton_Chekhov_with_bow-tie_sepia_image.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Вишнёвый сад", "a": "Антон Чехов", "y": "1903", "ws": "Вишнёвый сад (Чехов)", "q": "Вся Россия наш сад.", "d": "Имение продают за долги, сад вырубают. Чехов называл пьесу комедией, а МХТ поставил её как драму.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Anton_Chekhov_with_bow-tie_sepia_image.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/45a6b0ec50-360.webp", "w": 1000, "h": 1416, "remote": "https://upload.wikimedia.org/wikipedia/commons/c/c0/Anton_Chekhov_with_bow-tie_sepia_image.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Незнакомка", "a": "Александр Блок", "y": "1906", "ws": "Незнакомка (Блок)", "q": "По вечерам над ресторанами\nГорячий воздух дик и глух…", "d": "Символизм: в пошлом загородном кабаке поэту является прекрасная Незнакомка — мечта или видение?", "img": {"page": "https://commons.wikimedia.org/wiki/File:Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg", "lic": "Public domain", "by": "ru:Пархоменко, Иван Кириллович (1870-1940)", "src": "media/img/cee87e8a47-360.webp", "w": 1000, "h": 1113, "remote": "https://upload.wikimedia.org/wikipedia/commons/7/71/Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Двенадцать", "a": "Александр Блок", "y": "1918", "ws": "Двенадцать (Блок)", "q": "Черный вечер.\nБелый снег.\nВетер, ветер!", "d": "Поэма о революционном Петрограде: двенадцать красногвардейцев идут сквозь метель, а впереди — неожиданно — Христос.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg", "lic": "Public domain", "by": "ru:Пархоменко, Иван Кириллович (1870-1940)", "src": "media/img/cee87e8a47-360.webp", "w": 1000, "h": 1113, "remote": "https://upload.wikimedia.org/wikipedia/commons/7/71/Alexander_Blok_by_Ivan_Parkhomenko_1910.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}, {"t": "Мне нравится, что вы больны не мной…", "a": "Марина Цветаева", "y": "1915", "ws": "Мне нравится, что Вы больны не мной (Цветаева)", "q": "Мне нравится, что вы больны не мной,\nМне нравится, что я больна не вами…", "d": "Нежное и ироничное стихотворение, ставшее песней в фильме «Ирония судьбы»."}, {"t": "Письмо матери", "a": "Сергей Есенин", "y": "1924", "ws": "Письмо матери (Есенин)", "q": "Ты жива еще, моя старушка?\nЖив и я. Привет тебе, привет!", "d": "Исповедь блудного сына. Простые слова, песенная интонация — фирменный голос Есенина.", "img": {"page": "https://commons.wikimedia.org/wiki/File:Sergey_Yesenin_2.jpg", "lic": "Public domain", "by": "Unknown authorUnknown author", "src": "media/img/8d42bf61f2-360.webp", "w": 1000, "h": 1332, "remote": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Sergey_Yesenin_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"}}], "quiz": [{"q": "Кому принадлежат слова «Краткость — сестра таланта»?", "o": ["Толстому", "Чехову", "Гоголю", "Блоку"], "a": 1, "e": "Из письма Чехова брату Александру, 1889."}, {"q": "Блок — представитель какого направления?", "o": ["Акмеизма", "Символизма", "Футуризма", "Реализма"], "a": 1, "e": "Главный поэт русского символизма."}, {"q": "Кто из поэтов — футурист?", "o": ["Есенин", "Маяковский", "Гумилёв", "Цветаева"], "a": 1, "e": "Маяковский и Хлебников — лидеры русского футуризма."}, {"q": "Что происходит в «Вишнёвом саде»?", "o": ["Свадьба", "Имение с садом продают за долги", "Дуэль", "Революция"], "a": 1, "e": "Сад покупает Лопахин, сын бывшего крепостного."}]}]};
